export function isUiModalVisible(el: Element | null | undefined): boolean {
    if (!el) return false;
    const style = window.getComputedStyle(el);
    if (style.display === 'none' || style.visibility === 'hidden') return false;
    const rect = el.getBoundingClientRect();
    return rect.width > 0 && rect.height > 0;
}

export function getTopmostVisibleModalUI() {
    const selector = [
        '#saveSlotBootModal',
        '.js-modal-overlay',
        '.compact-popup',
        '.stats-modal',
        '.modal',
        '.modal-overlay',
        '.quest-completion-modal',
        '.talent-action-modal',
        '.talent-choice-modal',
        '.talent-change-juice'
    ].join(', ');

    const seen = new Set();
    return Array.from(document.querySelectorAll(selector))
        .filter((el) => {
            if (!el || seen.has(el)) return false;
            seen.add(el);
            if (el.hasAttribute('inert') || el.getAttribute('aria-hidden') === 'true') return false;
            return isUiModalVisible(el);
        })
        .map((el, index) => {
            const zIndex = Number.parseInt(window.getComputedStyle(el).zIndex, 10);
            return {
                el,
                index,
                zIndex: Number.isFinite(zIndex) ? zIndex : 0
            };
        })
        .sort((a, b) => {
            if (a.zIndex !== b.zIndex) return a.zIndex - b.zIndex;
            return a.index - b.index;
        })
        .map(entry => entry.el)
        .pop() || null;
}

export function closeTopmostModalUI() {
    const modal = getTopmostVisibleModalUI();
    if (!modal) return false;

    const closeTarget = modal.querySelector([
        '[data-action^="close"]',
        '[data-action="skipCapture"]',
        '[data-action="removeTalentActionModal"]',
        '.btn-talent-choice-cancel',
        '.btn-talent-juice-close',
        '.talent-action-cancel',
        '.stats-close',
        '.close-btn',
        '.close-modal'
    ].join(', '));

    if (isHtmlButtonElement(closeTarget) && !closeTarget.disabled) {
        closeTarget.click();
        return true;
    }

    if (modal instanceof HTMLElement) {
        modal.click();
        return !isUiModalVisible(modal) || !document.body.contains(modal);
    }

    return false;
}

