/**
 * Affiche un message dans le journal de combat (modal log).
 * @param {string} msg - Le message à afficher
 */
export function logMessage(msg: string): void {
    if (typeof game !== 'undefined' && game && game.suppressLogs) return;
    const container = document.getElementById('gameLog');
    if (!container) return;

    const div = document.createElement('div');
    div.className = 'log-entry';

    const locale = ((typeof game !== 'undefined' && game && String(game.language || 'fr').toLowerCase().startsWith('en')) ? 'en-US' : 'fr-FR');
    const time = new Date().toLocaleTimeString(locale);
    div.innerHTML = `<span class="log-time">[${time}]</span> ${msg}`;

    container.appendChild(div);

    // Nettoyage (Max 50 lignes pour perf)
    if (container.children.length > 50) {
        const firstLog = container.firstChild;
        if (firstLog) container.removeChild(firstLog);
    }

    // Auto-scroll si le modal log est ouvert
    const logModal = document.getElementById('logModal');
    if (logModal && logModal.classList.contains('show')) {
        container.scrollTop = container.scrollHeight;
    }
}

