    const displayName = uiPokemonName(null, data?.name ?? '');
    const rarityKey = (data.rarity && data.rarity !== 'undefined') ? data.rarity : 'common';
    const rarityLabel = data.rarityBadgeLabel || data.rarityLabel || data.rarity || '';
