/**
 * Génère le HTML du contenu du modal bonus de collection.
 * @param {Object} data - { familyName, level, isNewCompletion, members: [{name, prestige, status}], effectTexts, bonusPerPrestige }
 * @returns {string} HTML
 */
export function renderCollectionBonusModalContent(data: CollectionBonusModalData): string {
    const title = data.isNewCompletion
        ? uiText('modal.collectionCompleted')
        : uiText('modal.collectionLevelUp');
    const subtitle = data.isNewCompletion
        ? uiText('modal.collectionUnlocked', null, { name: data.familyName })
        : uiText('modal.collectionLeveled', null, { name: data.familyName, level: data.level });
    const membersHTML = (data.members || []).map((m: CollectionBonusMember) => {
        const memberDisplayName = uiPokemonName(null, m.name);
        const showShiny = !!(m.shinyRequired || m.status === 'needs_shiny');
        const spriteUrl = getPokemonSpriteUrl(m.name, showShiny);
        const statusClass = m.status === 'missing'
            ? ' is-missing'
            : (m.status === 'needs_shiny'
                ? ' is-needs-shiny'
                : (m.status === 'prestige_0' ? ' is-prestige-0' : ''));
        const badge = m.status === 'ok'
            ? formatPrestigeSuffixHtml(m.prestige ?? 0)
            : (m.status === 'prestige_0' ? '0' : (m.status === 'needs_shiny' ? '✦' : '-'));
        return `<div class="collection-member${statusClass}" title="${memberDisplayName}${m.status === 'ok' ? formatPrestigeSuffixSpaced(m.prestige ?? 0) : ''}">
            <img src="${spriteUrl}" alt="${memberDisplayName}">
            <span>${badge}</span>
        </div>`;
    }).join('');
    const effectStr = (data.effectTexts && data.effectTexts.length) ? data.effectTexts.join(', ') : (data.bonusPerPrestige || '-');
    return `
        <div class="collection-bonus-modal-title">${title}</div>
        <div class="collection-bonus-modal-subtitle">${subtitle}</div>
        <div class="collection-bonus-modal-grid">${membersHTML}</div>
        <div class="collection-bonus-modal-effects">
            <strong>${uiText('modal.collectionActiveBonus')}</strong> ${effectStr}
        </div>
        <button type="button" class="btn btn-collection-bonus-close" data-action="closeCollectionBonusModal">${uiText('egg.confirm')}</button>
    `;
}

/**
 * Affiche le modal bonus de collection.
 */
export function showCollectionBonusModalUI(modalEl: HTMLElement | null, contentEl: HTMLElement | null, data: CollectionBonusModalData): void {
    if (!modalEl || !contentEl) return;
    contentEl.innerHTML = renderCollectionBonusModalContent(data);
    modalEl.classList.add('show');
}

/**
 * Ferme le modal bonus de collection.
 */
export function closeCollectionBonusModalUI() {
    const modal = document.getElementById('collectionBonusModal');
    if (modal) modal.classList.remove('show');
}

