/**
 * Affiche un toast épique pour le drop d'objets rares / légendaires.
 * @param {string} itemKey - La clé de l'objet dans ALL_ITEMS
 */
export function showRareItemToast(itemKey: string): void {
    const item = getAllItem(itemKey);
    if (!item) return;
    const displayItemName = uiMaybeLocalizeItemName((typeof game !== 'undefined' ? game : null), item, itemKey, item.name || itemKey);

    let container = document.getElementById('toastContainer');
    if (!container) {
        container = document.createElement('div');
        container.id = 'toastContainer';
        container.className = 'toastContainer';
        document.body.appendChild(container);
    }

    const toastDiv = document.createElement('div');
    toastDiv.className = 'toast show';

    // Style très distinctif pour "l'ultra rare"
    toastDiv.style.background = 'linear-gradient(135deg, rgba(30,20,50,0.95), rgba(70,30,110,0.95))';
    toastDiv.style.borderLeft = '6px solid #fbbf24';
    toastDiv.style.boxShadow = '0 8px 30px rgba(0,0,0,0.5), 0 0 15px rgba(251, 191, 36, 0.4)';
    toastDiv.style.minWidth = '280px';
    toastDiv.style.padding = '15px';
    toastDiv.style.display = 'flex';
    toastDiv.style.alignItems = 'center';
    toastDiv.style.gap = '15px';

    const imageHTML = item.img ?
        `<img src="${item.img}" class="item-sprite-img${getTimeDustGlowClass(item)}" style="width: 48px; height: 48px; object-fit: contain;">` :
        `<div style="font-size: 32px; filter: drop-shadow(0 0 5px rgba(255,255,255,0.8));">${item.icon || 'OBJ'}</div>`;

    const rarityLabel = (typeof game !== 'undefined' && game && typeof game.getRarityLabel === 'function')
        ? game.getRarityLabel(item.rarity)
        : (item.rarity === 'epic' ? 'Epic' : 'Legendary');

    toastDiv.innerHTML = `
        ${imageHTML}
        <div style="flex-grow: 1;">
            <div style="color: #fbbf24; font-size: 11px; text-transform: uppercase; letter-spacing: 1px; font-weight: bold; margin-bottom: 2px;">
                ${uiText('toast.rareDropInline', 'Drop {rarity} !', { rarity: rarityLabel })}
            </div>
            <div style="color: white; font-weight: bold; font-size: 16px;">${displayItemName}</div>
        </div>
    `;

    container.appendChild(toastDiv);

    // Animation de suppression
    setTimeout(() => {
        toastDiv.classList.remove('show');
        toastDiv.style.opacity = '0';
        toastDiv.style.transform = 'translateX(100%)';
        setTimeout(() => {
            if (toastDiv.parentNode === container) {
                container.removeChild(toastDiv);
            }
        }, 300);
    }, 3500); // Reste 3.5 sec
}

