/**
 * Affiche le modal de sélection d'objet à équiper.
 * @param {Array<{itemKey:string, name:string, description:string, count:number, iconHtml:string}>} itemsData
 * @param {number} creatureIndex
 * @param {string} location - 'team' | 'storage' | 'pension'
 * @param {ItemSelectCreatureInfo} [creatureInfo]
 */
export function showItemSelectModalUI(
    itemsData: ItemSelectRow[],
    creatureIndex: number,
    location: string,
    creatureInfo?: ItemSelectCreatureInfo | null,
): void {
    const existingOverlay = document.getElementById('itemSelectOverlay');
    if (existingOverlay) existingOverlay.remove();

    const modal = document.createElement('div');
    modal.id = 'itemSelectOverlay';
    modal.className = 'stats-modal show item-select-modal';
    modal.style.zIndex = '10001';
    modal.onclick = function (e) { if (e.target === modal) modal.remove(); };

    const gameRef = typeof game !== 'undefined' ? game : null;
    const isFrench = !uiIsEn(gameRef);

    interface ProcessedItemRow {
        item: ItemSelectRow;
        displayName: string;
        displayDescription: string;
        relevance: HeldItemRelevanceResult;
    }

    const processedItems: ProcessedItemRow[] = itemsData.map((item) => {
        const fallbackDef = item.itemKey ? getAllItem(item.itemKey) : null;
        const heldDef = item.itemKey ? getHeldItem(item.itemKey) : null;
        const itemDef = heldDef || fallbackDef || {};
        const displayName =
            gameRef && typeof gameRef.getLocalizedItemName === 'function'
                ? gameRef.getLocalizedItemName(item.itemKey, item.name || '', itemDef)
                : uiMaybeLocalizeItemName(gameRef, itemDef, item.itemKey, item.name);
        const rawDescription =
            gameRef && typeof gameRef.getLocalizedItemDescription === 'function'
                ? gameRef.getLocalizedItemDescription(item.itemKey, item.description || '', itemDef)
                : uiMaybeLocalizeItemDescription(gameRef, itemDef, item.itemKey, item.description || '');
        const displayDescription = formatPercentInText(rawDescription || '', { isFrench, html: true });
        const relevance = evaluateHeldItemRelevance(
            item.itemKey,
            itemDef,
            creatureInfo,
            isFrench,
            (moveId: string) => (gameRef && typeof gameRef.getLocalizedMoveName === 'function' ? gameRef.getLocalizedMoveName(moveId) : ''),
        );
        return { item, displayName, displayDescription, relevance };
    });

    // Tri : recommandés / boosts utiles d'abord, puis stats/utilitaires, puis sans effet, puis stock décroissant
    processedItems.sort((a, b) => {
        if (a.relevance.priority !== b.relevance.priority) {
            return a.relevance.priority - b.relevance.priority;
        }
        if (b.item.count !== a.item.count) {
            return b.item.count - a.item.count;
        }
        return a.displayName.localeCompare(b.displayName);
    });

    let replacementBannerHtml = '';
    if (creatureInfo && creatureInfo.heldItem) {
        const currentHeldName = creatureInfo.heldItemName || creatureInfo.heldItem;
        const currentHeldDesc = creatureInfo.heldItemDescription
            ? `<span class="item-replacement-desc">(${formatPercentInText(creatureInfo.heldItemDescription, { isFrench, html: true })})</span>`
            : '';
        replacementBannerHtml = `
            <div class="item-replacement-banner">
                <span class="item-replacement-lead">${uiText('modal.itemReplacesLead', 'Remplace actuellement :')}</span>
                <span class="item-replacement-name">${currentHeldName}</span>
                ${currentHeldDesc}
                <span class="item-replacement-return">${uiText('modal.itemSafeReturn', "L'ancien objet retournera immédiatement dans votre sac.")}</span>
            </div>
        `;
    }

    const toolbarHtml = `
        <div class="item-select-toolbar">
            <div class="item-select-search-wrap">
                <input type="text" id="itemSelectSearchInput" class="item-select-search-input" placeholder="${uiText('modal.itemSearchPlaceholder', 'Rechercher un objet...')}" autocomplete="off" />
            </div>
            <div class="item-select-tabs" role="tablist">
                <button type="button" class="item-select-tab active" data-filter="all">${uiText('modal.itemFilterAll', 'Tous')}</button>
                <button type="button" class="item-select-tab" data-filter="moves">${uiText('modal.itemFilterMoves', 'Attaques')}</button>
                <button type="button" class="item-select-tab" data-filter="stats">${uiText('modal.itemFilterStats', 'Stats & Utilitaires')}</button>
            </div>
        </div>
    `;

    let listHTML = '';
    if (processedItems.length === 0) {
        listHTML = `
            <div class="item-select-empty">
                <div class="item-select-empty-icon">OBJ</div>
                <div>${uiText('modal.itemNone')}</div>
                <div class="item-select-empty-hint">${uiText('modal.itemHint')}</div>
            </div>
        `;
    } else {
        processedItems.forEach(({ item, displayName, displayDescription, relevance }) => {
            const cardClasses = ['item-select-card'];
            if (relevance.status === 'boost') {
                cardClasses.push('item-recommended');
            } else if (relevance.status === 'dimmed') {
                cardClasses.push('item-dimmed');
            }

            let typeBadgeHtml = '';
            if (relevance.tagType) {
                const typeLabel = formatPokemonTypeLabel(relevance.tagType);
                typeBadgeHtml = `<span class="type-badge type type-${relevance.tagType}" style="font-size:9px; padding:1px 5px; border-radius:2px; text-transform:uppercase; margin:0 4px 0 0;">${typeLabel}</span>`;
            }

            const relevancePillHtml = relevance.tag
                ? `<span class="item-relevance-pill ${relevance.status}">${typeBadgeHtml}${relevance.tag}</span>`
                : '';

            listHTML += `
                <div class="${cardClasses.join(' ')}"
                     data-action="equipItem" data-arg="${item.itemKey}" data-arg2="${creatureIndex}" data-arg3="${location}"
                     data-item-key="${item.itemKey}"
                     data-item-name="${displayName.toLowerCase()}"
                     data-filter-category="${relevance.filterCategory}"
                     data-relevance-status="${relevance.status}">
                    <div class="item-select-icon">${item.iconHtml}</div>
                    <div class="item-select-main">
                        <div class="item-select-header-row">
                            <span class="item-select-name">${displayName}</span>
                            <span class="item-select-count font-num">×${item.count}</span>
                            ${relevancePillHtml}
                        </div>
                        <div class="item-select-desc">${displayDescription}</div>
                    </div>
                    <button type="button" class="btn-2 item-equip-btn" data-action="equipItem" data-arg="${item.itemKey}" data-arg2="${creatureIndex}" data-arg3="${location}">${uiText('modal.itemEquip', 'Équiper')}</button>
                </div>
            `;
        });

        listHTML += `
            <div class="item-select-search-empty" id="itemSelectSearchEmpty" style="display:none;">
                ${uiText('modal.itemFilterEmpty', 'Aucun objet ne correspond à votre recherche.')}
            </div>
        `;
    }

    const headerHtml = creatureInfo
        ? buildSubModalHeaderHtml({
            title: uiText('modal.itemSelectTitle', 'Held item'),
            pokemonName: creatureInfo.displayName,
            pokemonSpriteUrl: creatureInfo.spriteUrl,
            closeAction: 'closeItemSelectOverlay',
            closeAriaLabel: uiText('modal.close', 'Fermer'),
        })
        : `
        <div class="stats-header">
            <h2>${uiText('modal.itemSelectTitle')}</h2>
            <button class="stats-close" data-action="closeItemSelectOverlay">&#10005;</button>
        </div>
        `;

    const content = `
        <div class="stats-content item-select-content submodal-list-content" data-action="stopPropagation" data-action-stop>
            ${headerHtml}
            ${replacementBannerHtml}
            ${toolbarHtml}
            <div class="item-select-list">
                ${listHTML}
            </div>
        </div>
    `;
    modal.innerHTML = content;
    document.body.appendChild(modal);

    // Interactive filter & search logic
    const searchInput = modal.querySelector<HTMLInputElement>('#itemSelectSearchInput');
    const tabs = modal.querySelectorAll<HTMLButtonElement>('.item-select-tab');
    const cards = modal.querySelectorAll<HTMLElement>('.item-select-card');
    const emptyNotice = modal.querySelector<HTMLElement>('#itemSelectSearchEmpty');

    let currentFilter = 'all';

    const applyFilter = () => {
        const query = (searchInput?.value || '').trim().toLowerCase();
        let visibleCount = 0;

        cards.forEach((card) => {
            const cardName = card.dataset.itemName || '';
            const cardCat = card.dataset.filterCategory || '';
            const cardStatus = card.dataset.relevanceStatus || '';

            const matchesQuery = !query || cardName.includes(query) || (card.textContent || '').toLowerCase().includes(query);
            let matchesTab = true;
            if (currentFilter === 'moves') {
                matchesTab = cardCat === 'moves' || cardStatus === 'boost';
            } else if (currentFilter === 'stats') {
                matchesTab = cardCat === 'stats';
            }

            if (matchesQuery && matchesTab) {
                card.style.display = 'flex';
                visibleCount++;
            } else {
                card.style.display = 'none';
            }
        });

        if (emptyNotice) {
            emptyNotice.style.display = (visibleCount === 0 && cards.length > 0) ? 'block' : 'none';
        }
    };

    if (searchInput) {
        searchInput.addEventListener('input', applyFilter);
    }

    tabs.forEach((tab) => {
        tab.addEventListener('click', () => {
            tabs.forEach((t) => t.classList.remove('active'));
            tab.classList.add('active');
            currentFilter = tab.dataset.filter || 'all';
            applyFilter();
        });
    });

    registerSubModal(modal);
}

export function closeStatsBreakdownModalUI() {
    const modal = document.getElementById('statsBreakdownOverlay');
    if (modal) modal.remove();
}

function megaVariantOptionLabel(key: string): string {
    if (key === 'X') return uiText('mega.formX', 'Méga X');
    if (key === 'Y') return uiText('mega.formY', 'Méga Y');
    if (key === 'Z') return uiText('mega.formZ', 'Méga Z');
    if (key === 'default') return uiText('mega.formDefault', 'Méga (classique)');
    return key;
}

/**
 * Sélecteur de variante méga (X/Y, default/Z, etc.) lorsque la pierre est débloquée.
 */
export function buildMegaVariantSelectHtml(creature: CreatureData, index: number, location: string): string {
    if (!creature || !creature.megaStoneUnlocked) return '';
    const variantKeys = getMegaVariantKeys(String(creature.name || ''));
    if (variantKeys.length === 0) return '';
    const cur = String(creature.megaVariant || variantKeys[0]);
    const lab = uiText('mega.variantLabel', 'Forme méga');
    const hintEsc = String(uiText('mega.variantHint', '')).replace(/"/g, '&quot;');
    const ix = Number.isFinite(Number(index)) ? Number(index) : 0;
    const loc = String(location || 'team');
    const options = variantKeys.map((key) => {
        const escKey = key.replace(/"/g, '&quot;');
        const selected = cur === key ? ' selected' : '';
        return `<option value="${escKey}"${selected}>${megaVariantOptionLabel(key)}</option>`;
    }).join('');
    return `
        <div class="mega-variant-select-wrap">
            <label class="mega-variant-select-label">${lab}
                <select class="mega-variant-select" data-action="setCreatureMegaVariant" data-arg="${ix}" data-arg2="${loc.replace(/"/g, '&quot;')}" title="${hintEsc}">
                    ${options}
                </select>
            </label>
        </div>`;
}

/**
 * Affiche le modal "Détails des stats" : explique comment chaque stat finale est obtenue
 * (base de l'espèce, IVs, Pokérus, multiplicateurs de rareté/prestige/shiny/zone, synergies,
 * jetons de prestige, talent Muraille, statut Shadow…) et l'apport réel des IVs / Pokérus.
 *
 * @param {Object} payload - sortie de Creature.getStatsBreakdown() + creatureName + spriteUrl
 */
export function showStatsBreakdownModalUI(payload: StatsBreakdownPayload): void {
    closeStatsBreakdownModalUI();
    if (!payload || !payload.stats || !payload.meta) return;

    const meta = payload.meta;
    const stats = payload.stats;
    const variants = payload.variants || {};

    const fmtNum = (n: number) => formatNumber(Math.round(n));
    const fmtMult = (n: number) => `×${(Math.round(n * 1000) / 1000).toFixed(3).replace(/0+$/, '').replace(/\.$/, '')}`;
    const fmtPct = (n: number) => `${n >= 0 ? '+' : ''}${(n * 100).toFixed(1)}%`;
    const fmtSigned = (n: number) => (n >= 0 ? '+' : '') + fmtNum(n);

    const statCssVarMap: Record<StatBreakdownKey, string> = {
        hp:        'var(--s-hp, #ef4444)',
        attack:    'var(--s-atk, #f59e0b)',
        spattack:  'var(--s-atksp, #ec4899)',
        defense:   'var(--s-def, #4a7c23)',
        spdefense: 'var(--s-defsp, #10b981)',
        speed:     'var(--s-spd, #8b5cf6)',
    };

    const statLabels: Record<StatBreakdownKey, { label: string; icon: string }> = {
        hp:        { label: uiText('modal.creature.hpFull', 'PV'),                     icon: '&#10084;&#65039;' },
        attack:    { label: uiText('modal.creature.atkShort', 'ATK'),                  icon: '&#9876;&#65039;'  },
        spattack:  { label: uiText('modal.creature.spAtkShort', 'ATK SP'),             icon: '&#128165;'        },
        defense:   { label: uiText('modal.creature.defShort', 'DEF'),                  icon: '&#128737;&#65039;' },
        spdefense: { label: uiText('modal.creature.spDefShort', 'DEF SP'),             icon: '&#128160;'        },
        speed:     { label: uiText('modal.creature.speedShort', 'SPD'),                icon: '&#128095;'        }
    };

    const tHeaderTitle    = uiText('modal.statsBreakdown.title', 'Détails des stats');
    const tIntro          = uiText('modal.statsBreakdown.intro', 'Origine de chaque stat finale pour ce Pokémon.');

    const tBase           = uiText('modal.statsBreakdown.base', 'Base espèce (niv. {level})', { level: meta.level });
    const tIv             = uiText('modal.statsBreakdown.iv', 'IV ({val}/{max})');
    const tIvWithMult     = uiText('modal.statsBreakdown.ivWithMult', 'IV ({val}/{max}) × {mult} prestige');
    const tPokerus        = uiText('modal.statsBreakdown.pokerus', 'Pokérus');
    const tSubtotal       = uiText('modal.statsBreakdown.subtotal', 'Sous-total additif');
    const tRarity         = uiText('modal.statsBreakdown.rarity', 'Rareté');
    const tPrestige       = uiText('modal.statsBreakdown.prestige', 'Prestige');
    const tShiny          = uiText('modal.statsBreakdown.shiny', 'Shiny');
    const tTier           = uiText('modal.statsBreakdown.tier', 'Tier (ennemi)');
    const tSynergy        = uiText('modal.statsBreakdown.synergy', 'Synergies + Collection');
    const tTokens         = uiText('modal.statsBreakdown.tokens', 'Jetons de prestige (+5 % chacun)');
    const tTotalMult      = uiText('modal.statsBreakdown.totalMult', 'Multiplicateur total');
    const muraillePct = meta.murailleRatio && meta.murailleRatio > 0
        ? `${(meta.murailleRatio * 100).toFixed(meta.murailleRatio % 0.01 === 0 ? 0 : 1)}`
        : '10';
    const tTalent         = uiText('modal.statsBreakdown.talent', 'Talent Muraille (+{pct} % PV)', { pct: muraillePct });
    const tTalentChip     = uiText('modal.statsBreakdown.talentChip', 'Muraille (+{pct} % PV → ATK)', { pct: muraillePct });
    const tZone           = uiText('modal.statsBreakdown.zone', 'Zone');
    const tShadow         = uiText('modal.statsBreakdown.shadow', 'Shadow');
    const tFinal          = uiText('modal.statsBreakdown.final', 'Total final');
    const tWithoutIv      = uiText('modal.statsBreakdown.withoutIv', 'Sans IV');
    const tWithoutPkrs    = uiText('modal.statsBreakdown.withoutPokerus', 'Sans Pokérus');
    const tIvImpact       = uiText('modal.statsBreakdown.ivImpact', 'Apport IV');
    const tPkrsImpact     = uiText('modal.statsBreakdown.pokerusImpact', 'Apport Pokérus');
    const tTalentNone     = uiText('modal.statsBreakdown.talentNone', 'Aucun talent actif sur les stats');
    const tShadowNone     = uiText('modal.statsBreakdown.notShadow', 'Statut Shadow non actif');
    const tPkrsActiveTpl  = uiText('modal.statsBreakdown.pokerusActiveLevel', 'Pokérus {roman} ACTIF (×{mult})');
    const tPkrsInactive   = uiText('modal.statsBreakdown.pokerusInactive', 'Pokérus inactif');
    const tShadowDetail   = uiText('modal.statsBreakdown.shadowDetail', 'Shadow (PV ×1.25 / ATK ×1.4 / DEF ×1.10 / VIT ×1.25)');
    const tClose          = uiText('modal.close', 'Fermer');
    const ultimatePctStr = String(meta.ultimateSlotTransferPct ?? 0);
    const tUltimateSlot = uiText('modal.statsBreakdown.ultimateSlot', 'Slot ultime (+{pct}%)', { pct: ultimatePctStr });
    const tUltimateSlotChip = uiText('modal.statsBreakdown.ultimateSlotChip', 'Slot ultime : {name} (+{pct}%)', {
        name: meta.ultimateSlotMentorName || '',
        pct: ultimatePctStr,
    });
    const tUltimateSlotEmpty = uiText('modal.statsBreakdown.ultimateSlotEmpty', 'Slot ultime (vide)');

    // Bandeau récap (sans la zone : non utilisée sur les Pokémon du joueur)
    const rarityValStr  = fmtMult(meta.multipliers.rarity);
    const prestigeStr   = `${fmtMult(meta.multipliers.prestige)} (P${meta.prestige})`;
    const shinyStr      = meta.isShiny ? fmtMult(meta.multipliers.shiny) : '×1';
    const tierStr       = meta.isEnemy ? `${fmtMult(meta.multipliers.tier)} (T${meta.tier})` : '×1';
    const zoneMult      = meta.multipliers.zone ?? 1;
    const zoneStr       = fmtMult(zoneMult);

    const combatStages = meta.combatStatStages;
    const hasCombatStages = combatStages
        && Object.values(combatStages).some((v) => Number(v) !== 0);
    const combatStageCreature = hasCombatStages
        ? { getCombatStatStage: (stat: CombatStatKey) => Number(combatStages?.[stat]) || 0 }
        : null;
    const uiLang = String(game?.language || 'fr').toLowerCase().startsWith('en') ? 'en' : 'fr';
    const tCombatStages = uiText('modal.statsBreakdown.combatStages', 'Modifs de stats (combat)');
    const combatStagesHtml = combatStageCreature
        ? `<div class="stats-breakdown-combat-stages"><span class="sb-chip sb-chip-muted"><b>${tCombatStages}</b> ${buildCombatStatStageBadgesHtml(combatStageCreature, uiLang)}</span></div>`
        : '';

    const headerChips = `
        <div class="stats-breakdown-chips">
            <span class="sb-chip"><b>${tRarity}</b> ${rarityValStr}</span>
            <span class="sb-chip"><b>${tPrestige}</b> ${prestigeStr}</span>
            <span class="sb-chip"><b>${tShiny}</b> ${shinyStr}</span>
            ${meta.isEnemy ? `<span class="sb-chip"><b>${tTier}</b> ${tierStr}</span>` : ''}
            ${zoneMult !== 1 ? `<span class="sb-chip"><b>${tZone}</b> ${zoneStr}</span>` : ''}
            <span class="sb-chip ${meta.hasPokerus ? 'sb-chip-good' : 'sb-chip-muted'}">${
                meta.hasPokerus
                    ? tPkrsActiveTpl
                        .replace('{roman}', (['', 'I', 'II', 'III', 'IV', 'V'][meta.pokerusLevel] || String(meta.pokerusLevel || '')))
                        .replace('{mult}', fmtMult(meta.multipliers.pokerus).replace('×', ''))
                    : tPkrsInactive
            }</span>
            <span class="sb-chip ${meta.passiveTalent === 'muraille' ? 'sb-chip-good' : 'sb-chip-muted'}">${meta.passiveTalent === 'muraille' ? tTalentChip : tTalentNone}</span>
            <span class="sb-chip ${meta.isShadow ? 'sb-chip-good' : 'sb-chip-muted'}">${meta.isShadow ? tShadowDetail : tShadowNone}</span>
            ${meta.ultimateSlotUnlocked
                ? `<span class="sb-chip ${meta.ultimateSlotMentorName ? 'sb-chip-good' : 'sb-chip-muted'}">${
                    meta.ultimateSlotMentorName ? tUltimateSlotChip : tUltimateSlotEmpty
                }</span>`
                : ''}
        </div>
    `;

    // Lignes par stat
    const buildStatBlock = (key: StatBreakdownKey) => {
        const s = stats[key];
        const v = variants[key] || { withoutIv: s.final, withoutPokerus: s.final, ivContribution: 0, pokerusContribution: 0 };
        const lab = statLabels[key];
        const tokensCount = (meta.tokens && meta.tokens[key]) || 0;
        const tokenLine = tokensCount > 0
            ? `<tr><td>${tTokens}</td><td>+${tokensCount * 5}%</td></tr>`
            : '';
        const talentLine = s.talentBonus > 0
            ? `<tr class="sb-good"><td>${tTalent}</td><td>${fmtSigned(s.talentBonus)}</td></tr>`
            : '';
        const shadowLine = s.shadowMult !== 1
            ? `<tr class="${s.shadowMult > 1 ? 'sb-good' : 'sb-bad'}"><td>${tShadow}</td><td>${fmtNum(s.beforeShadow)} → ${fmtMult(s.shadowMult)} → ${fmtNum(s.final)}</td></tr>`
            : '';
        const ultimateLine = (s.ultimateSlotBonus ?? 0) > 0
            ? `<tr class="sb-good"><td>${tUltimateSlot}</td><td>${fmtSigned(s.ultimateSlotBonus ?? 0)}</td></tr>`
            : '';
        const zoneLine = (s.zoneMult ?? 1) !== 1
            ? `<tr><td>${tZone}</td><td>${fmtMult(s.zoneMult ?? 1)}</td></tr>`
            : '';
        const tierLine = meta.isEnemy
            ? `<tr><td>${tTier}</td><td>${fmtMult(s.tierMult)}</td></tr>`
            : '';
        const pokerusLine = s.pokerusMult !== 1
            ? `<tr class="sb-good"><td>${tPokerus}${meta.pokerusLevel ? ` ${(['', 'I', 'II', 'III', 'IV', 'V'][meta.pokerusLevel] || '')}` : ''}</td><td>${fmtMult(s.pokerusMult)}</td></tr>`
            : '';

        // IV : afficher la valeur effective (IV × prestige) si le multiplicateur est > 1
        const ivLabel = (s.ivPrestigeMult > 1)
            ? tIvWithMult.replace('{val}', String(s.iv)).replace('{max}', String(s.ivMax)).replace('{mult}', fmtMult(s.ivPrestigeMult))
            : tIv.replace('{val}', String(s.iv)).replace('{max}', String(s.ivMax));
        const ivShown = (s.ivPrestigeMult > 1)
            ? `${fmtSigned(s.ivContribution)} (${s.iv} × ${fmtMult(s.ivPrestigeMult)})`
            : fmtSigned(Number(s.iv));

        const ivPctOfFinal = s.final > 0 ? (v.ivContribution / s.final) : 0;
        const pkrsPctOfFinal = s.final > 0 ? (v.pokerusContribution / s.final) : 0;

        return `
            <details class="stats-breakdown-stat srow" open style="--c:${statCssVarMap[key]}; border-left: 4px solid var(--c);">
                <summary>
                    <span class="sb-stat-icon">${lab.icon}</span>
                    <span class="sb-stat-name" style="color:var(--c); font-weight:800;">${lab.label}</span>
                    <span class="sb-stat-value">${fmtNum(s.final)}</span>
                </summary>
                <div class="sb-stat-body">
                    <table class="sb-table">
                        <tbody>
                            <tr><td>${tBase}</td><td>${fmtNum(s.base)}</td></tr>
                            <tr class="sb-good"><td>${ivLabel}</td><td>${ivShown}</td></tr>
                            <tr class="sb-subtotal"><td>${tSubtotal}</td><td>${fmtNum(s.additive)}</td></tr>
                            <tr><td>${tRarity}</td><td>${fmtMult(s.rarityMult)}</td></tr>
                            <tr><td>${tPrestige}</td><td>${fmtMult(s.prestigeMult)}</td></tr>
                            ${meta.isShiny ? `<tr><td>${tShiny}</td><td>${fmtMult(s.shinyMult)}</td></tr>` : ''}
                            ${pokerusLine}
                            ${tierLine}
                            ${zoneLine}
                            <tr><td>${tSynergy}</td><td>${fmtMult(s.synergyMult)}</td></tr>
                            ${tokenLine}
                            <tr class="sb-subtotal"><td>${tTotalMult}</td><td>${fmtMult(s.totalMult)}</td></tr>
                            ${talentLine}
                            ${shadowLine}
                            ${ultimateLine}
                            <tr class="sb-final"><td><b>${tFinal}</b></td><td><b>${fmtNum(s.final)}</b></td></tr>
                        </tbody>
                    </table>
                    <div class="sb-impacts">
                        <div class="sb-impact">
                            <div class="sb-impact-label">${tIvImpact}</div>
                            <div class="sb-impact-value sb-good-text">${fmtSigned(v.ivContribution)} (${fmtPct(ivPctOfFinal)})</div>
                            <div class="sb-impact-sub">${tWithoutIv}: ${fmtNum(v.withoutIv)}</div>
                        </div>
                        <div class="sb-impact ${meta.hasPokerus ? '' : 'sb-impact-muted'}">
                            <div class="sb-impact-label">${tPkrsImpact}</div>
                            <div class="sb-impact-value ${meta.hasPokerus ? 'sb-good-text' : ''}">${meta.hasPokerus ? `${fmtSigned(v.pokerusContribution)} (${fmtPct(pkrsPctOfFinal)})` : '—'}</div>
                            <div class="sb-impact-sub">${tWithoutPkrs}: ${fmtNum(v.withoutPokerus)}</div>
                        </div>
                    </div>
                </div>
            </details>
        `;
    };

    const statKeys: StatBreakdownKey[] = ['hp','attack','spattack','defense','spdefense','speed'];
    const blocks = statKeys.map(buildStatBlock).join('');

    const titleName = payload.creatureName || meta.name || '';
    const megaHintEsc = String(uiText('mega.sheetMegaHint', '')).replace(/"/g, '&quot;');
    const baseSprite = payload.spriteUrl
        ? `<img src="${payload.spriteUrl}" alt="${titleName}" class="stats-breakdown-sprite">`
        : '';
    const pkrsUnderSprite = meta.hasPokerus
        ? `<img src="img/PKRS.png" alt="" class="sb-stats-pkrs" width="22" height="22" loading="lazy">`
        : '';
    const megaUnderSprite = payload.megaSpriteUrl
        ? `<img src="${payload.megaSpriteUrl}" alt="" class="stats-breakdown-sprite-mega sb-stats-mega-thumb" width="40" height="40" loading="lazy" title="${megaHintEsc}">`
        : '';
    const megaVariantHtml = payload.megaVariantSelectHTML || '';
    const spriteCol = (baseSprite || pkrsUnderSprite || megaVariantHtml || megaUnderSprite)
        ? `<div class="stats-breakdown-sprite-col">${baseSprite}${pkrsUnderSprite}${megaVariantHtml}${megaUnderSprite}</div>`
        : '';

    const modal = document.createElement('div');
    modal.id = 'statsBreakdownOverlay';
    modal.className = 'stats-modal show submodal-parent stats-breakdown-modal';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-label', `${tHeaderTitle}${titleName ? ` — ${titleName}` : ''}`);
    modal.style.zIndex = '10001';
    modal.onclick = function (e) { if (e.target === modal) closeStatsBreakdownModalUI(); };

    const onKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            closeStatsBreakdownModalUI();
        }
    };
    modal.addEventListener('keydown', onKeyDown);

    const headerHtml = buildSubModalHeaderHtml({
        title: tHeaderTitle,
        pokemonName: titleName,
        pokemonSpriteUrl: payload.spriteUrl,
        closeAction: 'closeStatsBreakdownModal',
        closeAriaLabel: tClose,
    });

    modal.innerHTML = `
        <div class="stats-content stats-breakdown-content submodal-dialog-content" data-action="stopPropagation" data-action-stop>
            ${headerHtml}
            <div class="stats-breakdown-body">
                <div class="stats-breakdown-summary">
                    ${spriteCol}
                    <div class="stats-breakdown-summary-text">
                        <div class="sb-intro">${tIntro}</div>
                        ${headerChips}
                        ${combatStagesHtml}
                    </div>
                </div>
                <div class="stats-breakdown-list">
                    ${blocks}
                </div>
            </div>
        </div>
    `;
    document.body.appendChild(modal);
    registerSubModal(modal, 'creatureModal');
}

