export function showAutoPrestigeModalUI(payload: AutoPrestigePayload): void {
    closeAutoPrestigeModalUI();
    if (!payload) return;

    const tTitle = uiText('modal.creature.autoPrestigeModalTitle', 'Auto-attribution Prestige');
    const tIntro = uiText('modal.creature.autoPrestigeModalIntro', 'Choisissez la statistique qui recevra automatiquement les points de prestige obtenus lors des prestiges individuels et en masse.');
    const tDisabled = uiText('modal.creature.autoPrestigeOptionDisabled', 'Désactivé (Attribution manuelle)');
    const tClose = uiText('common.close', 'Fermer');
    const tPerLevel = uiText('modal.creature.autoPrestigeBonusPerLevel', '+5 % par niveau');
    const tApplyTokens = uiText('modal.creature.autoPrestigeApplyExistingTokens', 'Attribuer immédiatement les {count} jeton(s) en réserve', { count: payload.prestigeTokens });

    const modal = document.createElement('div');
    modal.id = 'autoPrestigeOverlay';
    modal.className = 'stats-modal show submodal-parent auto-prestige-modal';
    modal.setAttribute('role', 'dialog');
    modal.setAttribute('aria-modal', 'true');
    modal.setAttribute('aria-label', `${tTitle} — ${payload.creatureName}`);
    modal.style.zIndex = '10020';
    modal.onclick = function (e) { if (e.target === modal) closeAutoPrestigeModalUI(); };

    const onKeyDown = (e: KeyboardEvent) => {
        if (e.key === 'Escape') {
            e.preventDefault();
            closeAutoPrestigeModalUI();
        }
    };
    modal.addEventListener('keydown', onKeyDown);

    const headerHtml = buildSubModalHeaderHtml({
        title: tTitle,
        pokemonName: payload.creatureName,
        pokemonSpriteUrl: payload.spriteUrl,
        closeAction: 'closeAutoPrestigeModal',
        closeAriaLabel: tClose,
    });

    const isNoneSelected = !payload.currentStat;

    const disabledOptionHtml = `
        <button type="button"
                class="auto-prestige-card auto-prestige-card--none${isNoneSelected ? ' is-selected' : ''}"
                data-action="setAutoPrestigeStat"
                data-arg="${payload.creatureIndex}"
                data-arg2="${payload.location}"
                data-arg3="none">
            <div class="auto-prestige-card-head">
                <span class="auto-prestige-card-icon" aria-hidden="true">⏸️</span>
                <span class="auto-prestige-card-title">${tDisabled}</span>
                ${isNoneSelected ? '<span class="auto-prestige-check" aria-hidden="true">✓</span>' : ''}
            </div>
            <div class="auto-prestige-card-desc">Garder les jetons en réserve pour les dépenser manuellement</div>
        </button>
    `;

    const statCardsHtml = payload.stats.map((s) => {
        const isSelected = payload.currentStat === s.key;
        return `
            <button type="button"
                    class="auto-prestige-card${isSelected ? ' is-selected' : ''}"
                    style="--stat-color: ${s.colorVar};"
                    data-action="setAutoPrestigeStat"
                    data-arg="${payload.creatureIndex}"
                    data-arg2="${payload.location}"
                    data-arg3="${s.key}">
                <div class="auto-prestige-card-head">
                    <span class="auto-prestige-card-icon" aria-hidden="true">${s.icon}</span>
                    <span class="auto-prestige-card-title" style="color: ${s.colorVar}; font-weight:800;">${s.label}</span>
                    <span class="auto-prestige-card-val">${formatNumber(s.currentValue)}</span>
                    ${isSelected ? '<span class="auto-prestige-check" aria-hidden="true">✓</span>' : ''}
                </div>
                <div class="auto-prestige-card-footer">
                    <span class="auto-prestige-bonus-badge">${s.bonusPercent > 0 ? `+${s.bonusPercent}%` : '+0%'}</span>
                    <span class="auto-prestige-card-hint">${tPerLevel}</span>
                </div>
            </button>
        `;
    }).join('');

    const tokenImmediateHtml = (payload.prestigeTokens > 0)
        ? `<div class="auto-prestige-tokens-callout">
            <span class="auto-prestige-tokens-note">⭐ ${payload.prestigeTokens} jeton(s) disponible(s)</span>
            <label class="auto-prestige-tokens-label">
                <input type="checkbox" id="autoPrestigeApplyImmediate" class="auto-prestige-checkbox" checked>
                <span>${tApplyTokens}</span>
            </label>
           </div>`
        : '';

    modal.innerHTML = `
        <div class="stats-content stats-modal-content submodal-card submodal-dialog-content auto-prestige-modal-card auto-prestige-modal-content" data-action="stopPropagation" data-action-stop>
            ${headerHtml}
            <div class="submodal-scrollable-body auto-prestige-modal-body">
                <p class="auto-prestige-intro">${tIntro}</p>
                <div class="auto-prestige-options-grid">
                    ${disabledOptionHtml}
                    ${statCardsHtml}
                </div>
                ${tokenImmediateHtml}
            </div>
        </div>
    `;

    document.body.appendChild(modal);
    registerSubModal(modal, 'creatureModal');
}

