export function showEvolutionChoiceModalUI(payload: EvolutionChoicePayload): void {
    closeEvolutionChoiceModalUI();
    if (!payload || !Array.isArray(payload.options) || payload.options.length === 0) return;

    const modal = document.createElement('div');
    modal.id = 'evolutionChoiceOverlay';
    modal.className = 'stats-modal show evolution-choice-modal';
    modal.style.zIndex = '10001';
    modal.onclick = function (e) { if (e.target === modal) closeEvolutionChoiceModalUI(); };

    let optionsHTML = '';
    payload.options.forEach(function (opt: EvolutionChoiceOption, idx: number) {
        const evoName = String(opt.evolves_to || 'Inconnu');
        const evoDisplayName = uiPokemonName((typeof game !== 'undefined' ? game : null), evoName);
        const itemKey = String(opt.requiredItem || '');
        const itemDef = itemKey ? getAllItem(itemKey) : null;
        const reqLabel = itemKey
            ? `${(itemDef && itemDef.icon) ? itemDef.icon + ' ' : ''}${uiMaybeLocalizeItemName((typeof game !== 'undefined' ? game : null), itemDef || {}, itemKey, (itemDef && itemDef.name) ? itemDef.name : itemKey)}`
            : uiText('modal.requiredLevel', null, { level: opt.requiredLevel || 1 });
        const sprite = getPokemonSpriteUrl(evoName, false, false);

        optionsHTML += `
            <button class="btn evolution-choice-option" data-action="evolveCreatureWithOption" data-arg="${payload.creatureIndex}" data-arg2="${payload.location}" data-arg3="${idx}">
                <img src="${sprite}" alt="${evoDisplayName}" class="evolution-choice-sprite">
                <span class="evolution-choice-name">${evoDisplayName}</span>
                <span class="evolution-choice-req">${uiText('modal.requiredLabel')}: ${reqLabel}</span>
            </button>
        `;
    });

    modal.innerHTML = `
        <div class="stats-content evolution-choice-content" data-action="stopPropagation" data-action-stop>
            <div class="stats-header">
                <h2>${uiText('modal.evolutionSelectTitle', null, { name: payload.creatureName || 'Pokemon' })}</h2>
                <button class="stats-close" data-action="closeEvolutionChoiceModal">&#10005;</button>
            </div>
            <div class="evolution-choice-list">
                ${optionsHTML}
            </div>
        </div>
    `;

    document.body.appendChild(modal);
    publishModalOpened('evolutionChoiceModal');
}

