/**
 * Génère le HTML du contenu du modal créature (détail).
 * @param {Object} data - { titleLine, spriteUrl, type, secondaryType, rarity, maxLevel, tokenDisplay, statsBoxTitle, statsRowsHTML, moveHTML, talentHTML, ultimateHTML, itemHTML, actionsHTML }
 * @returns {string} HTML
 */
export function renderCreatureModalContent(data: CreatureModalContentData): string {
    const lang = data.language || 'fr';
    const type1Label = data.typeDisplayLabel ?? (data.type ? formatPokemonTypeLabel(data.type, lang) : '');
    const type2Label = data.secondaryTypeDisplayLabel ?? (data.secondaryType ? formatPokemonTypeLabel(data.secondaryType, lang) : '');
    const type2 = data.secondaryType ? `<span class="type-badge type type-${data.secondaryType}">${type2Label || data.secondaryType}</span>` : '';
    const levelShort = uiText('state.levelShort', 'Lvl');
    const shadowClass = data.isShadow ? ' shadow' : '';
    const closeAction = data.closeAction || 'closeCreatureModal';
    const rarityText = data.rarityDisplayLabel ?? data.rarity ?? '';
    const compact = !!data.compactLayout;
    const isMax = !!data.isMaxLevel || (data.level !== undefined && data.maxLevel !== undefined && data.level >= data.maxLevel);
    const expBarHtml = (compact || data.hideExpBar || isMax)
        ? ''
        : `<div class="creature-modal-exp-bar">
                <div class="creature-modal-exp-fill" style="width:${data.expPercent || 0}%;"></div>
            </div>`;
    const compactTitleBlock = compact && data.titleLine
        ? `<div class="egg-hatch-compact-title"><span class="creature-name-pixel">${data.titleLine}</span></div>`
        : '';
    const prestigeBadgeHtml = (data.prestige && data.prestige > 0)
        ? `<span class="creature-modal-prestige-star" data-tooltip-title="Prestige ${data.prestige}" data-tooltip-desc="★ ${data.prestige}">★ ${data.prestige}</span>`
        : '';
    const levelDisplay = data.levelDisplay || (isMax
        ? `${levelShort} ${data.maxLevel ?? data.level} MAX`
        : `${levelShort} ${data.level ?? 1} / ${data.maxLevel ?? 100}`);
    const switcherHtml = data.hasMultipleCreatures ? `
        <div class="creature-modal-switcher" role="group" aria-label="${data.navAriaLabel || 'Navigation'}">
            <button type="button"
                    class="btn-2 switcher-btn"
                    data-action="navigateCreatureModal"
                    data-arg="${data.prevIndex}"
                    data-arg2="${data.location}"
                    data-tooltip-title="${data.prevPokemonTitle || 'Pokémon précédent'}"
                    data-tooltip-desc="${data.prevPokemonDesc || 'Flèche gauche'}"
                    aria-label="${data.prevPokemonTitle || 'Pokémon précédent'}">◀</button>
            <span class="switcher-pos">${data.positionLabel ?? ''}</span>
            <button type="button"
                    class="btn-2 switcher-btn"
                    data-action="navigateCreatureModal"
                    data-arg="${data.nextIndex}"
                    data-arg2="${data.location}"
                    data-tooltip-title="${data.nextPokemonTitle || 'Pokémon suivant'}"
                    data-tooltip-desc="${data.nextPokemonDesc || 'Flèche droite'}"
                    aria-label="${data.nextPokemonTitle || 'Pokémon suivant'}">▶</button>
        </div>` : '';
    const modalHeadHtml = compact ? '' : `
        <header class="modal-head creature-modal-head">
            <div class="creature-modal-head-identity">
                <h2 class="creature-modal-head-title">
                    <span class="creature-name-pixel">${data.titleLine}</span>
                </h2>
                ${prestigeBadgeHtml}
                <div class="creature-modal-head-level-wrap">
                    <span class="creature-modal-level-badge${isMax ? ' is-max' : ''}">${levelDisplay}</span>
                    ${expBarHtml}
                </div>
                ${data.ivButton ? `<div class="creature-modal-header-actions">${data.ivButton}</div>` : ''}
            </div>
            ${switcherHtml}
            <button type="button" class="btn-2 x stats-close" data-action="${closeAction}" aria-label="Fermer">&#10005;</button>
        </header>`;
    const statsTitle = data.statsBoxTitle || uiText('modal.creature.statsTitle', 'Statistiques');
    const statsHeaderBlock = compact
        ? ''
        : `<div class="creature-modal-stats-header">
                        <div class="creature-modal-stats-box-title">
                            <span class="creature-name-pixel creature-modal-stats-title">${statsTitle}</span>
                        </div>
                        ${data.autoPrestigeButtonHTML ? `<div class="creature-modal-stats-actions">${data.autoPrestigeButtonHTML}</div>` : ''}
                    </div>`;
    const cardsBlock = (compact || data.hideMoveCards)
        ? ''
        : `<div class="creature-modal-cards">
                    <div class="creature-modal-move-column">
                        ${data.moveHTML ?? ''}
                    </div>
                    <div class="creature-modal-info">
                        ${data.talentHTML ?? ''}
                        ${data.ultimateHTML ?? ''}
                        ${data.itemHTML ?? ''}
                    </div>
                </div>`;
    const actionsBlock = data.hideActions
        ? ''
        : `<div class="creature-modal-actions">
                    ${data.actionsHTML ?? ''}
                </div>`;
    const gridClass = compact ? 'creature-modal-grid creature-modal-grid--egg-hatch-compact' : 'creature-modal-grid';
    return `
        ${compact ? `<button class="stats-close creature-modal-close" data-action="${closeAction}">&times;</button>${compactTitleBlock}` : modalHeadHtml}
        <div class="${gridClass}">
            <div class="creature-modal-sprite-wrap${shadowClass}">
                <div class="creature-modal-sprite-frame">
                    ${!compact && data.favoriteButtonHTML ? data.favoriteButtonHTML : ''}
                    <img src="${data.spriteUrl}" alt="${data.creatureName}" class="creature-modal-sprite">
                </div>
                <div class="creature-modal-badges">
                    <div class="creature-modal-badges-types">
                        <span class="type-badge type type-${data.type}">${type1Label || data.type}</span>
                        ${type2}
                    </div>
                    <div class="creature-modal-badges-rarity">
                        <span class="rarity-label ${data.rarity}">${rarityText}</span>
                    </div>
                    ${data.pokerusActive
                        ? `<div class="creature-modal-pokerus-row">
                            <img src="img/PKRS.png"
                                 alt="PKRS"
                                 class="creature-modal-pokerus-icon"
                                 onmouseenter="game.scheduleTooltip(event, 'Pokérus${data.pokerusLevelLabel ? ' ' + data.pokerusLevelLabel : ''}', '${(data.pokerusRemainingLabel || '').replace(/'/g, "\\'")}')"
                                 onmouseleave="game.hideTooltip()">
                            ${data.pokerusLevelLabel ? `<span class="creature-modal-pokerus-level">${data.pokerusLevelLabel}</span>` : ''}
                           </div>`
                        : ''}
                    ${data.megaStoneUnlocked && (data.megaFormDisplayName || data.megaVariantSelectHTML) ? `
                        ${data.megaVariantSelectHTML || ''}
                        <div class="creature-modal-mega-form-label" title="${String(uiText('mega.sheetMegaHint', '')).replace(/"/g, '&quot;')}">
                            <span class="creature-modal-mega-name">${data.megaFormDisplayName || ''}</span>
                        </div>` : ''}
                </div>
            </div>
            <div class="creature-modal-main">
                ${compact ? '' : (data.tokenDisplay ?? '')}
                <div class="creature-modal-stats-box">
                    ${statsHeaderBlock}
                    <div class="creature-modal-stats-row">
                        ${data.statsRowsHTML ?? ''}
                    </div>
                </div>
                ${cardsBlock}
            </div>
            ${compact ? '' : actionsBlock}
        </div>
    `;
}

function buildEggHatchReadOnlyStatLine(
    gameRef: GameRuntime,
    label: string,
    value: string | number,
    statKey: string,
    ivVal: number | undefined,
): string {
    const statCssVarMap: Record<string, string> = {
        hp: 'var(--s-hp, #ef4444)',
        attack: 'var(--s-atk, #f59e0b)',
        spattack: 'var(--s-atksp, #ec4899)',
        defense: 'var(--s-def, #4a7c23)',
        spdefense: 'var(--s-defsp, #10b981)',
        speed: 'var(--s-spd, #8b5cf6)',
    };
    const statCssVar = statCssVarMap[statKey] || `var(--s-${statKey}, #64748b)`;
    const ivTitle = gameRef.t('modal.creature.ivTitle');
    const ivDesc = gameRef.t('modal.creature.ivDesc');
    let ivClass = 'stat-iv--good';
    if (ivVal !== undefined && ivVal !== null) {
        if (ivVal >= 31) ivClass = 'stat-iv--max';
        else if (ivVal < 20) ivClass = 'stat-iv--low';
    }
    const ivStr = (ivVal !== undefined && ivVal !== null)
        ? ` <span class="stat-iv stat-iv-tooltip ${ivClass}" onmouseenter="game.scheduleTooltip(event, '${ivTitle}', '${ivDesc}')" onmouseleave="game.hideTooltip()">IV (${ivVal})</span>`
        : '';
    return `<div class="stat-item-inner stat-row-${statKey} srow" style="--c:${statCssVar};">
        <span class="stat-label"><strong>${label}</strong></span>
        <span class="stat-value">${formatNumber(value)}</span>
        <span class="stat-iv-col">${ivStr}</span>
        <span class="stat-bonus-col"></span>
    </div>`;
}

/**
 * Contenu read-only du modal éclosion (sprite, types, rareté, stats + IVs).
 */
export function buildEggHatchCreatureModalHtml(gameRef: GameRuntime, creature: CreatureData): string {
    const creatureDisplayName = typeof gameRef.getLocalizedPokemonName === 'function'
        ? gameRef.getLocalizedPokemonName(creature.name)
        : creature.name;
    const titleLine = `${creature.isShadow ? '[Shadow] ' : ''}${creatureDisplayName}${creature.isShiny ? ` ${shinyBadgeHtml('Shiny')}` : ''}`;
    const spriteUrl = getPokemonSpriteUrl(creature.name, creature.isShiny, false);
    const rarityKey = String(creature.rarity || 'common');
    const rarityDisplayLabel = typeof gameRef.getRarityLabel === 'function'
        ? gameRef.getRarityLabel(rarityKey)
        : rarityKey;
    const statsRowsHTML = `
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, 'HP', creature.maxHp, 'hp', creature.ivHP)}</div>
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, gameRef.t('modal.creature.atkShort'), creature.attack, 'attack', creature.ivAttack)}</div>
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, gameRef.t('modal.creature.spAtkShort'), creature.spattack, 'spattack', creature.ivSpAttack)}</div>
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, gameRef.t('modal.creature.defShort'), creature.defense, 'defense', creature.ivDefense)}</div>
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, gameRef.t('modal.creature.spDefShort'), creature.spdefense, 'spdefense', creature.ivSpDefense)}</div>
        <div class="stat-item">${buildEggHatchReadOnlyStatLine(gameRef, gameRef.t('modal.creature.speedShort'), creature.speed, 'speed', creature.ivSpeed)}</div>
    `;

    return renderCreatureModalContent({
        titleLine,
        spriteUrl,
        creatureName: creatureDisplayName,
        type: creature.type,
        secondaryType: creature.secondaryType || '',
        rarity: rarityKey,
        rarityDisplayLabel,
        isShadow: !!creature.isShadow,
        statsRowsHTML,
        hideMoveCards: true,
        hideActions: true,
        closeAction: 'closeEggHatchModal',
        compactLayout: true,
    });
}

/**
 * Ferme le modal créature (retire la classe show).
 */
export function closeCreatureModalUI() {
    closeAutoPrestigeModalUI();
    const modal = document.getElementById('creatureModal');
    if (modal) modal.classList.remove('show');
}

