/**
 * @file src/ui/uiDom.ts
 * DOM helpers for imperative UI modules.
 */

export interface StorageListElement extends HTMLElement {
    _storageDragDelegationBound?: boolean;
    _storageDropDelegationBound?: boolean;
}

export function eventTargetElement(target: EventTarget | null): Element | null {
    return target instanceof Element ? target : null;
}

export function isHtmlButtonElement(el: Element | null): el is HTMLButtonElement {
    return el instanceof HTMLButtonElement;
}

export function isHtmlSelectElement(el: Element | null): el is HTMLSelectElement {
    return el instanceof HTMLSelectElement;
}
