interface EdgeScrollState {
    speed: number;
    rafId: number;
}

function legacyClickEvent(): Event | undefined {
    return (globalThis as typeof globalThis & { event?: Event }).event;
}

const HORIZONTAL_EDGE_SCROLL_CONFIG = Object.freeze({
    edgeThresholdPx: 72,
    maxSpeedPxPerFrame: 18,
});

const SUB_TAB_EDGE_SCROLL_CONFIG = HORIZONTAL_EDGE_SCROLL_CONFIG;

const TABS_EDGE_SCROLL_CONFIG = HORIZONTAL_EDGE_SCROLL_CONFIG;

const horizontalEdgeScrollStates = new WeakMap<HTMLElement, EdgeScrollState>();

export interface BindHorizontalEdgeAutoScrollOptions {
    datasetKey?: string;
    chipSelector?: string;
    config?: typeof HORIZONTAL_EDGE_SCROLL_CONFIG;
    onTick?: (container: HTMLElement) => void;
    onScrollStateChange?: (container: HTMLElement) => void;
}

function getHorizontalEdgeScrollState(container: HTMLElement): EdgeScrollState {
    let state = horizontalEdgeScrollStates.get(container);
    if (!state) {
        state = { speed: 0, rafId: 0 };
        horizontalEdgeScrollStates.set(container, state);
    }
    return state;
}

export function canHorizontalContainerScroll(container: HTMLElement): boolean {
    return !!container && (container.scrollWidth - container.clientWidth) > 4;
}

export function computeHorizontalEdgeScrollSpeed(
    container: HTMLElement,
    clientX: number,
    config: typeof HORIZONTAL_EDGE_SCROLL_CONFIG = HORIZONTAL_EDGE_SCROLL_CONFIG,
): number {
    if (!canHorizontalContainerScroll(container)) return 0;
    const rect = container.getBoundingClientRect();
    const edgeThreshold = Math.min(config.edgeThresholdPx, rect.width * 0.3);
    if (edgeThreshold <= 0) return 0;

    let speed = 0;
    if (clientX < rect.left + edgeThreshold) {
        const ratio = Math.max(0, Math.min(1, ((rect.left + edgeThreshold) - clientX) / edgeThreshold));
        speed = -Math.ceil(ratio * config.maxSpeedPxPerFrame);
    } else if (clientX > rect.right - edgeThreshold) {
        const ratio = Math.max(0, Math.min(1, (clientX - (rect.right - edgeThreshold)) / edgeThreshold));
        speed = Math.ceil(ratio * config.maxSpeedPxPerFrame);
    }

    const maxScrollLeft = Math.max(0, container.scrollWidth - container.clientWidth);
    if ((speed < 0 && container.scrollLeft <= 0) || (speed > 0 && container.scrollLeft >= maxScrollLeft)) {
        return 0;
    }
    return speed;
}

export function stopHorizontalEdgeAutoScroll(container: HTMLElement): void {
    const state = getHorizontalEdgeScrollState(container);
    state.speed = 0;
    if (state.rafId) {
        cancelAnimationFrame(state.rafId);
        state.rafId = 0;
    }
}

function startHorizontalEdgeAutoScroll(
    container: HTMLElement,
    onTick?: (container: HTMLElement) => void,
): void {
    const state = getHorizontalEdgeScrollState(container);
    if (state.rafId) return;

    const tick = () => {
        if (!state.speed) {
            state.rafId = 0;
            return;
        }
        const previousScrollLeft = container.scrollLeft;
        container.scrollLeft += state.speed;
        if (container.scrollLeft === previousScrollLeft) {
            state.speed = 0;
            state.rafId = 0;
            return;
        }
        onTick?.(container);
        state.rafId = requestAnimationFrame(tick);
    };

    state.rafId = requestAnimationFrame(tick);
}

export function updateHorizontalEdgeAutoScrollSpeed(
    container: HTMLElement,
    clientX: number,
    options: {
        config?: typeof HORIZONTAL_EDGE_SCROLL_CONFIG;
        onTick?: (container: HTMLElement) => void;
    } = {},
): void {
    const state = getHorizontalEdgeScrollState(container);
    const config = options.config ?? HORIZONTAL_EDGE_SCROLL_CONFIG;
    state.speed = computeHorizontalEdgeScrollSpeed(container, clientX, config);
    if (!state.speed) {
        if (state.rafId) {
            cancelAnimationFrame(state.rafId);
            state.rafId = 0;
        }
        return;
    }
    startHorizontalEdgeAutoScroll(container, options.onTick);
}

export function bindHorizontalEdgeAutoScroll(
    container: HTMLElement,
    options: BindHorizontalEdgeAutoScrollOptions = {},
): void {
    const datasetKey = options.datasetKey ?? 'edgeScrollBoundHorizontal';
    if (!container || container.dataset[datasetKey] === '1') return;
    container.dataset[datasetKey] = '1';

    const config = options.config ?? HORIZONTAL_EDGE_SCROLL_CONFIG;
    const onTick = options.onTick;
    const onScrollStateChange = options.onScrollStateChange;
    const hasFinePointer = () => (window.matchMedia ? window.matchMedia('(pointer: fine)').matches : true);

    onScrollStateChange?.(container);

    container.addEventListener('mousemove', (ev: MouseEvent) => {
        if (!hasFinePointer()) return;
        updateHorizontalEdgeAutoScrollSpeed(container, ev.clientX, { config, onTick });
    }, { passive: true });

    container.addEventListener('mouseleave', () => {
        stopHorizontalEdgeAutoScroll(container);
    });

    container.addEventListener('mouseenter', () => {
        onScrollStateChange?.(container);
    }, { passive: true });

    container.addEventListener('scroll', () => {
        onScrollStateChange?.(container);
    }, { passive: true });

    if (options.chipSelector) {
        container.addEventListener('click', (ev: MouseEvent) => {
            const clickedChip = eventTargetElement(ev.target)?.closest(options.chipSelector!) ?? null;
            if (!clickedChip || !container.contains(clickedChip)) return;
            requestAnimationFrame(() => {
                if (typeof clickedChip.scrollIntoView === 'function') {
                    clickedChip.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
                }
                onScrollStateChange?.(container);
            });
        });
    }
}

export function getSubTabEdgeScrollState(container: HTMLElement): EdgeScrollState {
    return getHorizontalEdgeScrollState(container);
}

export function canSubTabContainerScroll(container: HTMLElement): boolean {
    return canHorizontalContainerScroll(container);
}

export function updateSubTabContainerScrollableState(container: HTMLElement): void {
    if (!container) return;
    container.classList.toggle('sub-tabs-scrollable', canSubTabContainerScroll(container));
}

export function computeSubTabEdgeScrollSpeed(container: HTMLElement, clientX: number): number {
    return computeHorizontalEdgeScrollSpeed(container, clientX, SUB_TAB_EDGE_SCROLL_CONFIG);
}

export function stopSubTabEdgeAutoScroll(container: HTMLElement): void {
    stopHorizontalEdgeAutoScroll(container);
}

export function startSubTabEdgeAutoScroll(container: HTMLElement): void {
    startHorizontalEdgeAutoScroll(container, updateSubTabContainerScrollableState);
}

export function updateSubTabEdgeAutoScrollSpeed(container: HTMLElement, clientX: number): void {
    updateHorizontalEdgeAutoScrollSpeed(container, clientX, {
        config: SUB_TAB_EDGE_SCROLL_CONFIG,
        onTick: updateSubTabContainerScrollableState,
    });
}

export function bindSubTabEdgeAutoScroll(container: HTMLElement): void {
    bindHorizontalEdgeAutoScroll(container, {
        datasetKey: 'edgeScrollBound',
        chipSelector: '.sub-tab-btn',
        config: SUB_TAB_EDGE_SCROLL_CONFIG,
        onTick: updateSubTabContainerScrollableState,
        onScrollStateChange: updateSubTabContainerScrollableState,
    });
}

export function initSubTabEdgeAutoScroll() {
    const containers = document.querySelectorAll('.sub-tabs-container');
    containers.forEach((el) => bindSubTabEdgeAutoScroll(el as HTMLElement));
    containers.forEach((el) => updateSubTabContainerScrollableState(el as HTMLElement));
}

export function getTabsEdgeScrollState(container: HTMLElement): EdgeScrollState {
    return getHorizontalEdgeScrollState(container);
}

export function canTabsContainerScroll(container: HTMLElement): boolean {
    return canHorizontalContainerScroll(container);
}

export function updateTabsContainerScrollableState(container: HTMLElement): void {
    if (!container) return;
    const scrollable = canTabsContainerScroll(container);
    container.classList.toggle('tabs-scrollable', scrollable);

    const maxScroll = Math.max(0, container.scrollWidth - container.clientWidth);
    const atStart = container.scrollLeft <= 4;
    const atEnd = container.scrollLeft >= maxScroll - 4;
    container.classList.toggle('tabs-scroll-at-start', atStart);
    container.classList.toggle('tabs-scroll-at-end', atEnd);
    container.dataset.atStart = atStart ? 'true' : 'false';
    container.dataset.atEnd = atEnd ? 'true' : 'false';

    const parent = container.closest('.secondary-content');
    if (parent instanceof HTMLElement) {
        parent.classList.toggle('tabs-has-overflow', scrollable);
        parent.classList.toggle('tabs-scroll-at-start', atStart);
        parent.classList.toggle('tabs-scroll-at-end', atEnd);
    }
}

export function refreshTabsContainerScrollStates(): void {
    document.querySelectorAll('.tabs-container').forEach((el) => {
        updateTabsContainerScrollableState(el as HTMLElement);
    });
}

export function computeTabsEdgeScrollSpeed(container: HTMLElement, clientX: number): number {
    return computeHorizontalEdgeScrollSpeed(container, clientX, TABS_EDGE_SCROLL_CONFIG);
}

export function stopTabsEdgeAutoScroll(container: HTMLElement): void {
    stopHorizontalEdgeAutoScroll(container);
}

export function startTabsEdgeAutoScroll(container: HTMLElement): void {
    startHorizontalEdgeAutoScroll(container);
}

export function updateTabsEdgeAutoScrollSpeed(container: HTMLElement, clientX: number): void {
    updateHorizontalEdgeAutoScrollSpeed(container, clientX, { config: TABS_EDGE_SCROLL_CONFIG });
}

export function bindTabsEdgeAutoScroll(container: HTMLElement): void {
    bindHorizontalEdgeAutoScroll(container, {
        datasetKey: 'edgeScrollBoundTabs',
        chipSelector: '.tab-btn',
        config: TABS_EDGE_SCROLL_CONFIG,
        onScrollStateChange: updateTabsContainerScrollableState,
    });
}

export function initTabsEdgeAutoScroll() {
    const containers = document.querySelectorAll('.tabs-container');
    containers.forEach((el) => bindTabsEdgeAutoScroll(el as HTMLElement));
    refreshTabsContainerScrollStates();
}

export function setTabButtonState(button: Element | null, isActive: boolean): void {
    if (!button) return;
    button.classList.toggle('active', !!isActive);
    button.setAttribute('aria-selected', isActive ? 'true' : 'false');
    button.setAttribute('tabindex', isActive ? '0' : '-1');
}

export function setTabPanelState(panel: Element | null, isActive: boolean): void {
    if (!panel || !(panel instanceof HTMLElement)) return;
    if (!panel) return;
    panel.classList.toggle('active', !!isActive);
    panel.style.display = isActive ? '' : 'none';
    panel.hidden = !isActive;
    panel.setAttribute('aria-hidden', isActive ? 'false' : 'true');
}

/**
 * Change l'onglet actif dans l'interface principale.
 * @param {string} tabName - Le nom de l'onglet (sans le suffixe 'Tab')
 */
export function switchTab(tabName: string): void {
    const guard = TAB_UNLOCK_GUARD[tabName];
    const featureKey = guard?.key as keyof UnlockedFeatures | undefined;
    if (guard && game && game.unlockedFeatures && featureKey && !game.unlockedFeatures[featureKey]) {
        if (toast.info) {
            toast.info(
                uiText('toast.tabLockedTitle', 'Tab locked', {}, game),
                uiText('toast.tabLockedBody', 'Complete Professor Oak quests to unlock {label}.', {
                    label: uiText(guard.labelKey || '', guard.fallback || guard.key, {}, game)
                }, game)
            );
        }
        return;
    }

    const tabs = document.querySelectorAll('.tab-content');
    tabs.forEach(tab => setTabPanelState(tab, tab.id === (tabName + 'Tab')));

    const buttons = document.querySelectorAll('.tab-btn');
    buttons.forEach(btn => setTabButtonState(btn, btn.getAttribute('data-arg') === tabName));

    const clickEvt = legacyClickEvent();
    const clickTarget = clickEvt ? eventTargetElement(clickEvt.target) : null;
    const targetBtn = (clickTarget && isHtmlButtonElement(clickTarget) && clickTarget.classList.contains('tab-btn'))
        ? clickTarget
        : Array.from(buttons).find(btn => btn.getAttribute('data-arg') === tabName);
    if (targetBtn) setTabButtonState(targetBtn, true);

    const activeTabBtn = Array.from(buttons).find(btn => btn.getAttribute('data-arg') === tabName);
    if (activeTabBtn instanceof HTMLElement) {
        requestAnimationFrame(() => {
            if (typeof activeTabBtn.scrollIntoView === 'function') {
                activeTabBtn.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
            }
            const tabsContainer = activeTabBtn.closest('.tabs-container');
            if (tabsContainer instanceof HTMLElement) {
                updateTabsContainerScrollableState(tabsContainer);
            }
        });
    }

    if (typeof game !== 'undefined' && game) {
        game.isTeamRocketTabActive = (tabName === 'teamrocket');
        // Suivi de l'onglet principal actif (utilisé par secondaryInterval pour
        // skipper les refresh DOM qui ne seraient de toute façon pas visibles).
        game._activeMainTabId = tabName + 'Tab';
        syncMainTabState(tabName);
    }

    void awaitLazyTabReady(tabName).then(() => {
        scheduleExtrasScrollReset(() => resetExtrasMainTabScroll(tabName));
    });
}

/**
 * Change le sous-onglet de la boutique (Epicerie, Pokédollars, Jetons, etc.)
 * @param {string} tabName - Nom du sous-onglet
 */
export function switchShopSubTab(tabName: string): void {
    if (tabName === 'recycleur' && game && game.unlockedFeatures && !game.unlockedFeatures.recyclerSubTab) {
        if (toast.info) {
            toast.info(
                uiText('toast.tabLockedTitle', 'Tab locked', {}, game),
                uiText('toast.recyclerLockedBody', 'Complete Professor Oak quests to unlock the Recycler.', {}, game)
            );
        }
        return;
    }

    if (tabName === 'subway' && game && game.unlockedFeatures && !game.unlockedFeatures.subwayTab) {
        if (toast.info) {
            toast.info(
                uiText('toast.tabLockedTitle', 'Tab locked', {}, game),
                uiText('toast.subwayLockedBody', 'Débloquez le Battle Subway pour accéder à cette boutique.', {}, game)
            );
        }
        return;
    }

    const subContents = document.querySelectorAll('#boutiqueTab > .sub-tab-content');
    subContents.forEach(tab => setTabPanelState(tab, tab.id === ('shop-' + tabName)));

    const subButtons = document.querySelectorAll('#boutiqueTab > .sub-tabs-container .sub-tab-btn');
    subButtons.forEach(btn => setTabButtonState(btn, btn.getAttribute('data-arg') === tabName));

    let activeButton = null;

    const clickEvt = legacyClickEvent();
    if (clickEvt) {
        const eventTarget = eventTargetElement(clickEvt.currentTarget) ?? eventTargetElement(clickEvt.target);
        activeButton = eventTarget?.closest('#boutiqueTab > .sub-tabs-container .sub-tab-btn') ?? null;
    }

    if (!activeButton) {
        activeButton = Array.from(subButtons).find(btn => btn.getAttribute('data-arg') === tabName) || null;
    }

    if (activeButton) {
        setTabButtonState(activeButton, true);
        if (typeof activeButton.scrollIntoView === 'function') {
            activeButton.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        }
    }

    if (tabName === 'recycleur') {
        switchRecyclerSubTab('shards');
    }

    if (game) {
        if (tabName === 'epicerie') {
            game.updatePokeMartDisplay();
        } else if (tabName === 'pokedollars') {
            game.updateUpgradesDisplay();
        } else if (tabName === 'jetons') {
            game.updateShopDisplay();
        } else if (tabName === 'marques') {
            game.updateTowerShopDisplay();
        } else if (tabName === 'subway') {
            if (typeof game.updateSubwayDisplay === 'function') game.updateSubwayDisplay();
        } else if (tabName === 'recycleur') {
            game.updateRecyclerDisplay();
        }
    }

    scheduleExtrasScrollReset(() => resetBoutiqueSubTabScroll(tabName));
}

/**
 * Change le sous-onglet du recycleur (Shards / Boutique poussière).
 */
export function switchRecyclerSubTab(tabName: string): void {
    const root = document.getElementById('recyclerContent');
    if (!root) return;

    const panels = root.querySelectorAll('.sub-tab-content');
    panels.forEach(panel => setTabPanelState(panel, panel.id === `recycler-${tabName}`));

    const buttons = root.querySelectorAll('.sub-tabs-container .sub-tab-btn');
    buttons.forEach(btn => setTabButtonState(btn, btn.getAttribute('data-arg') === tabName));

    let activeButton: Element | null = null;
    const clickEvt = legacyClickEvent();
    if (clickEvt) {
        const eventTarget = eventTargetElement(clickEvt.currentTarget) ?? eventTargetElement(clickEvt.target);
        activeButton = eventTarget?.closest('#recyclerContent .sub-tabs-container .sub-tab-btn') ?? null;
    }
    if (!activeButton) {
        activeButton = Array.from(buttons).find(btn => btn.getAttribute('data-arg') === tabName) || null;
    }
    if (activeButton) {
        setTabButtonState(activeButton, true);
        if (typeof activeButton.scrollIntoView === 'function') {
            activeButton.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        }
    }

    if (tabName === 'dust' && typeof document !== 'undefined') {
        document.dispatchEvent(new CustomEvent('poketime:recyclerClosePopover'));
    }

    scheduleExtrasScrollReset(() => resetRecyclerSubTabScroll());
}

export function switchQuestsSubTab(tabName: string): void {
    const views = document.querySelectorAll('#questsTab .sub-tab-content');
    views.forEach(v => setTabPanelState(v, v.id === 'questsSubView-' + tabName));

    const btns = document.querySelectorAll('#questsTab .sub-tab-btn');
    btns.forEach(b => setTabButtonState(b, b.getAttribute('data-arg') === tabName));

    if (tabName === 'succes') {
        if (typeof window !== 'undefined') {
            window.dispatchEvent(new CustomEvent('poketime:questsSuccesTab'));
        }
        if (typeof game !== 'undefined' && game && game.updateAchievementsDisplay) {
            game.updateAchievementsDisplay();
        }
    }

    scheduleExtrasScrollReset(() => resetQuestsTabScroll());
}

export function initializeTabAccessibility() {
    const mainButtons = Array.from(document.querySelectorAll('.tabs-container .tab-btn[role="tab"]'));
    if (mainButtons.length) {
        const activeMain = mainButtons.find(btn => btn.classList.contains('active')) || mainButtons[0];
        const activeMainArg = activeMain ? activeMain.getAttribute('data-arg') : null;
        mainButtons.forEach(btn => setTabButtonState(btn, btn === activeMain));
        document.querySelectorAll('.tab-content').forEach(panel => {
            setTabPanelState(panel, !!activeMainArg && panel.id === `${activeMainArg}Tab`);
        });
    }

    const shopButtons = Array.from(
        document.querySelectorAll('#boutiqueTab > .sub-tabs-container .sub-tab-btn[role="tab"]'),
    );
    if (shopButtons.length) {
        const activeShop = shopButtons.find(btn => btn.classList.contains('active')) || shopButtons[0];
        const activeShopArg = activeShop ? activeShop.getAttribute('data-arg') : null;
        shopButtons.forEach(btn => setTabButtonState(btn, btn === activeShop));
        document.querySelectorAll('#boutiqueTab > .sub-tab-content').forEach(panel => {
            setTabPanelState(panel, !!activeShopArg && panel.id === `shop-${activeShopArg}`);
        });
    }

    const recyclerRoot = document.getElementById('recyclerContent');
    if (recyclerRoot) {
        const recyclerButtons = Array.from(
            recyclerRoot.querySelectorAll('.sub-tabs-container .sub-tab-btn[role="tab"]'),
        );
        if (recyclerButtons.length) {
            const activeRecycler = recyclerButtons.find(btn => btn.classList.contains('active')) || recyclerButtons[0];
            const activeRecyclerArg = activeRecycler ? activeRecycler.getAttribute('data-arg') : null;
            recyclerButtons.forEach(btn => setTabButtonState(btn, btn === activeRecycler));
            recyclerRoot.querySelectorAll('.sub-tab-content').forEach(panel => {
                setTabPanelState(panel, !!activeRecyclerArg && panel.id === `recycler-${activeRecyclerArg}`);
            });
        }
    }

    const pokedexButtons = Array.from(document.querySelectorAll('#pokedexTab .sub-tab-btn[role="tab"]'));
    if (pokedexButtons.length) {
        const activePokedex = pokedexButtons.find(btn => btn.classList.contains('active')) || pokedexButtons[0];
        pokedexButtons.forEach(btn => setTabButtonState(btn, btn === activePokedex));
        const activePanelId = activePokedex ? activePokedex.getAttribute('aria-controls') : null;
        ['pokedexSubView-pokedex', 'pokedexSubView-collectionbonuses'].forEach(id => {
            const panel = document.getElementById(id);
            setTabPanelState(panel, !!activePanelId && id === activePanelId);
        });
    }

    const arenaButtons = Array.from(document.querySelectorAll('.arena-subtab-btn[role="tab"]'));
    if (arenaButtons.length) {
        const activeArena = arenaButtons.find(btn => btn.classList.contains('active')) || arenaButtons[0];
        arenaButtons.forEach(btn => setTabButtonState(btn, btn === activeArena));
        const activePanelId = activeArena ? activeArena.getAttribute('aria-controls') : null;
        ['arenaGymsPanel', 'arenaElite4Panel'].forEach(id => {
            const panel = document.getElementById(id);
            setTabPanelState(panel, !!activePanelId && id === activePanelId);
        });
    }
}

