/**
 * @file src/stores/teamSnapshotGetter.ts
 * Optional bridge so publishHooks can read the live team store without importing gameFacade.
 */

import type { TeamSnapshot } from '../bus/snapshots.js';

let _getter: (() => TeamSnapshot) | null = null;

export function registerTeamSnapshotGetter(fn: () => TeamSnapshot): void {
  _getter = fn;
}

export function getRegisteredTeamSnapshot(): TeamSnapshot | null {
  return _getter ? _getter() : null;
}
