import type { StatBoost } from '../types/game/state.js';

/** Resolves which stat a timed potion boost applies to (`stat` preferred, legacy saves use `type`). */
export function getActiveStatBoostKey(boost: StatBoost | null | undefined): string {
    if (!boost) return '';
    const key = boost.stat ?? boost.type;
    return typeof key === 'string' ? key : '';
}

/** Ensures `stat` is set for readers; keeps `type` in sync for legacy paths. */
export function normalizeActiveStatBoost(boost: StatBoost): StatBoost {
    const key = getActiveStatBoostKey(boost);
    if (key) {
        boost.stat = key;
        boost.type = key;
    }
    return boost;
}

export function normalizeActiveStatBoosts(boosts: StatBoost[]): StatBoost[] {
    return boosts.map(normalizeActiveStatBoost);
}
