import { playSample } from './samples.ts';
import { playNoise, playTone } from './synth.ts';

export function playSfxCue(ctx: AudioContext, dest: AudioNode, id: string, when = ctx.currentTime): void {
    switch (id) {
        case 'click':
            playSample(ctx, dest, id, when);
            return;
        case 'success':
            playTone(ctx, dest, 392, 'triangle', 0.16, 0.12, when);
            playTone(ctx, dest, 523.25, 'triangle', 0.22, 0.12, when + 0.14);
            return;
        case 'capture':
            playNoise(ctx, dest, 0.12, 0.05, when, 600);
            playTone(ctx, dest, 349.23, 'triangle', 0.08, 0.08, when);
            playTone(ctx, dest, 440, 'triangle', 0.1, 0.08, when + 0.08);
            return;
        case 'captureFail':
            playTone(ctx, dest, 480, 'square', 0.08, 0.06, when);
            playTone(ctx, dest, 240, 'square', 0.14, 0.05, when + 0.07);
            return;
        case 'shiny':
            playTone(ctx, dest, 659.25, 'triangle', 0.1, 0.22, when);
            playTone(ctx, dest, 880, 'triangle', 0.1, 0.22, when + 0.08);
            playTone(ctx, dest, 1174.66, 'triangle', 0.16, 0.24, when + 0.16);
            return;
        case 'egg':
            playTone(ctx, dest, 392, 'triangle', 0.12, 0.2, when);
            playTone(ctx, dest, 493.88, 'triangle', 0.12, 0.2, when + 0.1);
            playTone(ctx, dest, 587.33, 'triangle', 0.18, 0.22, when + 0.2);
            return;
        case 'evolve':
            playTone(ctx, dest, 329.63, 'triangle', 0.1, 0.2, when);
            playTone(ctx, dest, 392, 'triangle', 0.1, 0.2, when + 0.09);
            playTone(ctx, dest, 493.88, 'triangle', 0.12, 0.22, when + 0.18);
            playTone(ctx, dest, 587.33, 'triangle', 0.2, 0.22, when + 0.28);
            return;
        case 'mega':
            playTone(ctx, dest, 196, 'triangle', 0.16, 0.22, when);
            playTone(ctx, dest, 392, 'triangle', 0.18, 0.2, when + 0.08);
            return;
        case 'buy':
        case 'modal':
        case 'prestige':
        case 'prestigePoint':
        case 'unfold':
        case 'fold':
        case 'equip':
        case 'unequip':
            playSample(ctx, dest, id, when);
            return;
        case 'confirm':
            playTone(ctx, dest, 349.23, 'triangle', 0.06, 0.16, when);
            playTone(ctx, dest, 440, 'triangle', 0.08, 0.16, when + 0.07);
            return;
        case 'quest':
            playTone(ctx, dest, 392, 'triangle', 0.1, 0.2, when);
            playTone(ctx, dest, 493.88, 'triangle', 0.1, 0.2, when + 0.09);
            playTone(ctx, dest, 587.33, 'triangle', 0.1, 0.18, when + 0.18);
            playTone(ctx, dest, 783.99, 'triangle', 0.18, 0.22, when + 0.27);
            return;
        case 'zone':
            playTone(ctx, dest, 440, 'triangle', 0.1, 0.2, when);
            playTone(ctx, dest, 554.37, 'triangle', 0.16, 0.22, when + 0.1);
            return;
        case 'move':
            playTone(ctx, dest, 440, 'triangle', 0.05, 0.16, when);
            playNoise(ctx, dest, 0.03, 0.03, when, 900);
            return;
        case 'collect':
            playTone(ctx, dest, 349.23, 'triangle', 0.1, 0.2, when);
            playTone(ctx, dest, 523.25, 'triangle', 0.14, 0.22, when + 0.08);
            return;
        case 'roamer':
            playTone(ctx, dest, 196, 'triangle', 0.12, 0.2, when);
            playTone(ctx, dest, 392, 'triangle', 0.16, 0.18, when + 0.1);
            playTone(ctx, dest, 587.33, 'triangle', 0.2, 0.16, when + 0.18);
            return;
        case 'achievement':
            playTone(ctx, dest, 392, 'triangle', 0.08, 0.18, when);
            playTone(ctx, dest, 493.88, 'triangle', 0.1, 0.2, when + 0.08);
            playTone(ctx, dest, 659.25, 'triangle', 0.18, 0.22, when + 0.16);
            return;
        case 'pokerus':
            playTone(ctx, dest, 261.63, 'triangle', 0.1, 0.18, when);
            playTone(ctx, dest, 349.23, 'triangle', 0.14, 0.2, when + 0.09);
            return;
        case 'runEnd':
            playTone(ctx, dest, 329.63, 'triangle', 0.12, 0.2, when);
            playTone(ctx, dest, 392, 'triangle', 0.16, 0.22, when + 0.1);
            playTone(ctx, dest, 523.25, 'triangle', 0.18, 0.18, when + 0.2);
            return;
        default:
            return;
    }
}
