/**
 * @file src/bus/gameFacade.ts
 * Central EventBus facade for Poketime.
 * Phase 1.5 — Single entry point for all game interactions.
 *
 * Usage:
 *   import { facade } from './bus/gameFacade.js';
 *
 *   // Dispatch a command (write)
 *   facade.dispatch({ type: 'CHANGE_ZONE', zone: 5 });
 *
 *   // Subscribe to events (read)
 *   const unsub = facade.subscribe('RESOURCES_CHANGED', (evt) => { ... });
 *
 *   // Get a read-only snapshot
 *   const snap = facade.getSnapshot();
 */

