// ─── Debounce configuration (trailing edge) ───
//
// IMPORTANT: This is a DEBOUNCE, not a throttle.
// When multiple events of the same type arrive within the window,
// only the LAST one is published after the delay.
// Intermediate states are discarded.
//
// This is acceptable for high-frequency events like RESOURCES_CHANGED
// (only the final resource values matter). For COMBAT_STATE_CHANGED,
// consider using a shorter window or requestAnimationFrame-based sampling
// if intermediate states become important for UI animations.

const DEBOUNCE_MS: Record<string, number> = {
  [Evt.RESOURCES_CHANGED]: 200,
  [Evt.TEAM_CHANGED]: 0,
  [Evt.STORAGE_CHANGED]: 32,
  [Evt.PENSION_CHANGED]: 500,
  [Evt.COMBAT_STATE_CHANGED]: 16,  // ~1 frame at 60fps
  [Evt.DPS_METER_UPDATED]: 100,
  [Evt.FARMING_METRICS_UPDATED]: 100,
  [Evt.MART_AUTO_PURCHASE_UPDATED]: 100,
  [Evt.AFK_SUMMARY_CHANGED]: 100,
  [Evt.STATE_UPDATED]: 500,
};

/** Force publish after this many ms even if debounce keeps resetting (120/144 Hz RAF). */
const MAX_WAIT_MS: Record<string, number> = {
  [Evt.COMBAT_STATE_CHANGED]: 16,
};

// Debounce timers (one per event type)
const _debounceTimers: Record<string, ReturnType<typeof setTimeout> | null> = {};
const _debounceWindowStart: Record<string, number> = {};
const _debouncePendingBuild: Record<string, () => GameEvent | null> = {};

/** Reuse enriched creature metadata between HP-only combat ticks. */
const _combatCreatureCache = {
  enemy: { uid: '', snap: null as CreatureSnapshot | null },
  player: { uid: '', snap: null as CreatureSnapshot | null },
};

// ─── Subscriber store ───

type EventHandler = (event: GameEvent) => void;
const _subscribers = new Map<string, Set<EventHandler>>();

// ─── Snapshot cache (Phase 3.4) ───
// Avoids rebuilding the full snapshot on every subscriber call.
// Invalidated after CACHE_TTL_MS or when the game version changes.

let _cachedSnapshot: GameSnapshot | null = null;
let _cachedAt: number = 0;
let _snapshotSeq: number = 0;
const SNAPSHOT_CACHE_TTL_MS = 50; // rebuild at most every 50ms

/**
 * Call this from game mutation points to invalidate the snapshot cache.
 * Each mutation increments the sequence, forcing the next getSnapshot() to rebuild.
 */
function invalidateSnapshotCache(): void {
  _snapshotSeq++;
  _cachedSnapshot = null;
  _combatCreatureCache.enemy.uid = '';
  _combatCreatureCache.enemy.snap = null;
  _combatCreatureCache.player.uid = '';
  _combatCreatureCache.player.snap = null;
}

function _combatCreatureIdentity(c: CreatureData): string {
  const uid = (c as { uid?: string }).uid;
  if (typeof uid === 'string' && uid) return uid;
  const prestige = Number(c.prestige) || 0;
  return `${c.name}|${prestige}|${c.isShiny ? 1 : 0}`;
}

function _combatCreatureSnapshot(
  c: CreatureData | null,
  cache: { uid: string; snap: CreatureSnapshot | null },
): CreatureSnapshot | null {
  if (!c) {
    cache.uid = '';
    cache.snap = null;
    return null;
  }
  const gm = g()!;
  const uid = _combatCreatureIdentity(c);
  const currentHp = Number(c.currentHp) || 0;
  const maxHp = Number(c.maxHp) || 1;
  if (cache.uid === uid && cache.snap) {
    if (cache.snap.currentHp === currentHp && cache.snap.maxHp === maxHp) {
      return cache.snap;
    }
    const updated = { ...cache.snap, currentHp, maxHp };
    cache.snap = updated;
    return updated;
  }
  const snap =
    _creatureToSnapshot(c, gm, 'team') ?? minimalCreatureSnapshot(gm, c);
  const withHp = { ...snap, currentHp, maxHp };
  cache.uid = uid;
  cache.snap = withHp;
  return withHp;
}

// ─── Snapshot builders ───

/** Returns null when game is not registered yet (e.g. mid-constructor before setGameInstance). */
function g(): GameRuntime | null {
  return game ?? null;
}

/** Lightweight resources payload for publishResourcesChanged (no full game snapshot). */
export function buildResourceSnapshot(): ResourceSnapshot | null {
  if (!g()) return null;
  return _buildResourceSnapshot();
}

function _buildResourceSnapshot(): ResourceSnapshot {
  const gm = g()!;
  return {
    pokedollars: gm.pokedollars ?? 0,
    shards: { ...gm.shards },
    essenceDust: gm.essenceDust ?? 0,
    talentRerolls: gm.talentRerolls ?? 0,
    talentChoices: gm.talentChoices ?? 0,
    questTokens: gm.questTokens ?? 0,
    combatTickets: gm.combatTickets ?? 0,
    triumphMarks: gm.triumphMarks ?? 0,
    activeVitamins: { ...gm.activeVitamins } as ResourceSnapshot['activeVitamins'],
  };
}

function _creatureToSnapshot(
  c: CreatureData | null,
  gm?: GameRuntime | null,
  spriteContext: 'team' | 'pension' | 'storage' = 'team',
) {
  if (!c) return null;
  const runtime = gm ?? g();
  if (!runtime) return null;
  try {
    return enrichCreatureSnapshot(runtime, c, spriteContext);
  } catch (err) {
    debugError('[gameFacade] enrichCreatureSnapshot failed for', c.name, err);
    return minimalCreatureSnapshot(runtime, c);
  }
}

/** One snapshot per team/pension slot — never compact/filter (keeps index 0 = game.playerTeam[0]). */
export function mapRosterSlots(
  gm: GameRuntime,
  arr: CreatureData[],
  spriteContext: 'team' | 'pension' | 'storage' = 'team',
): CreatureSnapshot[] {
  const out: CreatureSnapshot[] = [];
  for (let i = 0; i < arr.length; i++) {
    const c = arr[i];
    if (!c) continue;
    out[i] = _creatureToSnapshot(c, gm, spriteContext) ?? minimalCreatureSnapshot(gm, c);
  }
  return out;
}

type HeaderStatKey = 'hp' | 'attack' | 'spattack' | 'defense' | 'spdefense' | 'speed';

const HEADER_STAT_KEYS: HeaderStatKey[] = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'];

function _buildPassiveGains(gm: GameRuntime): TeamSnapshot['passiveGainsPerSec'] {
  if (typeof gm.getPassiveStatGainPerSecond === 'function') {
    const gains = gm.getPassiveStatGainPerSecond();
    return {
      hp: gains.hp ?? 0,
      attack: gains.attack ?? 0,
      spattack: gains.spattack ?? 0,
      defense: gains.defense ?? 0,
      spdefense: gains.spdefense ?? 0,
      speed: gains.speed ?? 0,
    };
  }

  const pensionStats = gm.calculatePensionStats?.() ?? { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 };
  const baseContribution = 0.10;
  const towerBonus = gm.permanentBoosts?.team_contribution ?? 0;
  const teamContributionRate = baseContribution + towerBonus;
  const vit = gm.activeVitamins ?? {};
  const vitaminBonus = buildVitaminBonusMultipliers(
    vit,
    getTotalVitaminEfficiency(gm.vitaminEfficiency, gm.farmMilkEfficiency),
  );
  const team = gm.playerTeamStats ?? {};
  return {
    hp: ((team.hp ?? 0) * teamContributionRate + (pensionStats.hp ?? 0)) * vitaminBonus.hp,
    attack: ((team.attack ?? 0) * teamContributionRate + (pensionStats.attack ?? 0)) * vitaminBonus.attack,
    spattack: ((team.spattack ?? 0) * teamContributionRate + (pensionStats.spattack ?? 0)) * vitaminBonus.spattack,
    defense: ((team.defense ?? 0) * teamContributionRate + (pensionStats.defense ?? 0)) * vitaminBonus.defense,
    spdefense: ((team.spdefense ?? 0) * teamContributionRate + (pensionStats.spdefense ?? 0)) * vitaminBonus.spdefense,
    speed: ((team.speed ?? 0) * teamContributionRate + (pensionStats.speed ?? 0)) * vitaminBonus.speed,
  };
}

function _buildHeaderStatBoosted(gm: GameRuntime): TeamSnapshot['headerStatBoosted'] {
  const headerStatBoosted: TeamSnapshot['headerStatBoosted'] = {
    hp: false, attack: false, spattack: false, defense: false, spdefense: false, speed: false,
  };
  for (const stat of HEADER_STAT_KEYS) {
    if (typeof gm.getBoostInfoForStat === 'function') {
      headerStatBoosted[stat] = gm.getBoostInfoForStat(stat).length > 0;
    }
  }
  return headerStatBoosted;
}

/** Header chip values — main stats + potions + synergies + collections + aura. */
function _buildHeaderDisplayStats(gm: GameRuntime): TeamSnapshot['teamStats'] {
  return buildDisplayedHeaderStats(gm);
}

/** Header stats + gains only — no creature roster build (perf). */
export function buildTeamHeaderStatsSnapshot(): TeamHeaderStatsSnapshot {
  const gm = g();
  if (!gm) {
    const empty = { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 };
    const emptyBoosted = { hp: false, attack: false, spattack: false, defense: false, spdefense: false, speed: false };
    return {
      teamStats: { ...empty },
      passiveGainsPerSec: { ...empty },
      headerStatBoosted: { ...emptyBoosted },
    };
  }
  return {
    teamStats: _buildHeaderDisplayStats(gm),
    passiveGainsPerSec: _buildPassiveGains(gm),
    headerStatBoosted: _buildHeaderStatBoosted(gm),
  };
}

export type BuildTeamSnapshotOptions = {
  /** When false, skips filtered storage grid build (use with publishStorageChanged). */
  withStorageRoster?: boolean;
};

/** Team roster snapshot for publishTeamChanged — optional storage slice. */
export function buildTeamSnapshot(options?: BuildTeamSnapshotOptions): TeamSnapshot | null {
  const gm = g();
  if (!gm) return null;
  const withStorageRoster = options?.withStorageRoster !== false;
  if (typeof gm.calculateTeamStats === 'function') gm.calculateTeamStats();
  const pt = (gm.playerTeam || []);
  const pens = (gm.pension || []);
  const storage = gm.storage || [];
  const mapTeam = (arr: CreatureData[]) => mapRosterSlots(gm, arr, 'team');
  const mapPension = (arr: CreatureData[]) => mapRosterSlots(gm, arr, 'pension');
  const maxTeamSize = getMaxTeamSize(gm);
  const maxPensionSlots = typeof gm.getPensionSlots === 'function' ? gm.getPensionSlots() : 0;
  const ultimateSlotUnlocked = isUltimateSlotUnlocked(gm);
  const ultimateTransferRate =
    typeof gm.getUltimateSlotTransferRate === 'function' ? gm.getUltimateSlotTransferRate() : 0;
  const ultimateBonus =
    typeof gm.getUltimateSlotTeamFlatBonus === 'function'
      ? gm.getUltimateSlotTeamFlatBonus()
      : { hp: 0, attack: 0, spattack: 0, defense: 0, spdefense: 0, speed: 0 };
  const ultimateCreature = gm.ultimateSlot
    ? mapRosterSlots(gm, [gm.ultimateSlot], 'storage')[0] ?? null
    : null;
  const headerStatBoosted = _buildHeaderStatBoosted(gm);
  const teamTransferRate =
    ((typeof gm.getTeamContributionRate === 'function' ? gm.getTeamContributionRate() : 0.1)) * 100;
  const pensionTransferRate =
    (typeof gm.getPensionTransferRate === 'function' ? gm.getPensionTransferRate() : 0) * 100;
  const faintedTeamIndices = buildFaintedTeamIndices(gm);
  const storageRoster = withStorageRoster ? buildStorageRoster(gm) : null;

  return {
    playerTeam: mapTeam(pt),
    pension: mapPension(pens),
    storageCount: Array.isArray(storage) ? storage.length : 0,
    teamStats: _buildHeaderDisplayStats(gm),
    passiveGainsPerSec: _buildPassiveGains(gm),
    maxTeamSize,
    maxPensionSlots,
    teamCountLabel: `${pt.length}/${maxTeamSize}`,
    pensionCountLabel: `${pens.length}/${maxPensionSlots}`,
    headerStatBoosted,
    activeCreatureIndex: gm.activeCreatureIndex ?? 0,
    faintedTeamIndices,
    teamSpritesOnly: !!gm.teamSpritesOnly,
    teamContributionRatePercent: teamTransferRate.toFixed(0),
    pensionTransferRatePercent: pensionTransferRate.toFixed(0),
    labels: {
      levelShort: typeof gm.t === 'function' ? gm.t('state.levelShort') : 'Lvl',
      viewDetails: typeof gm.t === 'function' ? gm.t('team.viewDetails') : 'View details',
      teamContributionPrefix:
        typeof gm.t === 'function'
          ? gm.t('tooltip.teamContributionTitle')
          : 'Contribution',
      pensionContributionPrefix:
        typeof gm.t === 'function'
          ? gm.t('tooltip.daycareContribution', { percent: pensionTransferRate.toFixed(0) })
          : 'Contribution',
    },
    storageRoster: storageRoster ? storageRoster.creatures : [],
    storageFilteredCountLabel: storageRoster
      ? `${storageRoster.filteredCount}/${storageRoster.totalOwned}`
      : '',
    storageShowEmptyFiltered: storageRoster ? storageRoster.showEmptyFiltered : false,
    storageSortStack: Array.isArray(gm.storageSortStack)
      ? gm.storageSortStack.map((entry) => ({ ...entry }))
      : [],
    storageSortByBaseStats: !!gm.storageSortByBaseStats,
    pensionSortKey: gm.pensionSortKey ?? null,
    pensionSortOrder: gm.pensionSortOrder ?? 'desc',
    pensionSortStats: gm.pensionSortStats && gm.pensionSortStats.length > 0 ? [...gm.pensionSortStats] : (gm.pensionSortKey ? pensionSortKeyToStats(gm.pensionSortKey) : []),
    resonancePreview: buildResonanceTeamPreview(gm),
    ultimateSlotUnlocked,
    ultimateSlot: ultimateCreature,
    ultimateSlotTransferPercent: (ultimateTransferRate * 100).toFixed(0),
    ultimateSlotBonus: { ...ultimateBonus },
  };
}

function _buildTeamSnapshot(): TeamSnapshot {
  return buildTeamSnapshot()!;
}

/** Zone fields for publishZoneChanged without full game snapshot. */
export function buildZoneSnapshot(): ZoneSnapshot | null {
  const gm = g();
  if (!gm) return null;
  return _buildZoneSnapshot();
}

function _buildPlayerHudHp(gm: GameRuntime): { current: number; max: number } {
  const creature = gm.currentPlayerCreature;
  if (!creature) return { current: 0, max: 1 };

  const trainerBattle = isTrainerBattle(gm);

  let maxHp = trainerBattle ? (creature.maxHp || 1) : gm.getPlayerMaxHp();
  let currentHp = trainerBattle
    ? creature.currentHp
    : (creature.mainAccountCurrentHp ?? maxHp);

  if (isNaN(maxHp) || maxHp === 0) maxHp = 1;
  if (isNaN(currentHp)) currentHp = 0;
  currentHp = Math.max(0, currentHp);

  return { current: currentHp, max: maxHp };
}

/** Storage slice for publishStorageChanged without rebuilding team roster. */
export function buildStorageChangedPayload(
  previousRoster?: StorageCardSnapshot[] | null,
): Pick<
  TeamSnapshot,
  'storageRoster' | 'storageFilteredCountLabel' | 'storageShowEmptyFiltered'
> | null {
  const gm = g();
  if (!gm) return null;
  const storageRoster =
    (previousRoster?.length ? tryAppendStorageRoster(gm, previousRoster) : null)
    ?? buildStorageRoster(gm);
  return {
    storageRoster: storageRoster.creatures,
    storageFilteredCountLabel: `${storageRoster.filteredCount}/${storageRoster.totalOwned}`,
    storageShowEmptyFiltered: storageRoster.showEmptyFiltered,
  };
}

function _buildCombatSnapshot(): CombatSnapshot {
  const gm = g()!;
  const playerHud = _buildPlayerHudHp(gm);
  return {
    state: gm.combatState ?? 'idle',
    currentEnemy: _combatCreatureSnapshot(
      gm.currentEnemy,
      _combatCreatureCache.enemy,
    ),
    currentPlayerCreature: _combatCreatureSnapshot(
      gm.currentPlayerCreature,
      _combatCreatureCache.player,
    ),
    playerHudCurrentHp: playerHud.current,
    playerHudMaxHp: playerHud.max,
    combatSpeed: gm.combatSpeed ?? 1,
    captureMode: gm.captureMode ?? 0,
    autoMaster: !!gm.autoMaster,
  };
}

function _buildZoneSnapshot(): ZoneSnapshot {
  const gm = g()!;
  return {
    currentZone: Number(currentZone) || 0,
    maxReachedZone: Number(maxReachedZone) || 0,
    currentRegion: String(currentRegion || 'kanto'),
    zoneName: String(gm.currentZoneName ?? ''),
  };
}

function _buildSettingsSnapshot(): SettingsSnapshot {
  const gm = g()!;
  return {
    language: gm.language ?? 'fr',
    teamSpritesOnly: !!gm.teamSpritesOnly,
    animatedSprites: gm.animatedSprites ? {
        active: !!gm.animatedSprites.active,
        team: !!gm.animatedSprites.team,
        pension: !!gm.animatedSprites.pension,
        all: !!gm.animatedSprites.all
    } : { active: false, team: false, pension: false, all: false },
    reducedMotion: !!gm.reducedMotion,
    afkMode: !!gm.afkMode,
    pauseOnRare: !!gm.pauseOnRare,
    notifyRareDrop: !!gm.notifyRareDrop,
    notifyEggHatch: !!gm.notifyEggHatch,
    notifyCapture: !!gm.notifyCapture,
    notifyDpsRecord: !!gm.notifyDpsRecord,
    notifyQuest: !!gm.notifyQuest,
    damagePopupMode: gm.damagePopupMode ?? 'true',
    selectedHeaderSkin: gm.selectedHeaderSkin ?? '',
    headerPanelOpacity: gm.headerPanelOpacity ?? 0.8,
  };
}

// ─── Core API ───

/**
 * Execute a typed command against the game instance.
 * Commands are validated at compile-time via the GameCommand union.
 */
function dispatch(cmd: GameCommand): void {
  executeCommand(cmd);
}

/**
 * Subscribe to a game event. Returns an unsubscribe function.
 */
function subscribe(eventType: GameEventType, handler: EventHandler): () => void {
  if (!_subscribers.has(eventType)) {
    _subscribers.set(eventType, new Set());
  }
  _subscribers.get(eventType)!.add(handler);
  trackFacadeSubscribe(eventType, 1);

  return () => {
    const set = _subscribers.get(eventType);
    if (set) {
      set.delete(handler);
      trackFacadeSubscribe(eventType, -1);
      if (set.size === 0) _subscribers.delete(eventType);
    }
  };
}

/**
 * Publish a game event to all subscribers, with debouncing support (trailing edge).
 * See DEBOUNCE_MS configuration above for per-event-type windows.
 */
function _flushDebounced(eventType: GameEventType): void {
  _debounceTimers[eventType] = null;
  _debounceWindowStart[eventType] = 0;
  const pending = _debouncePendingBuild[eventType];
  if (pending) {
    delete _debouncePendingBuild[eventType];
    const event = pending();
    if (event) _notifySubscribers(event);
    return;
  }
}

function _scheduleDebounced(
  eventType: GameEventType,
  buildEvent: () => GameEvent | null,
): void {
  const debounceMs = DEBOUNCE_MS[eventType];
  const maxWaitMs = MAX_WAIT_MS[eventType];

  if (debounceMs == null || debounceMs <= 0) {
    const event = buildEvent();
    if (event) _notifySubscribers(event);
    return;
  }

  _debouncePendingBuild[eventType] = buildEvent;
  const now = Date.now();
  if (!_debounceWindowStart[eventType]) _debounceWindowStart[eventType] = now;

  if (maxWaitMs != null && maxWaitMs > 0 && now - _debounceWindowStart[eventType] >= maxWaitMs) {
    const existing = _debounceTimers[eventType];
    if (existing != null) clearTimeout(existing);
    _flushDebounced(eventType);
    return;
  }

  const existing = _debounceTimers[eventType];
  if (existing != null) clearTimeout(existing);

  _debounceTimers[eventType] = setTimeout(() => {
    _flushDebounced(eventType);
  }, debounceMs);
}

function publish(event: GameEvent): void {
  _scheduleDebounced(event.type, () => event);
}

/**
 * Debounced publish with lazy payload (build runs when the timer fires).
 * Use for high-frequency events where only the latest Game state matters.
 */
function publishDeferred(eventType: GameEventType, buildEvent: () => GameEvent | null): void {
  _scheduleDebounced(eventType, buildEvent);
}

function _notifySubscribers(event: GameEvent): void {
  trackFacadePublish(event.type);
  const set = _subscribers.get(event.type);
  if (!set || set.size === 0) return;
  for (const handler of set) {
    try {
      handler(event);
    } catch (err) {
      debugError('[GameFacade] Subscriber error for', event.type, err);
    }
  }
}

/**
 * Build a complete read-only snapshot of the current game state.
 * Results are cached for SNAPSHOT_CACHE_TTL_MS to avoid rebuilding
 * when multiple subscribers request the same data in quick succession.
 * The cache is invalidated by _invalidateSnapshotCache() at mutation points.
 */
function getSnapshot(): GameSnapshot | null {
  if (!g()) return null;
  const now = Date.now();
  if (_cachedSnapshot && (now - _cachedAt) < SNAPSHOT_CACHE_TTL_MS) {
    return _cachedSnapshot;
  }
  _cachedSnapshot = {
    resources: _buildResourceSnapshot(),
    team: _buildTeamSnapshot(),
    combat: _buildCombatSnapshot(),
    zone: _buildZoneSnapshot(),
    settings: _buildSettingsSnapshot(),
    timestamp: now,
  };
  _cachedAt = now;
  return _cachedSnapshot;
}

// ─── Singleton export ───

// Phase 3.2 — bridge publish + getSnapshot to pub.ts for commandHandlers & mutation points
setFacadePublish(publish);
setFacadePublishDeferred(publishDeferred);
setFacadeBuildCombatSnapshot(() => (g() ? _buildCombatSnapshot() : null));
setFacadeGetSnapshot(getSnapshot);
setFacadeInvalidateSnapshot(invalidateSnapshotCache);

if (isFacadeDebugEnabled()) {
  startFacadeDebugWatcher();
  installFacadeDebugGlobal();
}

export const facade = {
  dispatch,
  subscribe,
  publish,
  getSnapshot,
  invalidateSnapshotCache,
};
