/**
 * @file src/lib/shopPurchaseFeedback.ts
 * Visual button feedback for shop purchases (survives Svelte {@html} refresh delay).
 */

let shopRefreshHoldUntil = 0;

/** Delay shop snapshot refresh so purchase press animation is visible before DOM replace. */
export function getShopRefreshDelayMs(): number {
  return Math.max(0, shopRefreshHoldUntil - Date.now());
}

export function armShopRefreshHold(ms = 280): void {
  shopRefreshHoldUntil = Math.max(shopRefreshHoldUntil, Date.now() + ms);
}

/** @internal Vitest */
export function resetShopPurchaseFeedbackForTests(): void {
  shopRefreshHoldUntil = 0;
}

export function flashShopPurchaseButton(dataAction: string, dataArg: string): void {
  const sel = `[data-action="${CSS.escape(dataAction)}"][data-arg="${CSS.escape(String(dataArg))}"]`;
  const btn = document.querySelector(sel);
  if (!(btn instanceof HTMLButtonElement) || btn.disabled) return;
  btn.classList.remove('shop-purchase-pressed');
  void btn.offsetWidth;
  btn.classList.add('shop-purchase-pressed');
  armShopRefreshHold();
  window.setTimeout(() => btn.classList.remove('shop-purchase-pressed'), 280);
}
