/** Read a sample without fetch() when Vite inlined it as a data URL (CSP connect-src is 'self'). */

function bytesFromDataUrl(url: string): ArrayBuffer | null {
    const comma = url.indexOf(',');
    if (comma < 0) return null;
    const meta = url.slice(0, comma);
    const payload = url.slice(comma + 1);
    try {
        if (meta.includes(';base64')) {
            const binary = atob(payload);
            const bytes = new Uint8Array(binary.length);
            for (let i = 0; i < binary.length; i += 1) bytes[i] = binary.charCodeAt(i);
            return bytes.buffer;
        }
        return new TextEncoder().encode(decodeURIComponent(payload)).buffer;
    } catch {
        return null;
    }
}

export function readAudioBytes(url: string): Promise<ArrayBuffer | null> {
    if (url.startsWith('data:')) return Promise.resolve(bytesFromDataUrl(url));
    return fetch(url)
        .then((response) => (response.ok ? response.arrayBuffer() : null))
        .catch(() => null);
}
