export interface AudioFlags {
    offline: boolean;
    afk: boolean;
}

export const CUE_COOLDOWN_MS: Record<string, number> = {
    click: 40,
    success: 400,
    capture: 400,
    captureFail: 400,
    shiny: 800,
    egg: 600,
    evolve: 800,
    mega: 800,
    buy: 180,
    confirm: 280,
    prestigePoint: 280,
    modal: 120,
    unfold: 120,
    fold: 120,
    equip: 180,
    unequip: 180,
    quest: 700,
    zone: 2500,
    prestige: 700,
    move: 90,
    collect: 700,
    roamer: 800,
    achievement: 700,
    pokerus: 700,
    runEnd: 800,
};

export function cueCooldownMs(id: string): number | null {
    const ms = CUE_COOLDOWN_MS[id];
    return typeof ms === 'number' ? ms : null;
}

/** Menu groups. Every cooldown id appears once. */
export const SFX_MENU_GROUPS: { id: string; cues: string[] }[] = [
    { id: 'capture', cues: ['capture', 'captureFail', 'shiny'] },
    { id: 'progress', cues: ['egg', 'evolve', 'mega', 'prestige', 'zone', 'runEnd'] },
    { id: 'reward', cues: ['quest', 'collect', 'achievement', 'roamer', 'pokerus', 'success'] },
    { id: 'action', cues: ['buy', 'equip', 'unequip', 'prestigePoint', 'confirm', 'move', 'click', 'modal', 'unfold', 'fold'] },
];

export function canPlayCue(
    id: string,
    flags: AudioFlags,
    muted: boolean,
    lastAt: number,
    now: number,
): boolean {
    if (flags.offline || muted) return false;
    const cooldown = cueCooldownMs(id);
    if (cooldown == null) return false;
    return now - lastAt >= cooldown;
}
