import clickUrl from './samples/click.wav?url';
import buyUrl from './samples/buy.wav?url';
import modalUrl from './samples/modal.wav?url';
import prestigeUrl from './samples/prestige.wav?url';
import prestigePointUrl from './samples/prestige-point.wav?url';
import unfoldUrl from './samples/unfold.wav?url';
import foldUrl from './samples/fold.wav?url';
import equipUrl from './samples/equip.wav?url';
import unequipUrl from './samples/unequip.wav?url';
import { readAudioBytes } from './readAudioBytes.ts';

const SAMPLE_URLS: Record<string, string> = {
    click: clickUrl,
    buy: buyUrl,
    modal: modalUrl,
    prestige: prestigeUrl,
    prestigePoint: prestigePointUrl,
    unfold: unfoldUrl,
    fold: foldUrl,
    equip: equipUrl,
    unequip: unequipUrl,
};

const fileBytes = new Map<string, Promise<ArrayBuffer | null>>();
const decoded = new WeakMap<AudioContext, Map<string, AudioBuffer>>();
const decoding = new WeakMap<AudioContext, Map<string, Promise<AudioBuffer | null>>>();

function bytesFor(id: string): Promise<ArrayBuffer | null> {
    const url = SAMPLE_URLS[id];
    if (!url) return Promise.resolve(null);
    let pending = fileBytes.get(id);
    if (!pending) {
        pending = readAudioBytes(url);
        fileBytes.set(id, pending);
    }
    return pending;
}

for (const id of Object.keys(SAMPLE_URLS)) void bytesFor(id);

function contextBuffers(ctx: AudioContext): Map<string, AudioBuffer> {
    let buffers = decoded.get(ctx);
    if (!buffers) {
        buffers = new Map();
        decoded.set(ctx, buffers);
    }
    return buffers;
}

function decodeCue(ctx: AudioContext, id: string): Promise<AudioBuffer | null> {
    const buffers = contextBuffers(ctx);
    const ready = buffers.get(id);
    if (ready) return Promise.resolve(ready);
    let jobs = decoding.get(ctx);
    if (!jobs) {
        jobs = new Map();
        decoding.set(ctx, jobs);
    }
    let job = jobs.get(id);
    if (!job) {
        job = bytesFor(id).then(async (bytes) => {
            if (!bytes || bytes.byteLength === 0 || typeof ctx.decodeAudioData !== 'function') return null;
            try {
                const buffer = await ctx.decodeAudioData(bytes.slice(0));
                buffers.set(id, buffer);
                return buffer;
            } catch {
                return null;
            }
        });
        jobs.set(id, job);
    }
    return job;
}

export function preloadCueSamples(ctx: AudioContext): void {
    for (const id of Object.keys(SAMPLE_URLS)) void decodeCue(ctx, id);
}

export function playSample(ctx: AudioContext, dest: AudioNode, id: string, when: number): void {
    const buffer = contextBuffers(ctx).get(id);
    if (!buffer) {
        void decodeCue(ctx, id);
        return;
    }
    if (typeof ctx.createBufferSource !== 'function') return;
    const source = ctx.createBufferSource();
    source.buffer = buffer;
    source.connect(dest);
    source.start(when);
}
