/**
 * @file src/lib/pensionSortUtils.ts
 * Pure helpers for daycare/pension sorting by contribution (total, per-stat, and multi-stats).
 */

import {
  computeCreatureContribution,
  sumContributionTotal,
  type ContributionStatBlock,
} from './contributionTooltip.ts';

export const PENSION_STAT_KEYS = [
  'hp',
  'attack',
  'spattack',
  'defense',
  'spdefense',
  'speed',
] as const;

export type PensionStatKey = (typeof PENSION_STAT_KEYS)[number];

export const PENSION_SORT_KEYS = [
  'total',
  ...PENSION_STAT_KEYS,
] as const;

export type PensionSortKey = (typeof PENSION_SORT_KEYS)[number];
export type PensionSortOrder = 'asc' | 'desc';

export const PENSION_SORT_I18N_KEYS: Record<PensionSortKey, string> = {
  total: 'pension.sortTotalContribution',
  hp: 'storage.sortHp',
  attack: 'storage.sortAttack',
  spattack: 'storage.sortSpAttack',
  defense: 'storage.sortDefense',
  spdefense: 'storage.sortSpDefense',
  speed: 'storage.sortSpeed',
};

export const PENSION_STAT_SHORT_LABELS: Record<PensionStatKey, string> = {
  hp: 'PV',
  attack: 'ATK',
  spattack: 'ATK Spé',
  defense: 'DEF',
  spdefense: 'DEF Spé',
  speed: 'VIT',
};

export interface PensionSortCreature {
  uid: string;
  name?: string;
  level?: number;
  maxHp?: number;
  attack?: number;
  spattack?: number;
  defense?: number;
  spdefense?: number;
  speed?: number;
  [key: string]: unknown;
}

export function isPensionSortKey(key: unknown): key is PensionSortKey {
  return typeof key === 'string' && (PENSION_SORT_KEYS as readonly string[]).includes(key);
}

export function isPensionStatKey(key: unknown): key is PensionStatKey {
  return typeof key === 'string' && (PENSION_STAT_KEYS as readonly string[]).includes(key);
}

export function normalizePensionSortStats(rawStats: unknown): PensionStatKey[] {
  if (!Array.isArray(rawStats)) return [];
  const valid: PensionStatKey[] = [];
  for (const s of rawStats) {
    if (isPensionStatKey(s) && !valid.includes(s)) {
      valid.push(s);
    }
  }
  return valid;
}

export function statsToPensionSortKey(stats: readonly PensionStatKey[]): PensionSortKey | null {
  if (!stats || stats.length === 0) return null;
  if (stats.length === PENSION_STAT_KEYS.length) return 'total';
  if (stats.length === 1 && stats[0]) return stats[0];
  return 'total';
}

export function pensionSortKeyToStats(key: PensionSortKey | null): PensionStatKey[] {
  if (!key) return [];
  if (key === 'total') return [...PENSION_STAT_KEYS];
  return [key];
}

/**
 * Computes the contribution value for a given sort criteria:
 * - Single stat key: 'hp', 'attack', etc.
 * - 'total': weighted total matching tooltip (HP half-weighted)
 * - Array of PensionStatKey: sum of contributions for selected stats
 */
export function getPensionSortValue(
  creature: PensionSortCreature,
  keyOrStats: PensionSortKey | readonly PensionStatKey[],
  rate: number,
): number {
  const block = computeCreatureContribution(
    {
      maxHp: creature.maxHp ?? 0,
      attack: creature.attack ?? 0,
      spattack: creature.spattack ?? 0,
      defense: creature.defense ?? 0,
      spdefense: creature.spdefense ?? 0,
      speed: creature.speed ?? 0,
    },
    rate,
  );

  if (Array.isArray(keyOrStats)) {
    if (keyOrStats.length === 0) return 0;
    if (keyOrStats.length === PENSION_STAT_KEYS.length) {
      return sumContributionTotal(block);
    }
    let sum = 0;
    for (const s of keyOrStats) {
      if (s === 'hp') {
        sum += Math.floor(block.hp / 2);
      } else {
        sum += block[s as keyof ContributionStatBlock];
      }
    }
    return Math.floor(sum);
  }

  if (keyOrStats === 'total') {
    return sumContributionTotal(block);
  }
  return block[keyOrStats as keyof ContributionStatBlock];
}

function isPensionStatKeyList(
  value: PensionSortKey | readonly PensionStatKey[],
): value is readonly PensionStatKey[] {
  return Array.isArray(value);
}

function getRawStatValue(
  creature: PensionSortCreature,
  keyOrStats: PensionSortKey | readonly PensionStatKey[],
): number {
  if (isPensionStatKeyList(keyOrStats)) {
    if (keyOrStats.length === 0 || keyOrStats.length === PENSION_STAT_KEYS.length) {
      return (
        Math.floor((creature.maxHp ?? 0) / 2) +
        (creature.attack ?? 0) +
        (creature.spattack ?? 0) +
        (creature.defense ?? 0) +
        (creature.spdefense ?? 0) +
        (creature.speed ?? 0)
      );
    }
    let sum = 0;
    for (const s of keyOrStats) {
      if (s === 'hp') {
        sum += Math.floor((creature.maxHp ?? 0) / 2);
      } else {
        sum += Number(creature[s]) || 0;
      }
    }
    return sum;
  }

  if (keyOrStats === 'total') {
    return (
      Math.floor((creature.maxHp ?? 0) / 2) +
      (creature.attack ?? 0) +
      (creature.spattack ?? 0) +
      (creature.defense ?? 0) +
      (creature.spdefense ?? 0) +
      (creature.speed ?? 0)
    );
  }
  if (keyOrStats === 'hp') {
    return creature.maxHp ?? 0;
  }
  return Number(creature[keyOrStats as keyof PensionSortCreature]) || 0;
}

export function comparePensionCreatures(
  a: PensionSortCreature,
  b: PensionSortCreature,
  keyOrStats: PensionSortKey | readonly PensionStatKey[],
  order: PensionSortOrder,
  rate: number,
): number {
  // 1. Primary contribution value
  const valA = getPensionSortValue(a, keyOrStats, rate);
  const valB = getPensionSortValue(b, keyOrStats, rate);
  if (valA !== valB) {
    return order === 'asc' ? valA - valB : valB - valA;
  }

  // 2. Secondary tie-breaker: total contribution (if primary is a subset of stats)
  const isCompleteTotal =
    keyOrStats === 'total' ||
    (Array.isArray(keyOrStats) && keyOrStats.length === PENSION_STAT_KEYS.length);

  if (!isCompleteTotal) {
    const totA = getPensionSortValue(a, 'total', rate);
    const totB = getPensionSortValue(b, 'total', rate);
    if (totA !== totB) {
      return order === 'asc' ? totA - totB : totB - totA;
    }
  }

  // 3. Raw stat value (before rate floor)
  const rawA = getRawStatValue(a, keyOrStats);
  const rawB = getRawStatValue(b, keyOrStats);
  if (rawA !== rawB) {
    return order === 'asc' ? rawA - rawB : rawB - rawA;
  }

  // 4. Creature level
  const lvlA = a.level ?? 0;
  const lvlB = b.level ?? 0;
  if (lvlA !== lvlB) {
    return order === 'asc' ? lvlA - lvlB : lvlB - lvlA;
  }

  // 5. Deterministic tie-breaker
  return a.uid.localeCompare(b.uid);
}

export function sortPensionCreatures<T extends PensionSortCreature>(
  creatures: T[],
  keyOrStats: PensionSortKey | readonly PensionStatKey[] | null,
  order: PensionSortOrder,
  rate: number,
): T[] {
  if (
    !keyOrStats ||
    (Array.isArray(keyOrStats) && keyOrStats.length === 0) ||
    creatures.length <= 1
  ) {
    return creatures.slice();
  }
  return creatures.slice().sort((a, b) => comparePensionCreatures(a, b, keyOrStats, order, rate));
}

export function normalizePensionSort(
  rawKey: unknown,
  rawOrder: unknown,
  rawStats?: unknown,
): { key: PensionSortKey | null; order: PensionSortOrder; stats: PensionStatKey[] } {
  const order: PensionSortOrder = rawOrder === 'asc' ? 'asc' : 'desc';

  if (Array.isArray(rawStats)) {
    const stats = normalizePensionSortStats(rawStats);
    const key = statsToPensionSortKey(stats);
    return { key, order, stats };
  }

  const key = isPensionSortKey(rawKey) ? rawKey : null;
  const stats = pensionSortKeyToStats(key);
  return { key, order, stats };
}

export function pensionOrderEqual(
  a: readonly { uid: string }[],
  b: readonly { uid: string }[],
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i]?.uid !== b[i]?.uid) return false;
  }
  return true;
}
