/**
 * @file src/lib/vitaminsStats.ts
 * Vitamin consumption tallies and passive-gain multipliers.
 */

export interface VitaminsConsumedMap {
    hp?: number;
    attack?: number;
    spattack?: number;
    defense?: number;
    spdefense?: number;
    speed?: number;
    all?: number;
    moomooMilk?: number;
}

export interface ActiveVitaminsMap {
    hp?: number;
    attack?: number;
    spattack?: number;
    defense?: number;
    spdefense?: number;
    speed?: number;
    all?: number;
}

export const VITAMIN_STAT_KEYS = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'] as const;
export type VitaminStatKey = (typeof VITAMIN_STAT_KEYS)[number];

export type VitaminBonusMultipliers = Record<VitaminStatKey, number>;

export function sumVitaminsConsumed(consumed: VitaminsConsumedMap | null | undefined): number {
    if (!consumed || typeof consumed !== 'object') return 0;
    const keys = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed', 'all', 'moomooMilk'] as const;
    let total = 0;
    for (const key of keys) {
        total += Math.max(0, Number(consumed[key]) || 0);
    }
    return total;
}

export function getVitaminPortionForStat(
    vit: ActiveVitaminsMap | null | undefined,
    stat: VitaminStatKey,
): number {
    const v = vit ?? {};
    return (Number(v[stat]) || 0) + (Number(v.all) || 0);
}

/** Passive gain mult per stat: 1 + (specific + all) × (1 + vitaminEfficiency). */
export function buildVitaminBonusMultipliers(
    vit: ActiveVitaminsMap | null | undefined,
    vitaminEfficiency = 0,
): VitaminBonusMultipliers {
    const effMult = 1 + Math.max(0, Number(vitaminEfficiency) || 0);
    const result = {} as VitaminBonusMultipliers;
    for (const key of VITAMIN_STAT_KEYS) {
        result[key] = 1 + getVitaminPortionForStat(vit, key) * effMult;
    }
    return result;
}

/** Main vitamin efficiency + optional farm-milk bonus (separate cap in farm state). */
export function getTotalVitaminEfficiency(
    vitaminEfficiency: number | undefined,
    farmMilkEfficiency: number | undefined,
): number {
    return Math.max(0, Number(vitaminEfficiency) || 0) + Math.max(0, Number(farmMilkEfficiency) || 0);
}
