/** Edge autoscroll for creature drag — `.team-area` on desktop, window on mobile. */

import { isMobileViewport } from '../ui/breakpoints.ts';

export const EDGE_ZONE_PX = 90;
const MAX_SCROLL_SPEED = 12;

export type DragScrollRoot =
    | { kind: 'element'; el: HTMLElement }
    | { kind: 'window' };

let active = false;
let lastClientY = 0;
let rafId: number | null = null;
let docDragOverHandler: ((e: DragEvent) => void) | null = null;

export function isVerticallyScrollable(el: HTMLElement): boolean {
    return el.scrollHeight > el.clientHeight + 1;
}

/** @internal Exported for unit tests. */
export function resolveScrollRoot(): DragScrollRoot | null {
    if (typeof document === 'undefined') return null;

    const activeTeam = document.querySelector('.team-area.mobile-active');
    if (activeTeam instanceof HTMLElement && isVerticallyScrollable(activeTeam)) {
        return { kind: 'element', el: activeTeam };
    }

    const teamArea = document.querySelector('.team-area');
    if (teamArea instanceof HTMLElement && isVerticallyScrollable(teamArea)) {
        return { kind: 'element', el: teamArea };
    }

    if (isMobileViewport()) {
        const scrollingEl = document.scrollingElement;
        if (scrollingEl instanceof HTMLElement && isVerticallyScrollable(scrollingEl)) {
            return { kind: 'element', el: scrollingEl };
        }
        return { kind: 'window' };
    }

    if (teamArea instanceof HTMLElement) {
        return { kind: 'element', el: teamArea };
    }

    return { kind: 'window' };
}

function getViewportHeight(): number {
    if (typeof window === 'undefined') return 0;
    return window.visualViewport?.height ?? window.innerHeight;
}

function scrollElement(el: HTMLElement, delta: number): void {
    const maxScroll = Math.max(0, el.scrollHeight - el.clientHeight);
    el.scrollTop = Math.max(0, Math.min(maxScroll, el.scrollTop + delta));
}

function scrollWindow(delta: number): void {
    if (typeof window === 'undefined') return;
    const maxScroll = Math.max(
        0,
        document.documentElement.scrollHeight - getViewportHeight(),
    );
    const next = Math.max(0, Math.min(maxScroll, window.scrollY + delta));
    window.scrollTo(0, next);
}

/** @internal Exported for unit tests. */
export function applyDragAutoscrollStep(clientY: number): void {
    const root = resolveScrollRoot();
    if (!root) return;

    if (root.kind === 'element') {
        const el = root.el;
        const rect = el.getBoundingClientRect();
        const y = clientY - rect.top;
        const maxScroll = el.scrollHeight - el.clientHeight;
        if (y < EDGE_ZONE_PX && el.scrollTop > 0) {
            const factor = 1 - Math.max(0, y) / EDGE_ZONE_PX;
            scrollElement(el, -MAX_SCROLL_SPEED * factor);
        } else if (y > rect.height - EDGE_ZONE_PX && el.scrollTop < maxScroll) {
            const distFromBottom = rect.height - y;
            const factor = 1 - Math.max(0, distFromBottom) / EDGE_ZONE_PX;
            scrollElement(el, MAX_SCROLL_SPEED * factor);
        }
        return;
    }

    if (root.kind === 'window') {
        if (typeof window === 'undefined') return;
        const viewportHeight = getViewportHeight();
        const maxScroll = Math.max(
            0,
            document.documentElement.scrollHeight - viewportHeight,
        );
        if (clientY < EDGE_ZONE_PX && window.scrollY > 0) {
            const factor = 1 - Math.max(0, clientY) / EDGE_ZONE_PX;
            scrollWindow(-MAX_SCROLL_SPEED * factor);
        } else if (clientY > viewportHeight - EDGE_ZONE_PX && window.scrollY < maxScroll) {
            const distFromBottom = viewportHeight - clientY;
            const factor = 1 - Math.max(0, distFromBottom) / EDGE_ZONE_PX;
            scrollWindow(MAX_SCROLL_SPEED * factor);
        }
    }
}

function tick(): void {
    if (!active) return;
    applyDragAutoscrollStep(lastClientY);
    rafId = requestAnimationFrame(tick);
}

function onDocumentDragOver(e: DragEvent): void {
    updateDragAutoscroll(e.clientY);
}

export function startDragAutoscroll(): void {
    if (active) return;
    active = true;
    rafId = requestAnimationFrame(tick);
    if (typeof document !== 'undefined' && !docDragOverHandler) {
        docDragOverHandler = onDocumentDragOver;
        document.addEventListener('dragover', docDragOverHandler);
    }
}

export function updateDragAutoscroll(clientY: number): void {
    lastClientY = clientY;
    if (!active) startDragAutoscroll();
}

export function stopDragAutoscroll(): void {
    active = false;
    if (rafId !== null) {
        cancelAnimationFrame(rafId);
        rafId = null;
    }
    if (typeof document !== 'undefined' && docDragOverHandler) {
        document.removeEventListener('dragover', docDragOverHandler);
        docDragOverHandler = null;
    }
}

/** @internal Vitest — reset loop state between tests. */
export function resetDragAutoscrollForTests(): void {
    stopDragAutoscroll();
    lastClientY = 0;
}
