import { cueCooldownMs } from './audioCues.ts';

export const AUDIO_PREFS_KEY = 'poketime:audio';

export interface AudioPrefs {
    sfx: number;
    muted: boolean;
    /** Cue ids explicitly turned off. A missing id stays enabled. */
    cues: Record<string, false>;
}

export const DEFAULT_AUDIO_PREFS: AudioPrefs = {
    sfx: 0.5,
    muted: false,
    cues: {},
};

export interface AudioStorage {
    getItem(key: string): string | null;
    setItem(key: string, value: string): void;
}

export function clampVolume(value: unknown, fallback: number): number {
    const n = typeof value === 'number' ? value : Number(value);
    if (!Number.isFinite(n)) return fallback;
    if (n < 0) return 0;
    if (n > 1) return 1;
    return n;
}

export function normalizeCueToggles(raw: unknown): Record<string, false> {
    if (!raw || typeof raw !== 'object') return {};
    const cues: Record<string, false> = {};
    for (const [id, value] of Object.entries(raw as Record<string, unknown>)) {
        if (value === false && cueCooldownMs(id) != null) cues[id] = false;
    }
    return cues;
}

export function normalizeAudioPrefs(raw: unknown): AudioPrefs {
    if (!raw || typeof raw !== 'object') return { ...DEFAULT_AUDIO_PREFS, cues: {} };
    const record = raw as Record<string, unknown>;
    return {
        sfx: clampVolume(record.sfx, DEFAULT_AUDIO_PREFS.sfx),
        muted: record.muted === true,
        cues: normalizeCueToggles(record.cues),
    };
}

export function readAudioPrefs(storage: AudioStorage | null): AudioPrefs {
    if (!storage) return { ...DEFAULT_AUDIO_PREFS, cues: {} };
    try {
        const raw = storage.getItem(AUDIO_PREFS_KEY);
        if (!raw) return { ...DEFAULT_AUDIO_PREFS, cues: {} };
        return normalizeAudioPrefs(JSON.parse(raw));
    } catch {
        return { ...DEFAULT_AUDIO_PREFS, cues: {} };
    }
}

export function writeAudioPrefs(storage: AudioStorage | null, prefs: AudioPrefs): void {
    if (!storage) return;
    try {
        storage.setItem(AUDIO_PREFS_KEY, JSON.stringify(normalizeAudioPrefs(prefs)));
    } catch {
        /* private mode / quota */
    }
}
