/**
 * @file contributionTooltip.ts
 * Account-wide contribution gauge scale + bar HTML for team/daycare popovers.
 */

import { collectOwnedCreatures } from './regionalResonance.ts';
import { pickTooltipBarPercent } from './ultimateSlotPreview.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';

export type ContributionStatBlock = {
  hp: number;
  attack: number;
  spattack: number;
  defense: number;
  spdefense: number;
  speed: number;
};

export type ContributionTooltipScale = {
  maxima: ContributionStatBlock;
  totalMax: number;
};

const EMPTY_STATS: ContributionStatBlock = {
  hp: 0,
  attack: 0,
  spattack: 0,
  defense: 0,
  spdefense: 0,
  speed: 0,
};

const STAT_KEYS: ReadonlyArray<keyof ContributionStatBlock> = [
  'hp',
  'attack',
  'spattack',
  'defense',
  'spdefense',
  'speed',
];

function floorContribution(value: number, rate: number): number {
  const r = Number(rate);
  if (!Number.isFinite(r) || r <= 0) return 0;
  return Math.floor(Math.max(0, value) * r);
}

/** Per-stat contribution at the given transfer rate. */
export function computeCreatureContribution(
  creature: Pick<CreatureData, 'maxHp' | 'attack' | 'spattack' | 'defense' | 'spdefense' | 'speed'>,
  rate: number,
): ContributionStatBlock {
  return {
    hp: floorContribution(creature.maxHp ?? 0, rate),
    attack: floorContribution(creature.attack ?? 0, rate),
    spattack: floorContribution(creature.spattack ?? 0, rate),
    defense: floorContribution(creature.defense ?? 0, rate),
    spdefense: floorContribution(creature.spdefense ?? 0, rate),
    speed: floorContribution(creature.speed ?? 0, rate),
  };
}

/** Weighted total matching buildContributionPopoverContent (HP counts half). */
export function sumContributionTotal(block: ContributionStatBlock): number {
  return Math.floor(
    block.hp / 2 + block.attack + block.spattack + block.defense + block.spdefense + block.speed,
  );
}

/** Account-wide maxima for contribution gauge bars at the given rate. */
export function computeAccountContributionTooltipScale(
  game: GameRuntime | null | undefined,
  rate: number,
): ContributionTooltipScale {
  if (!game) return { maxima: { ...EMPTY_STATS }, totalMax: 0 };

  const maxima = { ...EMPTY_STATS };
  let totalMax = 0;
  const creatures = collectOwnedCreatures(game);

  for (let i = 0; i < creatures.length; i++) {
    const creature = creatures[i];
    if (!creature) continue;
    const bonus = computeCreatureContribution(creature, rate);
    for (let k = 0; k < STAT_KEYS.length; k++) {
      const key = STAT_KEYS[k];
      if (key === undefined) continue;
      maxima[key] = Math.max(maxima[key], bonus[key]);
    }
    totalMax = Math.max(totalMax, sumContributionTotal(bonus));
  }

  return { maxima, totalMax };
}

/** Single gauge bar HTML (reuses ultimate-slot pick tooltip bar styles). */
export function formatContributionBarHtml(value: number, max: number): string {
  const pct = pickTooltipBarPercent(value, max);
  return (
    `<span class="ultimate-slot-pick-tooltip-bar contribution-popover-bar">` +
    `<span class="ultimate-slot-pick-tooltip-bar-fill" style="width: ${pct}%;"></span>` +
    `</span>`
  );
}
