export interface StatInfo {
    short: string;
    long: string;
    color: string;
}

/**
 * Libellés et couleurs normalisés de stats :
 * Une seule source de vérité pour header, fiches, chips et modales.
 */
export const STATS: Record<string, StatInfo> = {
    hp:    { short: 'HP',     long: 'PV',        color: 'var(--s-hp)' },
    atk:   { short: 'ATK',    long: 'Atq.',      color: 'var(--s-atk)' },
    atksp: { short: 'ATK SP', long: 'Atq. Spé.', color: 'var(--s-atksp)' },
    def:   { short: 'DEF',    long: 'Déf.',      color: 'var(--s-def)' },
    defsp: { short: 'DEF SP', long: 'Déf. Spé.', color: 'var(--s-defsp)' },
    spd:   { short: 'SPD',    long: 'Vit.',      color: 'var(--s-spd)' },
    heal:  { short: 'SOINS',  long: 'Soins',     color: 'var(--s-heal, #cfd6e4)' },
};

import {
    formatPercent,
    formatPercentInText,
    type FormatPercentOptions,
} from '../../formatters.ts';
import { publishModalOpened } from '../bus/publishHooks.js';

export { formatPercent, formatPercentInText };
export type { FormatPercentOptions };

export const pct = (n: number | string, options?: FormatPercentOptions): string =>
    formatPercent(n, { signed: true, ...options });

const modalStack: HTMLElement[] = [];

export function getTopmostStackedModal(): HTMLElement | null {
    while (modalStack.length > 0) {
        const top = modalStack[modalStack.length - 1];
        if (top && document.body.contains(top)) {
            return top;
        }
        modalStack.pop();
    }
    return null;
}

/**
 * Gestionnaire standard de fermeture modale :
 * - Bouton ✕ (.x ou .stats-close)
 * - Clic sur le fond (.modal-backdrop / root)
 * - Touche Échap (gestion LIFO : seule la modale du dessus se ferme)
 */
export function openModal(root: HTMLElement): () => void {
    modalStack.push(root);
    const ac = new AbortController();
    const o = { signal: ac.signal };
    let isClosed = false;

    const close = () => {
        if (isClosed) return;
        isClosed = true;
        const idx = modalStack.indexOf(root);
        if (idx !== -1) modalStack.splice(idx, 1);
        ac.abort();
        root.remove();
    };

    root.addEventListener('mousedown', (e: MouseEvent) => {
        if (e.target === root) close();
    }, o);

    document.addEventListener('keydown', (e: KeyboardEvent) => {
        if (e.key !== 'Escape' || e.defaultPrevented || e.isComposing) return;
        if (root.hasAttribute('inert') || root.getAttribute('aria-hidden') === 'true') return;
        if (getTopmostStackedModal() !== root) return;

        e.preventDefault();
        e.stopPropagation();
        e.stopImmediatePropagation();
        close();
    }, { ...o, capture: true });

    const closeBtn = root.querySelector('.x, .stats-close');
    if (closeBtn) {
        closeBtn.addEventListener('click', close, o);
    }
    return close;
}

/**
 * Associe une sous-modale à la modale parente (par défaut #creatureModal) :
 * - Active inert et aria-hidden sur la parente
 * - À la destruction / fermeture de la sous-modale, retire inert et aria-hidden
 */
export function registerSubModal(subModalEl: HTMLElement, parentModalId = 'creatureModal'): () => void {
    if (parentModalId === 'creatureModal') publishModalOpened('creatureModal');
    const parent = document.getElementById(parentModalId);
    if (parent) {
        parent.setAttribute('inert', '');
        parent.setAttribute('aria-hidden', 'true');
    }
    let cleaned = false;
    const cleanup = () => {
        if (cleaned) return;
        cleaned = true;
        if (parent) {
            parent.removeAttribute('inert');
            parent.removeAttribute('aria-hidden');
        }
    };
    if (typeof MutationObserver !== 'undefined') {
        const observer = new MutationObserver(() => {
            if (typeof document === 'undefined' || !document.body || !document.body.contains(subModalEl)) {
                observer.disconnect();
                cleanup();
            }
        });
        observer.observe(document.body, { childList: true });
    }
    return cleanup;
}

export interface SubModalHeaderOptions {
    title: string;
    pokemonName: string;
    pokemonSpriteUrl?: string;
    closeAction: string;
    closeAriaLabel?: string;
}

/**
 * Génère le HTML standard de l'en-tête de sous-modale :
 * Titre court pixel, chip Pokémon (sprite 28px + nom), bouton ✕
 */
export function buildSubModalHeaderHtml(options: SubModalHeaderOptions): string {
    const esc = (s: string) => String(s || '').replace(/"/g, '&quot;');
    const spriteHtml = options.pokemonSpriteUrl
        ? `<img src="${esc(options.pokemonSpriteUrl)}" alt="${esc(options.pokemonName)}" class="submodal-pokemon-sprite" onerror="this.style.display='none'">`
        : '';
    const pokemonChip = options.pokemonName
        ? `<div class="submodal-pokemon-chip">
            ${spriteHtml}
            <span class="submodal-pokemon-name">${esc(options.pokemonName)}</span>
           </div>`
        : '';
    return `
        <div class="submodal-header">
            <div class="submodal-header-left">
                <h2 class="submodal-pixel-title">${esc(options.title)}</h2>
                ${pokemonChip}
            </div>
            <button type="button" class="stats-close submodal-close" data-action="${esc(options.closeAction)}" aria-label="${esc(options.closeAriaLabel || 'Fermer')}">&#10005;</button>
        </div>
    `;
}

/**
 * Déclenche une animation de surbrillance lumineuse ("flash") sur un élément modifié
 * de la fiche Pokémon ouverte, sans la rouvrir.
 */
export function triggerCreatureModalFlash(targetSelector: string): void {
    if (typeof requestAnimationFrame === 'undefined' || typeof document === 'undefined') return;
    requestAnimationFrame(() => {
        const modal = document.getElementById('creatureModal');
        if (!modal || !modal.classList.contains('show')) return;
        const target = modal.querySelector<HTMLElement>(targetSelector);
        if (!target) return;
        target.classList.remove('submodal-flash-highlight');
        // Force reflow pour relancer l'animation
        void target.offsetWidth;
        target.classList.add('submodal-flash-highlight');
        setTimeout(() => {
            target.classList.remove('submodal-flash-highlight');
        }, 1300);
    });
}


