/**
 * @file ultimateSlotPreview.ts
 * Preview transfer bonus for ultimate-slot mentor candidates (tooltips).
 */

import type { CreatureSnapshot } from '../bus/snapshots.js';
import { collectOwnedCreatures } from './regionalResonance.ts';
import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';

export type UltimateSlotStatBlock = {
  hp: number;
  attack: number;
  spattack: number;
  defense: number;
  spdefense: number;
  speed: number;
};

export type UltimateSlotTransferStats = Pick<
  CreatureSnapshot,
  'maxHp' | 'attack' | 'spattack' | 'defense' | 'spdefense' | 'speed'
>;

const EMPTY_STATS: UltimateSlotStatBlock = {
  hp: 0,
  attack: 0,
  spattack: 0,
  defense: 0,
  spdefense: 0,
  speed: 0,
};

const STAT_KEYS: ReadonlyArray<keyof UltimateSlotStatBlock> = [
  'hp',
  'attack',
  'spattack',
  'defense',
  'spdefense',
  'speed',
];

function floorStat(value: number, rate: number): number {
  return Math.floor(Math.max(0, value) * rate);
}

/** Per-team-member flat bonus if this creature were the ultimate mentor. */
export function computeUltimateSlotTransferBonus(
  stats: UltimateSlotTransferStats,
  transferRate: number,
): UltimateSlotStatBlock {
  const rate = Number(transferRate);
  if (!Number.isFinite(rate) || rate <= 0) return { ...EMPTY_STATS };

  return {
    hp: floorStat(stats.maxHp ?? 0, rate),
    attack: floorStat(stats.attack ?? 0, rate),
    spattack: floorStat(stats.spattack ?? 0, rate),
    defense: floorStat(stats.defense ?? 0, rate),
    spdefense: floorStat(stats.spdefense ?? 0, rate),
    speed: floorStat(stats.speed ?? 0, rate),
  };
}

function creatureToTransferStats(creature: UltimateSlotTransferStats | CreatureData): UltimateSlotTransferStats {
  return {
    maxHp: creature.maxHp ?? 0,
    attack: creature.attack ?? 0,
    spattack: creature.spattack ?? 0,
    defense: creature.defense ?? 0,
    spdefense: creature.spdefense ?? 0,
    speed: creature.speed ?? 0,
  };
}

function ensureCreatureStats(creature: CreatureData): void {
  if (creature && typeof creature.recalculateStats === 'function') {
    creature.recalculateStats();
  }
}

function collectAccountTransferStatSources(game: GameRuntime): UltimateSlotTransferStats[] {
  const creatures = collectOwnedCreatures(game);
  const mentor = game.ultimateSlot;
  if (mentor && !mentor.isEnemy) {
    const mentorUid = mentor.uid != null ? String(mentor.uid) : '';
    const alreadyListed = mentorUid
      ? creatures.some((c) => c?.uid != null && String(c.uid) === mentorUid)
      : false;
    if (!alreadyListed) creatures.push(mentor);
  }
  return creatures.map((c) => {
    ensureCreatureStats(c);
    return creatureToTransferStats(c);
  });
}

/** Pickable ultimate-slot candidates: storage only (matches picker modal). */
function collectStorageTransferStatSources(game: GameRuntime): UltimateSlotTransferStats[] {
  const storage = game.storage;
  if (!Array.isArray(storage)) return [];
  const out: UltimateSlotTransferStats[] = [];
  for (let i = 0; i < storage.length; i++) {
    const c = storage[i];
    if (!c || c.isEnemy) continue;
    ensureCreatureStats(c);
    out.push(creatureToTransferStats(c));
  }
  return out;
}

/** Sum of all transfer bonus stats in a block. */
export function sumUltimateSlotTransferBonus(block: UltimateSlotStatBlock): number {
  let total = 0;
  for (let k = 0; k < STAT_KEYS.length; k++) {
    const key = STAT_KEYS[k];
    if (key === undefined) continue;
    total += block[key];
  }
  return total;
}

/** Max per-stat transfer bonus across a list of creatures at the given rate. */
export function computeUltimateSlotTransferBonusMaxima(
  creatures: UltimateSlotTransferStats[],
  transferRate: number,
): UltimateSlotStatBlock {
  const maxima = { ...EMPTY_STATS };
  for (let i = 0; i < creatures.length; i++) {
    const creature = creatures[i];
    if (!creature) continue;
    const bonus = computeUltimateSlotTransferBonus(creature, transferRate);
    for (let k = 0; k < STAT_KEYS.length; k++) {
      const key = STAT_KEYS[k];
      if (key === undefined) continue;
      maxima[key] = Math.max(maxima[key], bonus[key]);
    }
  }
  return maxima;
}

/** Max total transfer bonus (sum of all stats) for any single creature in the list. */
export function computeUltimateSlotTransferBonusTotalMaximum(
  creatures: UltimateSlotTransferStats[],
  transferRate: number,
): number {
  let maxTotal = 0;
  for (let i = 0; i < creatures.length; i++) {
    const creature = creatures[i];
    if (!creature) continue;
    const bonus = computeUltimateSlotTransferBonus(creature, transferRate);
    maxTotal = Math.max(maxTotal, sumUltimateSlotTransferBonus(bonus));
  }
  return maxTotal;
}

export type UltimateSlotPickTooltipScale = {
  maxima: UltimateSlotStatBlock;
  totalMax: number;
};

/** Per-stat and total maxima for ultimate-slot picker tooltips (account-wide). */
export function computeAccountUltimateSlotPickTooltipScale(
  game: GameRuntime | null | undefined,
  transferRate: number,
): UltimateSlotPickTooltipScale {
  if (!game) return { maxima: { ...EMPTY_STATS }, totalMax: 0 };
  const sources = collectAccountTransferStatSources(game);
  return {
    maxima: computeUltimateSlotTransferBonusMaxima(sources, transferRate),
    totalMax: computeUltimateSlotTransferBonusTotalMaximum(sources, transferRate),
  };
}

/** Per-stat and total maxima among storage Pokémon (picker tooltip scale). */
export function computeStorageUltimateSlotPickTooltipScale(
  game: GameRuntime | null | undefined,
  transferRate: number,
): UltimateSlotPickTooltipScale {
  if (!game) return { maxima: { ...EMPTY_STATS }, totalMax: 0 };
  const sources = collectStorageTransferStatSources(game);
  return {
    maxima: computeUltimateSlotTransferBonusMaxima(sources, transferRate),
    totalMax: computeUltimateSlotTransferBonusTotalMaximum(sources, transferRate),
  };
}

/** Storage-only max total transfer bonus for any single storage creature. */
export function computeStorageUltimateSlotBonusTotalMaximum(
  game: GameRuntime | null | undefined,
  transferRate: number,
): number {
  return computeStorageUltimateSlotPickTooltipScale(game, transferRate).totalMax;
}

/** Account-wide max transfer bonus per stat (team, storage, pension, expeditions, mentor). */
export function computeAccountUltimateSlotBonusMaxima(
  game: GameRuntime | null | undefined,
  transferRate: number,
): UltimateSlotStatBlock {
  return computeAccountUltimateSlotPickTooltipScale(game, transferRate).maxima;
}

/** Account-wide max total transfer bonus for any single owned creature. */
export function computeAccountUltimateSlotBonusTotalMaximum(
  game: GameRuntime | null | undefined,
  transferRate: number,
): number {
  return computeAccountUltimateSlotPickTooltipScale(game, transferRate).totalMax;
}

const PICK_TOOLTIP_ROWS: ReadonlyArray<{ key: keyof UltimateSlotStatBlock; label: string }> = [
  { key: 'hp', label: 'HP' },
  { key: 'attack', label: 'ATK' },
  { key: 'spattack', label: 'SP.ATK' },
  { key: 'defense', label: 'DEF' },
  { key: 'spdefense', label: 'SP.DEF' },
  { key: 'speed', label: 'SPD' },
];

export function pickTooltipBarPercent(value: number, max: number): number {
  if (!Number.isFinite(max) || max <= 0) return 0;
  return Math.max(0, Math.min(100, Math.round((value / max) * 100)));
}

function formatUltimateSlotPickTooltipRow(
  label: string,
  value: number,
  barMax: number,
  options?: { total?: boolean },
): string {
  const pct = pickTooltipBarPercent(value, barMax);
  const rowClass = options?.total
    ? 'ultimate-slot-pick-tooltip-row ultimate-slot-pick-tooltip-row--total'
    : 'ultimate-slot-pick-tooltip-row';
  return (
    `<div class="${rowClass}">` +
    `<span class="ultimate-slot-pick-tooltip-label">${label}</span>` +
    `<span class="ultimate-slot-pick-tooltip-value">+${value}</span>` +
    `<span class="ultimate-slot-pick-tooltip-bar">` +
    `<span class="ultimate-slot-pick-tooltip-bar-fill" style="width: ${pct}%;"></span>` +
    `</span>` +
    `</div>`
  );
}

/** HTML body for #customTooltip (one stat per line, optional gauge vs account max). */
export function formatUltimateSlotPickTooltipBody(
  bonus: UltimateSlotStatBlock,
  maxima?: UltimateSlotStatBlock | null,
  totalMax?: number | null,
): string {
  const total = sumUltimateSlotTransferBonus(bonus);

  if (!maxima) {
    const lines = PICK_TOOLTIP_ROWS.map(({ key, label }) => `${label} +${bonus[key]}`);
    lines.push(`TOTAL +${total}`);
    return lines.join('<br>');
  }

  const rows = PICK_TOOLTIP_ROWS.map(({ key, label }) =>
    formatUltimateSlotPickTooltipRow(label, bonus[key], maxima[key]),
  );
  rows.push(formatUltimateSlotPickTooltipRow('TOTAL', total, totalMax ?? 0, { total: true }));
  return `<div class="ultimate-slot-pick-tooltip">${rows.join('')}</div>`;
}
