/**
 * @file src/lib/heldItemRelevance.ts
 * Évaluation contextuelle de la pertinence des objets tenus pour un Pokémon.
 */

import { getMoveDefinition, isDamagingMove } from '../../constants/movesDb.ts';
import { coerceStr } from './coerceStr.ts';

export interface HeldItemRelevanceResult {
    status: 'boost' | 'neutral' | 'dimmed';
    tag: string;
    tagType?: string;
    filterCategory: 'moves' | 'stats';
    boostedMoveNames: string[];
    priority: number; // 0: boost (recommandé), 1: neutral (stats/utilitaire), 2: dimmed (sans effet attaques)
}

export interface CreatureRelevanceContext {
    name?: string;
    type?: string;
    secondaryType?: string;
    currentMoves?: string[];
}

export interface HeldItemEffectLike {
    type_damage_bonus?: unknown;
    type?: unknown;
    physical_damage_mult?: unknown;
    special_damage_mult?: unknown;
    attack_mult?: unknown;
    spattack_mult?: unknown;
    speed_mult?: unknown;
    heal_percent?: unknown;
    crit_chance?: unknown;
    damage_mult?: unknown;
    xp_bonus?: unknown;
    spdefense_mult?: unknown;
    reflect_mult?: unknown;
    lifesteal?: unknown;
    super_effective_bonus?: unknown;
    first_strike_chance?: unknown;
    focus_sash?: unknown;
}

export interface HeldItemDefLike {
    name?: unknown;
    description?: unknown;
    effect?: HeldItemEffectLike | Record<string, unknown> | null;
    restrict_type?: unknown;
}

/**
 * Évalue si un objet tenu est utile, recommandé ou sans effet sur les attaques actuelles du Pokémon.
 */
export function evaluateHeldItemRelevance(
    itemKey: string,
    itemDef: HeldItemDefLike | null | undefined,
    creature: CreatureRelevanceContext | null | undefined,
    isFrench = true,
    localizeMoveName?: (rawName: string) => string,
): HeldItemRelevanceResult {
    const effect = (itemDef && itemDef.effect) ? itemDef.effect : {};
    const moves = (creature && Array.isArray(creature.currentMoves) && creature.currentMoves.length > 0)
        ? creature.currentMoves
        : ['Charge'];

    const getMoveLabel = (m: string) => {
        if (typeof localizeMoveName === 'function') {
            const loc = localizeMoveName(m);
            if (loc) return loc;
        }
        const def = getMoveDefinition(m);
        return coerceStr(def?.name, m);
    };

    // 1. Objets boostant un type précis (Charcoal, Magnet, Mystic Water...)
    if (effect.type_damage_bonus && effect.type) {
        const targetType = coerceStr(effect.type, '').toLowerCase();
        const boosted: string[] = [];

        for (const m of moves) {
            const def = getMoveDefinition(m);
            if (def && String(def.type).toLowerCase() === targetType && isDamagingMove(m)) {
                boosted.push(getMoveLabel(m));
            }
        }

        if (boosted.length > 0) {
            const tag = boosted.length === 1
                ? (isFrench ? `Booste ${boosted[0]}` : `Boosts ${boosted[0]}`)
                : (isFrench ? `Booste ${boosted.length} capacités` : `Boosts ${boosted.length} moves`);
            return {
                status: 'boost',
                tag,
                tagType: targetType,
                filterCategory: 'moves',
                boostedMoveNames: boosted,
                priority: 0,
            };
        }

        return {
            status: 'dimmed',
            tag: isFrench ? 'Sans effet sur les attaques actuelles' : 'No effect on current moves',
            tagType: targetType,
            filterCategory: 'moves',
            boostedMoveNames: [],
            priority: 2,
        };
    }

    // 2. Objets boostant les attaques physiques (Muscle Band...)
    if (effect.physical_damage_mult) {
        const boosted: string[] = [];
        for (const m of moves) {
            const def = getMoveDefinition(m);
            if (def && def.category === 'physical' && isDamagingMove(m)) {
                boosted.push(getMoveLabel(m));
            }
        }

        if (boosted.length > 0) {
            const count = boosted.length;
            const tag = isFrench
                ? `Booste ${count} attaque${count > 1 ? 's' : ''} physique${count > 1 ? 's' : ''}`
                : `Boosts ${count} physical move${count > 1 ? 's' : ''}`;
            return {
                status: 'boost',
                tag,
                filterCategory: 'moves',
                boostedMoveNames: boosted,
                priority: 0,
            };
        }

        return {
            status: 'dimmed',
            tag: isFrench ? 'Sans effet sur les attaques actuelles' : 'No effect on current moves',
            filterCategory: 'moves',
            boostedMoveNames: [],
            priority: 2,
        };
    }

    // 3. Objets boostant les attaques spéciales (Wise Glasses...)
    if (effect.special_damage_mult) {
        const boosted: string[] = [];
        for (const m of moves) {
            const def = getMoveDefinition(m);
            if (def && def.category === 'special' && isDamagingMove(m)) {
                boosted.push(getMoveLabel(m));
            }
        }

        if (boosted.length > 0) {
            const count = boosted.length;
            const tag = isFrench
                ? `Booste ${count} attaque${count > 1 ? 's' : ''} spéciale${count > 1 ? 's' : ''}`
                : `Boosts ${count} special move${count > 1 ? 's' : ''}`;
            return {
                status: 'boost',
                tag,
                filterCategory: 'moves',
                boostedMoveNames: boosted,
                priority: 0,
            };
        }

        return {
            status: 'dimmed',
            tag: isFrench ? 'Sans effet sur les attaques actuelles' : 'No effect on current moves',
            filterCategory: 'moves',
            boostedMoveNames: [],
            priority: 2,
        };
    }

    // 4. Bandeau Choix (+30% Attaque physique)
    if (effect.attack_mult) {
        const hasPhys = moves.some((m) => {
            const def = getMoveDefinition(m);
            return def && def.category === 'physical' && isDamagingMove(m);
        });
        if (hasPhys) {
            return {
                status: 'boost',
                tag: isFrench ? '+30 % Attaque' : '+30% Attack',
                filterCategory: 'moves',
                boostedMoveNames: moves,
                priority: 0,
            };
        }

        return {
            status: 'dimmed',
            tag: isFrench ? 'Sans effet sur les attaques actuelles' : 'No effect on current moves',
            filterCategory: 'moves',
            boostedMoveNames: [],
            priority: 2,
        };
    }

    // 5. Lunettes Choix (+30% Attaque Spéciale)
    if (effect.spattack_mult) {
        const hasSpec = moves.some((m) => {
            const def = getMoveDefinition(m);
            return def && def.category === 'special' && isDamagingMove(m);
        });
        if (hasSpec) {
            return {
                status: 'boost',
                tag: isFrench ? '+30 % Atq. Spé.' : '+30% Sp. Atk',
                filterCategory: 'moves',
                boostedMoveNames: moves,
                priority: 0,
            };
        }

        return {
            status: 'dimmed',
            tag: isFrench ? 'Sans effet sur les attaques actuelles' : 'No effect on current moves',
            filterCategory: 'moves',
            boostedMoveNames: [],
            priority: 2,
        };
    }

    // 6. Ceinture Force (Expert Belt: +20% super efficace)
    if (effect.super_effective_bonus) {
        return {
            status: 'boost',
            tag: isFrench ? '+20 % Super efficace' : '+20% Super effective',
            filterCategory: 'moves',
            boostedMoveNames: moves,
            priority: 0,
        };
    }

    // 7. Objets de statistiques et utilitaires universels
    if (effect.speed_mult) {
        return {
            status: 'neutral',
            tag: isFrench ? '+25 % Vitesse' : '+25% Speed',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.heal_percent) {
        return {
            status: 'neutral',
            tag: isFrench ? 'Régénération PV' : 'HP Regen',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.crit_chance) {
        return {
            status: 'neutral',
            tag: isFrench ? '+10 % Critique' : '+10% Crit',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.damage_mult) {
        return {
            status: 'neutral',
            tag: isFrench ? '+30 % Dégâts universels' : '+30% All damage',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.xp_bonus) {
        return {
            status: 'neutral',
            tag: isFrench ? '+100 % EXP' : '+100% XP',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.spdefense_mult) {
        return {
            status: 'neutral',
            tag: isFrench ? '+40 % Déf. Spé.' : '+40% Sp. Def',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.reflect_mult) {
        return {
            status: 'neutral',
            tag: isFrench ? 'Renvoi dégâts' : 'Damage reflect',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.lifesteal) {
        return {
            status: 'neutral',
            tag: isFrench ? 'Vol de vie' : 'Lifesteal',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.focus_sash) {
        return {
            status: 'neutral',
            tag: isFrench ? 'Survie 1 coup fatal' : 'Survive fatal hit',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }
    if (effect.first_strike_chance) {
        return {
            status: 'neutral',
            tag: isFrench ? 'Frappe prioritaire' : 'First strike',
            filterCategory: 'stats',
            boostedMoveNames: [],
            priority: 1,
        };
    }

    return {
        status: 'neutral',
        tag: isFrench ? 'Stat / Utilitaire' : 'Stat / Utility',
        filterCategory: 'stats',
        boostedMoveNames: [],
        priority: 1,
    };
}
