const noiseBuffers = new WeakMap<AudioContext, AudioBuffer>();

function sharedNoise(ctx: AudioContext): AudioBuffer | null {
    const cached = noiseBuffers.get(ctx);
    if (cached) return cached;
    if (typeof ctx.createBuffer !== 'function' || !(ctx.sampleRate > 0)) return null;
    const length = Math.max(1, Math.floor(ctx.sampleRate * 0.08));
    const buffer = ctx.createBuffer(1, length, ctx.sampleRate);
    const data = buffer.getChannelData(0);
    for (let i = 0; i < data.length; i++) data[i] = Math.random() * 2 - 1;
    noiseBuffers.set(ctx, buffer);
    return buffer;
}

export function playTone(
    ctx: AudioContext,
    dest: AudioNode,
    freq: number,
    type: OscillatorType,
    duration: number,
    peak: number,
    when: number,
): void {
    if (!(freq > 0) || !(duration > 0) || !(peak > 0)) return;
    const osc = ctx.createOscillator();
    const gain = ctx.createGain();
    osc.type = type;
    osc.frequency.setValueAtTime(freq, when);
    const attackEnd = when + Math.min(0.012, duration * 0.3);
    const releaseAt = when + duration - Math.min(0.04, duration * 0.35);
    gain.gain.setValueAtTime(0.0001, when);
    gain.gain.exponentialRampToValueAtTime(peak, attackEnd);
    if (releaseAt > attackEnd + 0.005) gain.gain.setValueAtTime(peak, releaseAt);
    gain.gain.exponentialRampToValueAtTime(0.0001, when + duration);
    osc.connect(gain).connect(dest);
    osc.start(when);
    osc.stop(when + duration + 0.02);
}

export function playNoise(
    ctx: AudioContext,
    dest: AudioNode,
    duration: number,
    peak: number,
    when: number,
    highpass = 1400,
): void {
    if (!(duration > 0) || !(peak > 0)) return;
    const buffer = sharedNoise(ctx);
    if (!buffer || typeof ctx.createBufferSource !== 'function') return;
    const src = ctx.createBufferSource();
    src.buffer = buffer;
    const filter = ctx.createBiquadFilter();
    filter.type = 'highpass';
    filter.frequency.setValueAtTime(highpass, when);
    const gain = ctx.createGain();
    gain.gain.setValueAtTime(peak, when);
    gain.gain.exponentialRampToValueAtTime(0.0001, when + duration);
    src.connect(filter).connect(gain).connect(dest);
    src.start(when);
    src.stop(when + duration + 0.02);
}
