/**
 * @file src/stores/storeUtils.ts
 * Shared comparison helpers for Svelte rune stores.
 */

import type { CreatureSnapshot, ResourceSnapshot, StorageCardSnapshot } from '../bus/snapshots.js';

export function creatureKey(c: CreatureSnapshot): string {
  return `${c.uid}|${c.name}|${c.level}|${c.prestige ?? 0}|${c.isShiny ? 1 : 0}`;
}

/** Identity / layout — reorder, species change (level/EXP/KO via volatile patch). */
export function creatureRosterIdentityEqual(a: CreatureSnapshot, b: CreatureSnapshot): boolean {
  return (
    a.uid === b.uid &&
    a.prestige === b.prestige &&
    a.isShiny === b.isShiny &&
    a.isShadow === b.isShadow &&
    a.rarity === b.rarity
  );
}

/** Volatile card fields updated in-place without replacing roster slots. */
export function creatureVolatileEqual(a: CreatureSnapshot, b: CreatureSnapshot): boolean {
  return (
    a.level === b.level &&
    a.exp === b.exp &&
    a.expToNext === b.expToNext &&
    a.shardCount === b.shardCount &&
    a.prestigeStoneCount === b.prestigeStoneCount &&
    a.prestigeReady === b.prestigeReady &&
    a.isAlive === b.isAlive &&
    a.displayName === b.displayName &&
    a.heldItem === b.heldItem &&
    a.heldBadgeHtml === b.heldBadgeHtml &&
    a.pokerusBadgeHtml === b.pokerusBadgeHtml &&
    a.spriteUrl === b.spriteUrl &&
    a.passiveTalent === b.passiveTalent &&
    a.effectivePrestige === b.effectivePrestige &&
    a.effectiveLevel === b.effectiveLevel &&
    a.resonanceActive === b.resonanceActive &&
    a.resonanceCapped === b.resonanceCapped &&
    a.resonanceCapSimLevel === b.resonanceCapSimLevel &&
    a.anchorCatchUpXpMult === b.anchorCatchUpXpMult &&
    a.isFavorite === b.isFavorite
  );
}

export function patchCreatureVolatileFields(
  target: CreatureSnapshot,
  source: CreatureSnapshot,
): CreatureSnapshot {
  if (creatureVolatileEqual(target, source)) return target;
  return {
    ...target,
    level: source.level,
    exp: source.exp,
    expToNext: source.expToNext,
    shardCount: source.shardCount,
    prestigeStoneCount: source.prestigeStoneCount,
    prestigeCost: source.prestigeCost,
    prestigeStoneCost: source.prestigeStoneCost,
    prestigeReady: source.prestigeReady,
    isAlive: source.isAlive,
    displayName: source.displayName,
    heldItem: source.heldItem,
    heldBadgeHtml: source.heldBadgeHtml,
    pokerusBadgeHtml: source.pokerusBadgeHtml,
    spriteUrl: source.spriteUrl,
    passiveTalent: source.passiveTalent,
    effectivePrestige: source.effectivePrestige,
    effectiveLevel: source.effectiveLevel,
    resonanceActive: source.resonanceActive,
    resonanceCapped: source.resonanceCapped,
    resonanceCapSimLevel: source.resonanceCapSimLevel,
    anchorCatchUpXpMult: source.anchorCatchUpXpMult,
    isFavorite: source.isFavorite,
  };
}

function creatureCardEqual(a: CreatureSnapshot, b: CreatureSnapshot): boolean {
  return creatureRosterIdentityEqual(a, b) && creatureVolatileEqual(a, b);
}

export function shallowEqualCreature(a: CreatureSnapshot | null, b: CreatureSnapshot | null): boolean {
  if (a === b) return true;
  if (!a || !b) return false;
  return (
    a.name === b.name &&
    a.level === b.level &&
    a.currentHp === b.currentHp &&
    a.maxHp === b.maxHp &&
    a.prestige === b.prestige &&
    a.isShiny === b.isShiny &&
    a.isShadow === b.isShadow &&
    a.rarity === b.rarity
  );
}

export function shallowEqualShards(
  a: Record<string, number>,
  b: Record<string, number>,
): boolean {
  const keysA = Object.keys(a);
  const keysB = Object.keys(b);
  if (keysA.length !== keysB.length) return false;
  for (const k of keysA) {
    if (a[k] !== b[k]) return false;
  }
  return true;
}

/** Ordered uid list — detects reorder even when per-card fields look unchanged. */
export function teamRosterUidOrder(roster: CreatureSnapshot[]): string {
  return roster.map((c) => c.uid).join('\n');
}

/** Passive talent keys per slot — for talent chip UI without full roster rescans. */
export function teamPassiveTalentsSignature(roster: CreatureSnapshot[]): string {
  const parts: string[] = [];
  for (let i = 0; i < roster.length; i++) {
    const c = roster[i];
    parts.push(c?.passiveTalent ?? '');
  }
  return parts.join(',');
}

/** Type composition for synergy button — changes only when team types change. */
export function teamSynergyTypesSignature(roster: CreatureSnapshot[]): string {
  const parts: string[] = [];
  for (let i = 0; i < roster.length; i++) {
    const c = roster[i];
    if (!c) continue;
    parts.push(`${c.type}|${c.secondaryType ?? ''}`);
  }
  return parts.join(',');
}

export function teamRosterIdentityEqual(
  a: CreatureSnapshot[],
  b: CreatureSnapshot[],
): boolean {
  if (a.length !== b.length) return false;
  if (teamRosterUidOrder(a) !== teamRosterUidOrder(b)) return false;
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    const bi = b[i];
    if (ai === undefined || bi === undefined) return false;
    if (!creatureRosterIdentityEqual(ai, bi)) return false;
  }
  return true;
}

/** Full roster equality (identity + volatile fields). */
export function teamRosterEqual(
  a: CreatureSnapshot[],
  b: CreatureSnapshot[],
): boolean {
  if (!teamRosterIdentityEqual(a, b)) return false;
  for (let i = 0; i < a.length; i++) {
    const ai = a[i];
    const bi = b[i];
    if (ai === undefined || bi === undefined) return false;
    if (!creatureVolatileEqual(ai, bi)) return false;
  }
  return true;
}

/** Ordered roster keys — detects sort/filter reorder even when length is unchanged. */
export function storageRosterSignature(roster: StorageCardSnapshot[]): string {
  return roster.map((c) => c.rosterKey).join('\n');
}

/** True when `next` is `prev` plus one entry at the end (capture / append). */
export function isStorageRosterAppendOnly(
  prev: StorageCardSnapshot[],
  next: StorageCardSnapshot[],
): boolean {
  if (next.length !== prev.length + 1) return false;
  for (let i = 0; i < prev.length; i++) {
    if (prev[i]?.rosterKey !== next[i]?.rosterKey) return false;
  }
  return true;
}

/** Same roster keys in order — reorder/filter changes return false. */
export function storageRosterIdentityEqual(
  a: StorageCardSnapshot[],
  b: StorageCardSnapshot[],
): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i]?.rosterKey !== b[i]?.rosterKey) return false;
  }
  return true;
}

function storageCardVolatileEqual(a: StorageCardSnapshot, b: StorageCardSnapshot): boolean {
  if (!creatureVolatileEqual(a, b)) return false;
  if (a.currentHp !== b.currentHp || a.maxHp !== b.maxHp) return false;
  if (a.cardOpacity !== b.cardOpacity) return false;
  if (a.draggable !== b.draggable) return false;
  if (a.isExpeditionEntry !== b.isExpeditionEntry) return false;
  if (a.expeditionName !== b.expeditionName) return false;
  if (a.expeditionStatus !== b.expeditionStatus) return false;
  if (a.storageIndex !== b.storageIndex) return false;
  if (a.source !== b.source) return false;
  return true;
}

/** Patch storage card fields in-place when rosterKey order is unchanged. */
export function patchStorageCardFields(
  target: StorageCardSnapshot,
  source: StorageCardSnapshot,
): StorageCardSnapshot {
  if (storageCardVolatileEqual(target, source)) return target;
  const patched = patchCreatureVolatileFields(target, source) as StorageCardSnapshot;
  return {
    ...patched,
    rosterKey: source.rosterKey,
    source: source.source,
    storageIndex: source.storageIndex,
    draggable: source.draggable,
    cardOpacity: source.cardOpacity,
    isExpeditionEntry: source.isExpeditionEntry,
    expeditionName: source.expeditionName,
    expeditionStatus: source.expeditionStatus,
    currentHp: source.currentHp,
    maxHp: source.maxHp,
  };
}

/**
 * Apply incoming storage roster: append, in-place patch, or full replace.
 * Returns a new array when identity/order changes; null when patched in place.
 */
export function applyStorageRosterUpdate(
  current: StorageCardSnapshot[],
  incoming: StorageCardSnapshot[],
): StorageCardSnapshot[] | null {
  if (isStorageRosterAppendOnly(current, incoming)) {
    const card = incoming[incoming.length - 1];
    if (!card) return null;
    return [...current, { ...card }];
  }
  if (!storageRosterIdentityEqual(current, incoming)) {
    return incoming.map((c) => ({ ...c }));
  }
  for (let i = 0; i < incoming.length; i++) {
    const cur = current[i];
    const inc = incoming[i];
    if (!cur || !inc) continue;
    const patched = patchStorageCardFields(cur, inc);
    if (patched !== cur) current[i] = patched;
  }
  return null;
}

/** Publish dedup for storage — roster order plus volatile/display fields (not keys alone). */
export function storageRosterPublishWouldChange(
  current: StorageCardSnapshot[],
  incoming: StorageCardSnapshot[],
): boolean {
  if (storageRosterSignature(current) !== storageRosterSignature(incoming)) return true;
  if (current.length !== incoming.length) return true;
  for (let i = 0; i < incoming.length; i++) {
    const a = current[i];
    const b = incoming[i];
    if (!a || !b) return true;
    if (a.isShiny !== b.isShiny || a.isShadow !== b.isShadow) return true;
    if (!creatureVolatileEqual(a, b)) return true;
    if (a.currentHp !== b.currentHp || a.maxHp !== b.maxHp) return true;
    if (a.cardOpacity !== b.cardOpacity) return true;
    if (a.draggable !== b.draggable) return true;
    if (a.isExpeditionEntry !== b.isExpeditionEntry) return true;
    if (a.expeditionName !== b.expeditionName) return true;
    if (a.expeditionStatus !== b.expeditionStatus) return true;
  }
  return false;
}

export function resourcesSnapshotWouldChange(
  prev: ResourceSnapshot,
  next: ResourceSnapshot,
): boolean {
  if (
    prev.pokedollars !== next.pokedollars
    || prev.essenceDust !== next.essenceDust
    || prev.talentRerolls !== next.talentRerolls
    || prev.talentChoices !== next.talentChoices
    || prev.questTokens !== next.questTokens
    || prev.combatTickets !== next.combatTickets
    || prev.triumphMarks !== next.triumphMarks
  ) {
    return true;
  }
  if (!shallowEqualShards(prev.shards, next.shards)) return true;
  const va = prev.activeVitamins;
  const vb = next.activeVitamins;
  return (
    va.hp !== vb.hp
    || va.attack !== vb.attack
    || va.spattack !== vb.spattack
    || va.defense !== vb.defense
    || va.spdefense !== vb.spdefense
    || va.speed !== vb.speed
    || va.all !== vb.all
  );
}
