import {
    canPlayCue,
    cueCooldownMs,
    type AudioFlags,
} from './audioCues.ts';
import {
    normalizeAudioPrefs,
    readAudioPrefs,
    writeAudioPrefs,
    type AudioPrefs,
    type AudioStorage,
} from './audioPrefs.ts';
import { preloadCueSamples } from './samples.ts';
import { readAudioBytes } from './readAudioBytes.ts';
import { playSfxCue } from './sfx.ts';
import { isMobileViewport } from '../ui/breakpoints.ts';

export type { AudioPrefs };

export interface AudioDirectorOptions {
    storage?: AudioStorage | null;
    now?: () => number;
    contextFactory?: () => AudioContext | null;
    flags?: () => AudioFlags;
    listen?: boolean;
}

type PrefsListener = (prefs: AudioPrefs) => void;

const IDLE_FLAGS: AudioFlags = { offline: false, afk: false };

function browserStorage(): AudioStorage | null {
    try {
        if (typeof localStorage === 'undefined') return null;
        return localStorage;
    } catch {
        return null;
    }
}

function canAttachBrowserListeners(): boolean {
    return typeof window !== 'undefined'
        && typeof window.addEventListener === 'function'
        && typeof document !== 'undefined'
        && typeof document.addEventListener === 'function';
}

function defaultContextFactory(): AudioContext | null {
    const host = globalThis as {
        AudioContext?: typeof AudioContext;
        webkitAudioContext?: typeof AudioContext;
    };
    const Ctor = host.AudioContext ?? host.webkitAudioContext;
    if (!Ctor) return null;
    try {
        return new Ctor();
    } catch {
        return null;
    }
}

export class AudioDirector {
    private storage: AudioStorage | null;
    private now: () => number;
    private contextFactory: () => AudioContext | null;
    private flags: () => AudioFlags;
    private prefs: AudioPrefs;
    private listeners = new Set<PrefsListener>();
    private lastCueAt = new Map<string, number>();
    private ctx: AudioContext | null = null;
    private sfxBus: GainNode | null = null;
    private unlocked = false;
    private removeListeners: (() => void) | null = null;
    private menuArmed = false;
    private menuUrl: string | null = null;
    private menuBytes: Promise<ArrayBuffer | null> | null = null;
    private menuVoices: { source: AudioBufferSourceNode; gain: GainNode | null }[] = [];
    private menuLoopTimer: ReturnType<typeof setTimeout> | null = null;
    private menuStarting = false;
    private menuResumePending = false;

    constructor(options: AudioDirectorOptions = {}) {
        this.storage = options.storage === undefined ? browserStorage() : options.storage;
        this.now = options.now ?? (() => Date.now());
        this.contextFactory = options.contextFactory ?? defaultContextFactory;
        this.flags = options.flags ?? (() => IDLE_FLAGS);
        this.prefs = readAudioPrefs(this.storage);
        const listen = options.listen ?? canAttachBrowserListeners();
        if (listen) this.attachBrowserListeners();
    }

    getPrefs(): AudioPrefs {
        return { ...this.prefs, cues: { ...this.prefs.cues } };
    }

    subscribe(listener: PrefsListener): () => void {
        this.listeners.add(listener);
        return () => this.listeners.delete(listener);
    }

    bindFlags(flags: () => AudioFlags): void {
        this.flags = flags;
    }

    setSfxVolume(value: number): void {
        this.patch({ sfx: value });
    }

    setMuted(muted: boolean): void {
        this.patch({ muted });
    }

    toggleMuted(): boolean {
        this.setMuted(!this.prefs.muted);
        return this.prefs.muted;
    }

    setCueEnabled(id: string, enabled: boolean): void {
        if (cueCooldownMs(id) == null) return;
        const cues = { ...this.prefs.cues };
        if (enabled) delete cues[id];
        else cues[id] = false;
        this.patch({ cues });
    }

    unlock(): void {
        this.unlocked = true;
        const ctx = this.ensureContext();
        if (!ctx) return;
        if (ctx.state === 'suspended') {
            void ctx.resume().catch(() => {});
        }
        this.tryStartMenuTrack();
    }

    /** Loop the save-slot theme until stopMenuTrack. Each repeat crossfades briefly. */
    startMenuTrack(url: string): void {
        this.menuArmed = true;
        if (this.menuUrl !== url) {
            this.menuUrl = url;
            this.menuBytes = null;
            this.stopMenuSource();
        }
        if (!this.menuBytes) {
            this.menuBytes = readAudioBytes(url);
        }
        this.tryStartMenuTrack();
    }

    stopMenuTrack(): void {
        this.menuArmed = false;
        this.menuStarting = false;
        this.stopMenuSource();
    }

    /** Let the slot theme fall away instead of cutting when the save finishes loading. */
    fadeOutMenuTrack(seconds = 2.4): void {
        this.menuArmed = false;
        this.menuStarting = false;
        if (this.menuLoopTimer != null) {
            clearTimeout(this.menuLoopTimer);
            this.menuLoopTimer = null;
        }
        const ctx = this.ctx;
        const fade = Number.isFinite(seconds) && seconds > 0 ? seconds : 2.4;
        if (!ctx || ctx.state !== 'running' || this.menuVoices.length === 0) {
            this.stopMenuSource();
            return;
        }
        const now = ctx.currentTime;
        const end = now + fade;
        for (const voice of this.menuVoices) {
            const gain = voice.gain;
            if (!gain) {
                try { voice.source.stop(end); } catch { /* already stopped */ }
                continue;
            }
            try {
                gain.gain.cancelScheduledValues(now);
                const level = gain.gain.value;
                const from = level > 0.0001 ? level : 0.0001;
                gain.gain.setValueAtTime(from, now);
                gain.gain.exponentialRampToValueAtTime(0.0001, end);
                voice.source.stop(end);
            } catch {
                try { voice.source.stop(); } catch { /* already stopped */ }
            }
        }
    }

    play(id: string): void {
        try {
            if (this.prefs.cues[id] === false) return;
            const now = this.now();
            if (!canPlayCue(id, this.flags(), this.prefs.muted, this.lastCueAt.get(id) ?? -Infinity, now)) return;
            const ctx = this.ensureContext();
            if (!ctx) return;
            this.lastCueAt.set(id, now);
            if (ctx.state === 'suspended') {
                void ctx.resume().catch(() => {});
            }
            const dest = this.sfxBus;
            if (!dest) return;
            playSfxCue(ctx, dest, id);
        } catch {
            /* audio is optional */
        }
    }

    dispose(): void {
        this.stopMenuTrack();
        this.removeListeners?.();
        this.removeListeners = null;
        const ctx = this.ctx;
        this.ctx = null;
        if (ctx && ctx.state !== 'closed') {
            void ctx.close().catch(() => {});
        }
    }

    private patch(partial: Partial<AudioPrefs>): void {
        const normalized = normalizeAudioPrefs({
            sfx: partial.sfx === undefined ? this.prefs.sfx : partial.sfx,
            muted: partial.muted === undefined ? this.prefs.muted : partial.muted,
            cues: partial.cues === undefined ? this.prefs.cues : partial.cues,
        });
        if (
            normalized.sfx === this.prefs.sfx
            && normalized.muted === this.prefs.muted
            && cuesEqual(normalized.cues, this.prefs.cues)
        ) return;
        this.prefs = normalized;
        writeAudioPrefs(this.storage, this.prefs);
        this.applyGains();
        for (const listener of this.listeners) listener(this.getPrefs());
    }

    private attachBrowserListeners(): void {
        if (!canAttachBrowserListeners()) return;
        const onGesture = () => this.unlock();
        const onVisibility = () => this.onVisibility();
        window.addEventListener('pointerdown', onGesture);
        window.addEventListener('keydown', onGesture);
        document.addEventListener('visibilitychange', onVisibility);
        this.removeListeners = () => {
            window.removeEventListener('pointerdown', onGesture);
            window.removeEventListener('keydown', onGesture);
            document.removeEventListener('visibilitychange', onVisibility);
        };
    }

    private onVisibility(): void {
        const ctx = this.ctx;
        if (!ctx) return;
        if (typeof document !== 'undefined' && document.hidden) {
            if (isMobileViewport() && ctx.state === 'running') void ctx.suspend().catch(() => {});
            return;
        }
        if (!this.unlocked) return;
        if (ctx.state === 'suspended') void ctx.resume().catch(() => {});
    }

    private stopMenuSource(): void {
        if (this.menuLoopTimer != null) {
            clearTimeout(this.menuLoopTimer);
            this.menuLoopTimer = null;
        }
        const voices = this.menuVoices;
        this.menuVoices = [];
        for (const voice of voices) {
            voice.source.onended = null;
            try { voice.source.stop(); } catch { /* already stopped */ }
            try { voice.source.disconnect(); } catch { /* already disconnected */ }
            try { voice.gain?.disconnect(); } catch { /* already disconnected */ }
        }
    }

    private queueMenuVoice(buffer: AudioBuffer, when: number, fadeIn: boolean): void {
        const ctx = this.ctx;
        const dest = this.sfxBus;
        if (!ctx || !dest || !this.menuArmed || ctx.state !== 'running') return;
        const source = ctx.createBufferSource();
        source.buffer = buffer;
        const duration = buffer.duration;
        const canLoop = Number.isFinite(duration) && duration > 0.3;
        const fade = canLoop ? Math.min(0.6, duration / 3) : 0;
        if (!canLoop || fade <= 0) {
            source.connect(dest);
            source.start(when);
            this.menuVoices.push({ source, gain: null });
            source.onended = () => {
                this.menuVoices = this.menuVoices.filter((voice) => voice.source !== source);
            };
            return;
        }
        const gain = ctx.createGain();
        source.connect(gain);
        gain.connect(dest);
        const end = when + duration;
        const fadeOutAt = end - fade;
        if (fadeIn) {
            gain.gain.setValueAtTime(0, when);
            gain.gain.linearRampToValueAtTime(1, when + fade);
        } else {
            gain.gain.setValueAtTime(1, when);
        }
        gain.gain.setValueAtTime(1, fadeOutAt);
        gain.gain.linearRampToValueAtTime(0, end);
        source.start(when);
        source.stop(end);
        this.menuVoices.push({ source, gain });
        source.onended = () => {
            this.menuVoices = this.menuVoices.filter((voice) => voice.source !== source);
            try { gain.disconnect(); } catch { /* already disconnected */ }
        };
        if (this.menuLoopTimer != null) clearTimeout(this.menuLoopTimer);
        const waitMs = Math.max(0, (fadeOutAt - ctx.currentTime) * 1000);
        this.menuLoopTimer = setTimeout(() => {
            this.menuLoopTimer = null;
            if (!this.menuArmed || this.ctx !== ctx) return;
            this.queueMenuVoice(buffer, Math.max(ctx.currentTime, fadeOutAt), true);
        }, waitMs);
    }

    private tryStartMenuTrack(): void {
        if (!this.menuArmed || this.menuVoices.length > 0 || this.menuStarting) return;
        const ctx = this.ensureContext();
        const dest = this.sfxBus;
        const bytesPromise = this.menuBytes;
        if (!ctx || !dest || !bytesPromise) return;
        if (ctx.state === 'suspended') {
            if (this.menuResumePending) return;
            this.menuResumePending = true;
            void ctx.resume().then(() => {
                this.menuResumePending = false;
                if (ctx.state === 'running') this.tryStartMenuTrack();
            }).catch(() => {
                this.menuResumePending = false;
            });
            return;
        }
        if (ctx.state !== 'running') return;
        this.menuStarting = true;
        void bytesPromise.then(async (bytes) => {
            this.menuStarting = false;
            if (!this.menuArmed || !bytes || this.menuVoices.length > 0 || this.ctx !== ctx) return;
            if (typeof ctx.decodeAudioData !== 'function' || typeof ctx.createBufferSource !== 'function') return;
            try {
                const buffer = await ctx.decodeAudioData(bytes.slice(0));
                if (!this.menuArmed || this.menuVoices.length > 0 || this.ctx !== ctx || ctx.state !== 'running') return;
                this.queueMenuVoice(buffer, ctx.currentTime, false);
            } catch {
                /* menu audio is optional */
            }
        }).catch(() => {
            this.menuStarting = false;
        });
    }

    private ensureContext(): AudioContext | null {
        if (this.ctx && this.ctx.state !== 'closed') return this.ctx;
        const ctx = this.contextFactory();
        if (!ctx) return null;
        this.ctx = ctx;
        if (typeof ctx.addEventListener === 'function') {
            ctx.addEventListener('statechange', () => {
                if (ctx.state === 'running') this.tryStartMenuTrack();
            });
        }
        const sfxBus = ctx.createGain();
        const master = ctx.createGain();
        master.gain.value = 1;
        sfxBus.connect(master);
        master.connect(ctx.destination);
        this.sfxBus = sfxBus;
        this.applyGains();
        preloadCueSamples(ctx);
        return ctx;
    }

    private applyGains(): void {
        const ctx = this.ctx;
        const sfxBus = this.sfxBus;
        if (!ctx || !sfxBus) return;
        const sfx = this.prefs.muted ? 0 : this.prefs.sfx;
        sfxBus.gain.setValueAtTime(sfx, ctx.currentTime);
    }
}

let singleton: AudioDirector | null = null;

export function getGameAudio(): AudioDirector {
    if (!singleton) singleton = new AudioDirector();
    return singleton;
}

export function installGameAudio(options: {
    flags: () => AudioFlags;
}): AudioDirector {
    const audio = getGameAudio();
    audio.bindFlags(options.flags);
    return audio;
}

export function playGameSfx(id: string): void {
    getGameAudio().play(id);
}

export function playSound(id: string): void {
    playGameSfx(id);
}

export function getAudioPrefs(): AudioPrefs {
    return getGameAudio().getPrefs();
}

export function subscribeAudio(listener: PrefsListener): () => void {
    return getGameAudio().subscribe(listener);
}

export function setSfxVolume(value: number): void {
    getGameAudio().setSfxVolume(value);
}

export function toggleAudioMuted(): boolean {
    return getGameAudio().toggleMuted();
}

export function setCueEnabled(id: string, enabled: boolean): void {
    getGameAudio().setCueEnabled(id, enabled);
}

function cuesEqual(a: Record<string, false>, b: Record<string, false>): boolean {
    const aKeys = Object.keys(a);
    const bKeys = Object.keys(b);
    if (aKeys.length !== bKeys.length) return false;
    return aKeys.every((key) => b[key] === false);
}

const globalHost = globalThis as { playSound?: (id: string) => void };
globalHost.playSound = playSound;
