/**
 * Prestige cost helpers for card snapshots (strict-index safe).
 * Decoupled from src/ui/tooltips.ts.
 */

import type { CreatureData } from '../types/creature.js';
import type { GameRuntime } from '../types/game.js';
import { ALL_ITEMS } from '../../constants/balance/shopAndAggregation.ts';
import { getAnchorCatchUpPrestigeCosts } from './regionalResonance.ts';

const PRESTIGE_STONE_ICON_URL =
  'https://raw.githubusercontent.com/PokeAPI/sprites/master/sprites/items/comet-shard.png';

export function cardGetPrestigeCost(
  gm: GameRuntime | null | undefined,
  prestige: number,
): number {
  if (gm && typeof gm.getPrestigeCost === 'function') {
    return gm.getPrestigeCost(prestige);
  }
  return Math.max(1, (Number(prestige) || 0) + 1);
}

export function cardGetPrestigeStoneCost(
  gm: GameRuntime | null | undefined,
  prestige: number,
): number {
  if (gm && typeof gm.getPrestigeStoneCost === 'function') {
    return gm.getPrestigeStoneCost(prestige);
  }
  return cardGetPrestigeCost(gm, prestige);
}

export function cardPrestigeStoneIconUrl(): string {
  const img = (ALL_ITEMS as Record<string, { img?: string }>).prestige_stone?.img;
  return img ?? PRESTIGE_STONE_ICON_URL;
}

/** Base prestige costs with regional resonance catch-up applied. */
export function cardResolvePrestigeCosts(
  gm: GameRuntime | null | undefined,
  creature: CreatureData,
): { shards: number; stones: number } {
  const prestige = Number(creature.prestige) || 0;
  const baseShards = Number(cardGetPrestigeCost(gm, prestige)) || 0;
  const baseStones = Number(cardGetPrestigeStoneCost(gm, prestige)) || 0;
  return getAnchorCatchUpPrestigeCosts(creature, gm, baseShards, baseStones);
}

const SHARD_ICON_URL = 'img/shard.png';

/** Tooltip HTML for prestige cost — matches storage card shard/stone row. */
export function buildPrestigeCostTooltipHtml(opts: {
  shardCount: number;
  shardCost: number;
  stoneCount: number;
  stoneCost: number;
}): string {
  const shards = Math.max(0, Math.floor(Number(opts.shardCount) || 0));
  const needShards = Math.max(1, Math.floor(Number(opts.shardCost) || 1));
  const stones = Math.max(0, Math.floor(Number(opts.stoneCount) || 0));
  const needStones = Math.max(1, Math.floor(Number(opts.stoneCost) || 1));
  const stoneIcon = cardPrestigeStoneIconUrl().replace(/"/g, '&quot;');
  return (
    `<div class="prestige-cost-tooltip">` +
    `<span class="prestige-cost-line prestige-cost-shards">` +
    `<img src="${SHARD_ICON_URL}" class="shard-inline" alt="">` +
    `${shards}/${needShards}</span>` +
    `<span class="prestige-cost-line prestige-cost-stones">` +
    `<img src="${stoneIcon}" class="shard-inline" alt="">` +
    `${stones}/${needStones}</span>` +
    `</div>`
  );
}
