/**
 * @file src/stores/combatSnapshotDiff.ts
 * Lightweight combat snapshot signature for publish dedup (no Svelte imports).
 */

import type { CombatSnapshot } from '../bus/snapshots.js';

function creatureCombatSig(
  c: CombatSnapshot['currentEnemy'],
): string {
  if (!c) return '';
  return [
    c.uid,
    c.name,
    c.level,
    c.maxHp,
    c.currentHp,
    c.isShiny ? 1 : 0,
    c.isBoss ? 1 : 0,
  ].join('|');
}

/** True if combat fields relevant to Svelte HUD would change. */
export function combatSnapshotWouldChange(
  current: CombatSnapshot,
  incoming: CombatSnapshot,
): boolean {
  if (current.state !== incoming.state) return true;
  if (current.playerHudCurrentHp !== incoming.playerHudCurrentHp) return true;
  if (current.playerHudMaxHp !== incoming.playerHudMaxHp) return true;
  if (current.combatSpeed !== incoming.combatSpeed) return true;
  if (current.captureMode !== incoming.captureMode) return true;
  if (current.autoMaster !== incoming.autoMaster) return true;
  if (creatureCombatSig(current.currentEnemy) !== creatureCombatSig(incoming.currentEnemy)) {
    return true;
  }
  if (
    creatureCombatSig(current.currentPlayerCreature)
    !== creatureCombatSig(incoming.currentPlayerCreature)
  ) {
    return true;
  }
  return false;
}
