/**
 * @file src/bus/publishHooks.ts
 * Thin helpers for publishing facade events from legacy game code.
 * Always invalidates the snapshot cache so payloads reflect the latest Game state.
 */

import { GameEventType as Evt } from './events.js';
import {
  publish,
  publishDeferred,
  buildCombatSnapshotOnly,
  invalidateSnapshotCache,
} from './pub.js';
import { game } from '../../gameManager.js';
import { playGameSfx } from '../audio/audioDirector.ts';
import {
  buildTeamHeaderStatsSnapshot,
  buildResourceSnapshot,
  buildStorageChangedPayload,
  buildTeamSnapshot,
  buildZoneSnapshot,
} from './gameFacade.js';
import { isSvelteStatsTab, renderStatsTab } from '../stats/statsUiBuilder.js';
import { getRegisteredResourcesSnapshot } from '../stores/resourcesSnapshotGetter.js';
import { getRegisteredTeamSnapshot } from '../stores/teamSnapshotGetter.js';
import { teamHeaderStatsWouldChange, teamSnapshotWouldChange } from '../stores/teamSnapshotDiff.js';
import { combatSnapshotWouldChange } from '../stores/combatSnapshotDiff.js';
import { resourcesSnapshotWouldChange, storageRosterPublishWouldChange } from '../stores/storeUtils.js';
import type { CombatSnapshot, ResourceSnapshot, TeamHeaderStatsSnapshot } from './snapshots.js';
import { notifyMiltankFarmChanged, resetMiltankFarmSnapshotDedupForTests } from '../lib/miltankFarmSnapshot.ts';
import { pensionSortKeyToStats } from '../lib/pensionSortUtils.ts';

function canPublishGameEvents(): boolean {
  return game != null;
}

export function publishResourcesChanged(): void {
  if (!canPublishGameEvents()) return;
  invalidateSnapshotCache();
  const incoming = buildResourceSnapshot();
  if (!incoming) return;
  const current = getRegisteredResourcesSnapshot();
  if (current && !resourcesSnapshotWouldChange(current, incoming)) return;
  publish({ type: Evt.RESOURCES_CHANGED, resources: incoming });
}

function currentHeaderFromStore(): TeamHeaderStatsSnapshot | null {
  const t = getRegisteredTeamSnapshot();
  if (!t) return null;
  return {
    teamStats: t.teamStats,
    passiveGainsPerSec: t.passiveGainsPerSec,
    headerStatBoosted: t.headerStatBoosted,
  };
}

let _lastPublishedTeamHeaderSig: string | null = null;

function teamHeaderPublishSignature(header: TeamHeaderStatsSnapshot): string {
  return JSON.stringify({
    teamStats: header.teamStats,
    passiveGainsPerSec: header.passiveGainsPerSec,
    headerStatBoosted: header.headerStatBoosted,
  });
}

export function publishTeamHeaderStatsChanged(): void {
  if (!canPublishGameEvents()) return;
  const header = buildTeamHeaderStatsSnapshot();
  const sig = teamHeaderPublishSignature(header);
  if (_lastPublishedTeamHeaderSig === sig) return;
  const current = currentHeaderFromStore();
  if (current && !teamHeaderStatsWouldChange(current, header)) {
    _lastPublishedTeamHeaderSig = sig;
    return;
  }
  _lastPublishedTeamHeaderSig = sig;
  publish({ type: Evt.TEAM_HEADER_STATS, header });
}

/** @internal Vitest */
export function resetTeamHeaderPublishDedupForTests(): void {
  _lastPublishedTeamHeaderSig = null;
}

export function publishTeamChanged(): void {
  if (!canPublishGameEvents()) return;
  invalidateSnapshotCache();
  const incoming = buildTeamSnapshot({ withStorageRoster: false });
  if (!incoming) return;
  const current = getRegisteredTeamSnapshot();
  if (current) {
    incoming.storageRoster = current.storageRoster;
    incoming.storageFilteredCountLabel = current.storageFilteredCountLabel;
    incoming.storageShowEmptyFiltered = current.storageShowEmptyFiltered;
    incoming.storageSortStack = current.storageSortStack.map((entry) => ({ ...entry }));
  }
  if (current && !teamSnapshotWouldChange(current, incoming)) return;
  publish({ type: Evt.TEAM_CHANGED, team: incoming });
  publishBagEggMetaChanged();
  const runtime = game;
  if (runtime && typeof runtime.refreshBonusUIIfOpen === 'function') runtime.refreshBonusUIIfOpen();
}

type StoragePublishPayload = NonNullable<ReturnType<typeof buildStorageChangedPayload>>;
let lastStoragePublish: StoragePublishPayload | null = null;

/** @internal Vitest only */
export function resetStoragePublishDedupForTests(): void {
  lastStoragePublish = null;
}

export function publishStorageChanged(): void {
  if (!canPublishGameEvents()) return;
  publishDeferred(Evt.STORAGE_CHANGED, () => {
    invalidateSnapshotCache();
    const payload = buildStorageChangedPayload(lastStoragePublish?.storageRoster ?? null);
    if (!payload) return null;
    if (
      lastStoragePublish &&
      !storageRosterPublishWouldChange(lastStoragePublish.storageRoster, payload.storageRoster) &&
      lastStoragePublish.storageFilteredCountLabel === payload.storageFilteredCountLabel &&
      lastStoragePublish.storageShowEmptyFiltered === payload.storageShowEmptyFiltered
    ) {
      return null;
    }
    lastStoragePublish = payload;
    const gm = game;
    if (gm?.pokePelagoState?.unlocked || gm?.unlockedFeatures?.pokePelago) {
      void import('../lib/pokePelagoSnapshot.js').then((m) => m.notifyPokePelagoChanged(gm, { force: true }));
    }
    return {
      type: Evt.STORAGE_CHANGED,
      storageRoster: payload.storageRoster,
      storageFilteredCountLabel: payload.storageFilteredCountLabel,
      storageShowEmptyFiltered: payload.storageShowEmptyFiltered,
    };
  });
}

export function publishPensionSortChanged(): void {
  if (!canPublishGameEvents()) return;
  const gm = game;
  if (!gm) return;
  publish({
    type: Evt.PENSION_SORT_CHANGED,
    pensionSortKey: gm.pensionSortKey ?? null,
    pensionSortOrder: gm.pensionSortOrder ?? 'desc',
    pensionSortStats: gm.pensionSortStats && gm.pensionSortStats.length > 0 ? [...gm.pensionSortStats] : (gm.pensionSortKey ? pensionSortKeyToStats(gm.pensionSortKey) : []),
  });
}

export function publishStorageSortChanged(): void {
  if (!canPublishGameEvents()) return;
  const gm = game;
  if (!gm) return;
  const storageSortStack = Array.isArray(gm.storageSortStack)
    ? gm.storageSortStack.map((entry) => ({ ...entry }))
    : [];
  publish({
    type: Evt.STORAGE_SORT_CHANGED,
    storageSortStack,
    storageSortByBaseStats: !!gm.storageSortByBaseStats,
  });
}

let lastCombatPublish: CombatSnapshot | null = null;

/** @internal Vitest only */
export function resetCombatPublishDedupForTests(): void {
  lastCombatPublish = null;
}

export function publishCombatStateChanged(): void {
  if (!canPublishGameEvents()) return;
  publishDeferred(Evt.COMBAT_STATE_CHANGED, () => {
    const combat = buildCombatSnapshotOnly();
    if (!combat) return null;
    if (lastCombatPublish && !combatSnapshotWouldChange(lastCombatPublish, combat)) {
      return null;
    }
    lastCombatPublish = combat;
    const gm = game;
    if (gm?.gymTrainerState?.active && gm.gymTrainerState.isFarmThreat) {
      publishMiltankFarmChanged();
    }
    return {
      type: Evt.COMBAT_STATE_CHANGED,
      state: combat.state,
      combat,
    };
  });
}

export function publishCombatStarted(): void {
  if (!canPublishGameEvents()) return;
  const combat = buildCombatSnapshotOnly();
  if (!combat) return;
  publish({ type: Evt.COMBAT_STARTED, snapshot: combat });
}

let lastStatsHtml = '';
let lastStatsTab = '';

/** @internal Vitest only — resets STATS_CHANGED dedup cache. */
export function resetStatsPublishDedupForTests(): void {
  lastStatsHtml = '';
  lastStatsTab = '';
}

function statsPublishDedupKey(
  gm: import('../types/game.js').GameRuntime,
  activeTab: string,
  legacyHtml: string,
): string {
  if (!isSvelteStatsTab(activeTab)) return legacyHtml;
  if (activeTab === 'combat') {
    const mode = gm.statsUi?.radarMode ?? 'team';
    return `combat|${mode}`;
  }
  return `svelte|${activeTab}`;
}

export function publishStatsChanged(tab?: string, opts?: { force?: boolean }): void {
  if (!canPublishGameEvents()) return;
  const gm = game as import('../types/game.js').GameRuntime;
  if (!gm) return;
  if (tab && gm.statsUi) gm.statsUi.tab = tab;
  const activeTab = gm.statsUi?.tab ?? 'combat';
  const display = document.getElementById('statsDisplay');
  if (!display) return;

  let html = '';
  if (!isSvelteStatsTab(activeTab)) {
    renderStatsTab(gm, display);
    html = display.innerHTML;
  }
  // Svelte tabs: do not touch #statsDisplay — innerHTML clears mounted tab components.

  const dedupKey = statsPublishDedupKey(gm, activeTab, html);
  if (!opts?.force && activeTab === lastStatsTab && dedupKey === lastStatsHtml) return;
  lastStatsTab = activeTab;
  lastStatsHtml = dedupKey;
  publish({ type: Evt.STATS_CHANGED, tab: activeTab, html });
}

