export function publishZRingChanged(): void {
  if (!canPublishGameEvents()) return;
  const gm = game as import('../types/game.js').GameRuntime;
  const state = gm.zRingState;
  publish({
    type: Evt.Z_RING_CHANGED,
    unlockedCount: state?.unlockedCrystalIds?.length ?? 0,
    activeCrystalId: state?.activeCrystalId ?? null,
  });
  if (gm?.pokePelagoState?.unlocked || gm?.unlockedFeatures?.pokePelago) {
    void import('../lib/pokePelagoSnapshot.js').then((m) => m.notifyPokePelagoChanged(gm, { force: true }));
  }
}

