export function publishZoneChanged(): void {
  if (!canPublishGameEvents()) return;
  invalidateSnapshotCache();
  const zone = buildZoneSnapshot();
  if (!zone) return;
  publish({
    type: Evt.ZONE_CHANGED,
    zone: zone.currentZone,
    region: zone.currentRegion,
    maxReachedZone: zone.maxReachedZone,
    zoneName: zone.zoneName,
  });
}

const MODALS_WITH_OWN_CUE = new Set(['eggHatchModal', 'captureModal', 'evolutionModal']);

export function publishModalOpened(modalId: string): void {
  if (!MODALS_WITH_OWN_CUE.has(modalId)) playGameSfx('modal');
  publish({ type: Evt.MODAL_OPENED, modalId });
}

export function publishModalClosed(modalId: string): void {
  publish({ type: Evt.MODAL_CLOSED, modalId });
}
