/// <reference types="svelte" />
/**
 * Store: main tab — active secondary tab (no facade import; safe for navigation.ts).
 */

class MainTabStore {
  activeMainTab = $state('boutiqueTab');
  isTeamRocketTabActive = $state(false);
}

export const mainTab = new MainTabStore();

export function syncMainTabState(tabName: string): void {
  mainTab.activeMainTab = `${tabName}Tab`;
  mainTab.isTeamRocketTabActive = tabName === 'teamrocket';
}
