/**
 * @file src/stores/teamSnapshotDiff.ts
 * Pure comparison for TEAM_CHANGED publish deduplication (no facade / Svelte imports).
 */

import type { TeamHeaderStatsSnapshot, TeamSnapshot } from '../bus/snapshots.js';
import { resonancePreviewSignature } from '../lib/regionalResonance.ts';
import {
  creatureVolatileEqual,
  storageRosterSignature,
  teamRosterIdentityEqual,
} from './storeUtils.js';
import { storageSortStacksEqual } from '../lib/storageSortUtils.js';

function statBlockEqual(a: TeamSnapshot['teamStats'], b: TeamSnapshot['teamStats']): boolean {
  return (
    a.hp === b.hp &&
    a.attack === b.attack &&
    a.spattack === b.spattack &&
    a.defense === b.defense &&
    a.spdefense === b.spdefense &&
    a.speed === b.speed
  );
}

/** Passive gains use floats; compare at milli precision to avoid publish storms. */
function passiveGainsEqual(
  a: TeamSnapshot['passiveGainsPerSec'],
  b: TeamSnapshot['passiveGainsPerSec'],
): boolean {
  const keys = ['hp', 'attack', 'spattack', 'defense', 'spdefense', 'speed'] as const;
  for (const k of keys) {
    if (Math.round((a[k] ?? 0) * 1000) !== Math.round((b[k] ?? 0) * 1000)) return false;
  }
  return true;
}

function headerBoostedEqual(
  boosted: TeamSnapshot['headerStatBoosted'],
  bBoosted: TeamSnapshot['headerStatBoosted'],
): boolean {
  const keys = Object.keys(boosted) as (keyof TeamSnapshot['headerStatBoosted'])[];
  for (const k of keys) {
    if (boosted[k] !== bBoosted[k]) return false;
  }
  return true;
}

function faintedEqual(a: number[], b: number[]): boolean {
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i] !== b[i]) return false;
  }
  return true;
}

/** True if header-only fields would change (no roster comparison). */
export function teamHeaderStatsWouldChange(
  current: TeamHeaderStatsSnapshot,
  incoming: TeamHeaderStatsSnapshot,
): boolean {
  if (!statBlockEqual(current.teamStats, incoming.teamStats)) return true;
  if (!passiveGainsEqual(current.passiveGainsPerSec, incoming.passiveGainsPerSec)) return true;
  if (!headerBoostedEqual(current.headerStatBoosted, incoming.headerStatBoosted)) {
    return true;
  }
  return false;
}

/** True if applying `incoming` would change any field in `current` store snapshot. */
export function teamSnapshotWouldChange(current: TeamSnapshot, incoming: TeamSnapshot): boolean {
  if (current.playerTeam.length !== incoming.playerTeam.length) return true;
  if (!teamRosterIdentityEqual(current.playerTeam, incoming.playerTeam)) return true;
  for (let i = 0; i < incoming.playerTeam.length; i++) {
    const a = current.playerTeam[i];
    const b = incoming.playerTeam[i];
    if (!a || !b) {
      if (a !== b) return true;
      continue;
    }
    if (!creatureVolatileEqual(a, b)) return true;
  }
  if (current.pension.length !== incoming.pension.length) return true;
  if (!teamRosterIdentityEqual(current.pension, incoming.pension)) return true;
  for (let i = 0; i < incoming.pension.length; i++) {
    const a = current.pension[i];
    const b = incoming.pension[i];
    if (!a || !b) {
      if (a !== b) return true;
      continue;
    }
    if (!creatureVolatileEqual(a, b)) return true;
  }
  if (current.storageCount !== incoming.storageCount) return true;
  if (!statBlockEqual(current.teamStats, incoming.teamStats)) return true;
  if (!statBlockEqual(current.passiveGainsPerSec, incoming.passiveGainsPerSec)) return true;
  if (current.maxTeamSize !== incoming.maxTeamSize) return true;
  if (current.maxPensionSlots !== incoming.maxPensionSlots) return true;
  if (current.teamCountLabel !== incoming.teamCountLabel) return true;
  if (current.pensionCountLabel !== incoming.pensionCountLabel) return true;
  if (!headerBoostedEqual(current.headerStatBoosted, incoming.headerStatBoosted)) {
    return true;
  }
  if (current.activeCreatureIndex !== incoming.activeCreatureIndex) return true;
  if (!faintedEqual(current.faintedTeamIndices, incoming.faintedTeamIndices)) return true;
  if (current.teamSpritesOnly !== incoming.teamSpritesOnly) return true;
  if (current.teamContributionRatePercent !== incoming.teamContributionRatePercent) return true;
  if (current.pensionTransferRatePercent !== incoming.pensionTransferRatePercent) return true;
  if (
    current.labels.levelShort !== incoming.labels.levelShort ||
    current.labels.viewDetails !== incoming.labels.viewDetails ||
    current.labels.teamContributionPrefix !== incoming.labels.teamContributionPrefix ||
    current.labels.pensionContributionPrefix !== incoming.labels.pensionContributionPrefix
  ) {
    return true;
  }
  if (storageRosterSignature(current.storageRoster) !== storageRosterSignature(incoming.storageRoster)) {
    return true;
  }
  if (current.storageFilteredCountLabel !== incoming.storageFilteredCountLabel) return true;
  if (current.storageShowEmptyFiltered !== incoming.storageShowEmptyFiltered) return true;
  if (!storageSortStacksEqual(current.storageSortStack ?? [], incoming.storageSortStack ?? [])) {
    return true;
  }
  if (!!current.storageSortByBaseStats !== !!incoming.storageSortByBaseStats) return true;
  if (
    resonancePreviewSignature(current.resonancePreview) !==
    resonancePreviewSignature(incoming.resonancePreview)
  ) {
    return true;
  }
  if (current.ultimateSlotUnlocked !== incoming.ultimateSlotUnlocked) return true;
  if ((current.ultimateSlot?.uid ?? null) !== (incoming.ultimateSlot?.uid ?? null)) return true;
  if (current.ultimateSlotTransferPercent !== incoming.ultimateSlotTransferPercent) return true;
  if (!statBlockEqual(current.ultimateSlotBonus, incoming.ultimateSlotBonus)) return true;
  return false;
}
